(window.GIM_TUR_P=window.GIM_TUR_P||{})["YD.7"]={"from":389,"s":[["\u0010c0\u0011\u0010y0\u0011אבל אסור לכבס כסותו כל ז' ימים אפילו במים לבד ולאחר ז' מותר \u0010y1\u0011וריב\"א אסר כל ל' \u0010y2\u0011ובספר המצות כתב מותר ללבוש חלוק לבן מיד אחר ז' והעולם נהגו בו איסור ונוהגין שאדם אחד לובשם תחילה ואח\"כ לובשם הוא וזה המנהג עיקר ע\"כ \u0010c1\u0011\u0010y3\u0011ואיני יודע טעם למנהג זה דאפי' גיהוץ מותר בישנים כ\"ש כיבוס \u0010c2\u0011\u0010y4\u0011וכשם שאסור לכבס כך אסור ללבוש המכובסים מקודם לכן אפי' ישינים ואצ\"ל שאסור ללבוש חדשים כת' הרמב\"ן ראיתי על שם רש\"י שהתיר ללבוש בז' אבלו' חלוק המכובס מקודם לכן ואינו נכון \u0010y5\u0011וגם הסדינין והמצעות של מטה אסור לכבסן ולהציע המכובסין \u0010c3\u0011\u0010y6\u0011וכן מטפחות הידים והשלחן אע\"פ שמותר לכבסן במועד \u0010y7\u0011וכן בכל אלו ששנינו שמותרים לכבס במועד כגון היוצא מבית השביה ומבית האסורים ומנודה שהתירו לו חכמים והנשאל לחכם והותר והבא ממדינת הים שהלך להרויח ולא היה לו פנאי לגלח אסורין בימי אבלו שאם אירעו אחד מהם קודם האבילות ונכנס מיד לתוך האבילות אסור לכבס אא\"כ אירעו אחד מהם ותכפוהו מיד שני האבלות זה אחר זה אז מותר לכבס בין בנתר בין בחול \u0010y8\u0011אפילו תוך ז' \u0010y9\u0011ובלבד שיעשנו בצינעא בתוך ביתו ואחר שתכפוהו אביליו זה אחר זה מכבס במים אבל לא בנתר וחול \u0010c4\u0011\u0010y10\u0011כתב הרמב\"ן ז\"ל קרוב בעיני הדבר לומר שאסור בכלים חדשים צבועים ובישנים מכובסים היוצאים מתחת המכבש תוך ז' אע\"פ שאין בהם משום גזירת שלשים ומותרים לאחר ז' תוך ז' אסורין וכתב עוד הרבה כתבו בענין לכבס ולהניח ואני אומר שאסור מצד מלאכה בין ע\"י עצמו בין על ידי אחרים ואם היה כסותו בקבולת ביד אחרים מכבסין אותו כדרכו כמו שאר מלאכות בתלוש שביד אחרים בקבולת ולאחר ז' אע\"פ שהוא אסור בגיהוץ מגהץ בין לעצמו בין לאחרים \u0010c5\u0011\u0010y11\u0011תניא כל יום לגיהוץ \u0010y12\u0011ופי' רבינו האי עבורי חומרתא אמנא \u0010y13\u0011אחד בכלים חדשים אחד בישנים יוצאת מתחת המכבש רבי אומר לא אסרו אלא בחדשים בלבד ר' אליעזר ברבי שמעון אומר לא אסרו אלא בחדשים לבנים והלכתא כוותיה הלכך ישנים אפי' לבנים או צבועין אפי' חדשים מותרים שאין איסור אלא בלבנים חדשים המגוהצים וכתב הראב\"ד שאפי' חדשים לבנים המגוהצים מותרים אא\"כ נתנן במכבש אחר הגיהוץ ומטעם זה התיר חלוק פשתן שחתכו אפי' מהיריעה של התגר אף ע\"פ שהתגר כובש היריעה ואינה מניחה לילך לכאן ולכאן כיון שביד החייט התופרה יוצאה לכאן ולכאן ואינו מקפיד בכך יוצאה מכלל מכבש לא משכחת כלים חדשים יוצאין מתחת המכבש אלא טלית וסדין שתפרו תחילה ונתנו לכובש וכבשו תחת המכבש אבל הרמב\"ן כתב דחדשים אסורים אפילו אינן כבושים במכבש שלא הוזכר מכבש אלא בישנים וכ\"כ הרמב\"ם וכן הוא מסקנת א\"א הרא\"ש ז\"ל \u0010c6\u0011\u0010y14\u0011וחדשים לבנים מגוהצים אסורים ללבוש אפי' הן של פשתן אע\"ג דגבי ט\"ב אמרינן כלי פשתן אין בהם משום גיהוץ היינו דווקא לגוהצן ולהניחן אבל אסור ללבוש המגוהצים \u0010y15\u0011הלכך הכא שאין איסור גיהוץ אלא בלבישה שהרי לגהץ ולהניח מותר בין בעצמו בין על ידי אחרים הלכך אין חילוק בין של צמר לפשתים והרמב\"ם כתב דכלי פשתן אין בהם משום גיהוץ וכתב עליו הרמב\"ן ואין זה נכון \u0010y16\u0011ואנו דגיהוץ שלנו ככיבוס שלהם הכל מותר לאחר ז' \u0010y17\u0011ירושלמי על כל המתים אסור בגיהוץ עד ל' יום ובאביו ובאמו י\"ב חדש ובאבל רבתי (פ\"ט) תניא עד שיגיע הרגל ויגערו בו חביריו \u0010c7\u0011וכתב הרמב\"ן ובגמרא דידן לא שוי חילוק בין גיהוץ דאביו ואמו לשאר קרובים \u0010y18\u0011\u0010y19\u0011\u0010y20\u0011וכן הרמב\"ם לא חילק בהם ומיהו סמכינן אירושלמי ואברייתא דאבל רבתי דגמרי גיהוץ מתספורת הלכך אסור באביו עד שיגיע הרגל אחר ל' יום ויגערו בו חביריו לומר לו לבוש כלים המגוהצים לכבוד הרגל וכן כתב א\"א הרא\"ש ז\"ל:",["אבל אסור לכבס כסותו כל ז' ימים אפי' במים לבד בסוף פ\"ק דתענית [יג.] ובפרק אלו מגלחין (מועד קטן יז:) תניא תכפוהו אבליו מכבס כסותו במים א\"ר חסדא במים אבל לא בנתר ולא בחול ואמר רב חסדא זאת אומרת אבל אסור בתכבוסת כלומר אסור לכבס כסותו כל ז' במים ואע\"פ שאינו גיהוץ שכל כביסה אסור לאבל כל שבעה כ\"כ הרמב\"ן בת\"ה דלא מיתסר אלא תוך ז' וכ\"נ מדברי הרמב\"ם בפרק ה':","ומ\"ש וריב\"א אסר כל ל' כ\"כ התוס' בשמו בפרק אלו מגלחין (מועד קטן כח.) וטעמא מדתניא במסכת שמחות [פ\"ז] ח' ימים קודם לרגל אם רצה לספר ולכבס הרשות בידו לא ספר ולא כבס ערב הרגל אסור לספר ולכבס עד שישלמו ל' ותניא נמי בתוס' כל אלו שאמרו מותר לכבס במועד אסור בתוך ל' יום של אבל והתוס' כתבו דאיכא למימר דכיבוס דקתני בהנך ברייתות היינו גיהוץ:","ומ\"ש בשם ספר המצות הוא בסמ\"ק וז\"ל חלוק מותר ללבוש מיד אחר ז' והעולם נהגו איסור בדבר ונהגו העם להלבישו לאחר שעה אחת וללובשה מיד אחר ז' והמנהג עיקר משום דכל הלכה רופפת בידך הלך אחר המנהג והמרדכי כתב כדברי סמ\"ק שנהגו העם להלביש כלים לבנים לאדם אחר טרם ילבשם האבל: \u0005ב\"ה כתב הריב\"ש בתשובה סי' ס\"ז שכן היה מנהג ברצלוני:\u0006","ומ\"ש רבינו שאיני יודע טעם למנהג זה לא ידעתי על מה תמה דדילמא ס\"ל כריב\"א דאסר כל ל' אפילו בכיבוס ומ\"מ לענין הלכה הו\"ל ריב\"א יחידאה ועוד שהוא מחמיר באבל ולא קי\"ל כוותיה:","ומ\"ש וכשם שאסור לכבס כך אסור ללבוש המכובסים מקודם לכן כ\"כ הרמב\"ן בת\"ה וכתב שמ\"ש על שם רש\"י אינו נכון שכשאמרו אסור בכביסה לא לכבס בלבד אמרו שלא מפני איסור מלאכה נגעו בה אלא שאסור ללבוש וכן בגיהוץ לענין לביש' אסרו ולבישה הזכירו בין שכבסן עכשיו בין שכבסן מקודם לכן וכן שבת שחל ט\"ב להיות בתוכה לענין כלי פשתן לבישתן אסרו ואפילו במכובסין מתחילה משמע:","ומ\"ש וגם הסדינים והמצעות של מטה אסור לכבסן ולהציע המכובסים כ\"כ הרא\"ש בפרק אלו מגלחין בשם הראב\"ד וכ\"כ בת\"ה בשמו ובשם חכמי הצרפתים.","ומה שאסר גם במטפחות הידים כ\"כ בת\"ה וז\"ל ומטפחות ידים נמי אסרו ואע\"פ שמותרים במועד כל אלו שאמרו מותרים לגלח במועד אסורים לגלח בימי אבלן וה\"ה לכיבוס:","ומ\"ש וכן בכל אלו ששנינו בהם שמותרין לכבס במועד וכולי בפרק אלו מגלחין (מועד קטן יז:) ת\"ר כל אלו שאמרו מותרים לגלח במועד מותרים לגלח בימי אבלן והתניא אסורים אמר רב חסדא אמר רבי שילא כי תניא ההיא בשתכפוהו אביליו אי בשתכפוהו אביליו מאי איריא כל אלו שאמרו אפילו כ\"ע נמי דתניא תכפוהו אביליו זה אחר זה הכביד שערו מיקל בתער ומכבס כסותו במים הא איתמר עלה אמר רב חסדא בתער ולא במספרים במים ולא בנתר ולא באהל א\"ר חסדא זאת אמרת אבל אסור בתכבוסת ע\"כ וילפינן דין כיבוס מדין גילוח וכ\"כ בת\"ה:","\u0003ומ\"ש אפי' תוך ז' כ\"כ הגה\"מ פ\"ז:\u0004 ","ומ\"ש ובלבד שיעשנו בצינעא בתוך ביתו כ\"כ הרמב\"ן בת\"ה והמרדכי במ\"ק בשם התוספתא וכתבו הגהות פ\"ו ומיהו גיהוץ ותספורת אסור אפילו אחר ז' ולא התיר אלא להקל בתער כדמוכח בירושלמי אי נמי י\"ל דכולה מתניתין בז' מיירי אבל תוך ל' ותכפוהו אביליו אפי' גיהוץ ותספורת מותר כדמוכח בתוספתא רק שיעשנו בצנעה כתוב בהלכות שמחות מותרין הגדולים לספר הקטנים שמת אביהם או לכבס בגדיהם :","כתב הרמב\"ן קרוב הדבר לומר שאסור בכלים חדשים צבועים וכולי בת\"ה וכתב הטעם משום דפלוגתא דתנאי שכתב רבינו לקמן בסמוך לת\"ק ולרבי אסורים כל ל' ולא הקל ר\"א ברבי שמעון אלא בגזירת ל' אבל בגזירת ז' נחמיר דומיא דכיבוס מים בישנים ולבנים: וכתב עוד הרבה כתבו בענין לכבס ולהניח ואני אומר שאסור מצד מלאכה וכולי ג\"ז בת\"ה. ועל מה שהתיר גיהוץ לאחר ז' אפי' לעצמו כתב ואינו ענין לשבת של ט\"ב דהתם גזרו עליהם מפני שאיסורו שוה בכל אדם שלא יעשו מלאכה שאינה צריכה ויבאו בה לידי חשד או לידי תקלה ועוד דשבת של ט\"ב חמור הוא מל' של אבל לענין כיבוס מפני שהוא אבילות דרבים כדאיתא בפרק החולץ (יבמות מג.) ואין למדין קל מחמור להחמיר עליו והכי תניא באבל מותר להוליך כלים לגיהוץ תוך ל' עכ\"ל וענין היתר כיבוס בגדים תוך שבעה ללבוש לאחר שבעה כתוב בהג\"א בשם א\"ז דלדידן מותר דאפילו גיהוץ שלנו אינו אלא ככיבוס שלהם ומ\"מ כתב שלא ראה נוהגים היתר והא ודאי יש להקשות עליו דתיפוק ליה דמשום מלאכה אסור וכמ\"ש הרמב\"ן ז\"ל ואע\"פ שאיפשר להעמיד דברי א\"ז בקובר מתו בתוך הרגל שבז' שהוא מונה אחר הרגל עבדיו עושין בצינעא מיהו כיון שכתב שלא ראה נוהגים היתר אין להקל :","תניא כל שלשים יום לגיהוץ בפרק אלו מגלחין (מועד קטן כג.):","ומ\"ש בשם רבינו האי דגיהוץ היינו עבורא חומרתא אמנא כ\"כ בת\"ה וסיים בה ובלשון ישמעאל צקא' וחומרתא מצקלא' ונ\"י פירש דגיהוץ היינו מים בעפר או בנתר ובורית:","\u0003ומ\"ש אחד כלים חדשים ואחד ישנים יוצאים מתחת המכבש וכו'\u0004 שם בפרק אלו מגלחין בברייתא וכתבו הרי\"ף והרא\"ש והרמב\"ן ז\"ל והלכתא כר\"א בר\"ש דהא רבה נפק בחימוציתא רומיתא סומקתא חדתא כר\"א ברבי שמעון. ומ\"ש בשם הראב\"ד כ\"כ בשמו הרמב\"ן בת\"ה והרא\"ש בפרק אלו מגלחין וז\"ל באבל רבתי [פ\"ז] כיצד לגיהוץ אסור ללבוש כלים מגוהצים אלו הם כלים המגוהצים כלים היוצאים מתחת המכבש מהך ברייתא משמע דאין גיהוץ אסור אלא בכלים שנותנים אותם תחת המכבש אחר הגיהוץ אבל כלים שאין עומדין תחת המכבש אחר הגיהוץ מותר ללובשן תוך שלשים יום שאין הנאת גיהוץ אלא בכלים הכובשין אותן במכבש אחר הגיהוץ וקי\"ל כר\"א בר' שמעון דאמר לא אסרו אלא כלים חדשים היוצאים מתחת המכבש נמצא שאסור ללבוש חלוק של פשתן שחתך אותו מיריעה של תגרים שזהו ודאי יוצא מתחת המכבש שאין התגר מניח יריעותיו ללכת כאן וכאן להתכפל או שמא י\"ל כיון שחתכו מן היריעה והחייט תופרו הוא הולך לכאן ולכאן ואינו מקפיד עליו כלום כבר יצא מתורת מכבש וכלים חדשים שיוצאים מתחת המכבש שאסורים כגון טלית וסדין אי נמי כגון שתפרן תחילה ונתנן לכובש לכובשן אחר הגיהוץ עכ\"ל וכתב עליו הרמב\"ן ואין דעתנו מקבלת זו שכתב בחדשים דבעינן בהו יוצאים מתחת המכבש דהול\"ל אחד כלים חדשים ואחד כלים ישנים והוא שיוצאים מתחת המכבש מדקתני היוצאים מתחת המכבש אישנים קאי ועוד דלא קתני ברבי ור\"א בר\"ש לא אסרו אלא כלים חדשים וחדשים ולבנים היוצאים מתחת המכבש אלמא כל דלית ליה ישנים לא מדכר מכבש והא דאבל רבתי בישנים תניא דת\"ק התם לא מדכר חדשים דלא איצטריך ורשב\"א פליג עליהם ואמר לא אסרו ישנים דמכבש אלא חדשים ולא שחקים לבנים ולא צבועים וכ\"ד הרמב\"ם בדבריו שלא הזכיר מכבש כלל והרא\"ש כתב אחר דברי הראב\"ד ז\"ל והרמב\"ם לא הזכיר מכבש כלל כי הוא ר\"ל דמכבש לא קאי אלא אישינים אבל חדשים לא בעי מכבש ע\"כ ומשמע לרבינו שמאחר שהביא דעת הרמב\"ם בסוף כך הוא הסכמתו:","\u0003ולענין הלכה הו\"ל הראב\"ד יחידאה לגב' הנך רבוותא והלכה כרבים:\u0004 ","וחדשים לבנים מגוהצים אסורים ללבוש אפילו הם של פשתן אע\"ג דגבי ט\"ב אמרינן כלי פשתן אין בהם משום גיהוץ היינו דוקא לגוהצן ולהניחן אבל אסור ללבוש המגוהצין כן כתב הרמב\"ן בתורת האדם והרא\"ש בפרק אלו מגלחין בשם הראב\"ד ז\"ל ודבר פשוט הוא שכל זה אחר ז' ותוך ל' דאילו תוך ז' אסור לגהץ אפי' להניח וסמ\"ג כתב וז\"ל כתב רבינו משה כלי פשתן אין בהם משום גיהוץ וגם בפרק אלו מגלחין (מועד קטן יח.) אמרו משום רבי יוחנן כלי פשתן משום שמתקלקלין מותר לכבסן במועד וה\"ה באבל עכ\"ל ומדנקט לישנא דכיבוס משמע דתוך שבעה איירי:","\u0003ומ\"ש עוד רבינו הלכך הכא שאין איסור גיהוץ אלא בלבישה וכו'\u0004 הלכך אין חילוק בין צמר לפשתים לשון שא\"צ ובלתי מסודר הוא דממ\"ש בסמוך משמע שפיר דאין חילוק בין צמר לפשתים ומ\"ש בשם הרמב\"ם הוא בפ\"ו ומה שכתב בשם הרמב\"ן שכתב עליו שאינו נכון הוא בת\"ה:","כתב רבינו ירוחם נ\"ל שאסור להציע סדין מגוהץ תחתיו כמו שאסור ללבוש וכתב עוד פשוט באבל רבתי כי דוקא מלבוש אבל כובע של ראש וכיוצא בו מותר ללבשו מגוהצים וז\"ל אבל רבתי בפ\"ז גבי גיהוץ מותר בפונדא ובפסיקיא ובאפיליא ובכובע של ראש :","ומ\"ש רבינו ואנו דגיהוץ שלנו ככיבוס שלהם הכל מותר לאחר ז' סמ\"ג כתב דאעפ\"כ משמע שרבינו היה מחמיר כרשב\"א בגיהוץ אף ע\"פ שהיה בבבל כתב הכלבו בשם הר\"מ אדם שאבל על אביו ועל אמו אם יש לו בגד שבת מותר ללבשם אחר ד' שבועות אבל אין לו לעשות בגדים חדשים תוך שנתו אא\"כ שמניח לאחר ללבשן ב' או ג ימים והכל מותר לאחר ד' שבועות הן ללבוש הן לעשות חדשים אלא שאין מנהג עכ\"ל :","\u0003ירושלמי על כל המתים אסור בגיהוץ עד ל' יום וכו'\u0004 וכתב הרמב\"ן בגמרא דידן לא שוי חילוק וכו' ומיהו סמכינן אירושלמי ואברייתא דאבל רבתי וכולי עד סוף הסימן בת\"ה. ומ\"ש בשם הרא\"ש בפרק אלו מגלחין:","ומ\"ש רבינו שהרמב\"ם לא חילק בהם אין לשון זה מדוקדק דמשמע מיניה שסתם דבריו ולא חילק בהם ואינו כן אלא בהדיא כתב בפ\"ו לאחר ל' מותר בגיהוץ אפי' על אביו ועל אמו מ\"מ לענין הלכה כיון שהרמב\"ן והרא\"ש מסכימים לדעת אחת הכי נקיטינן דרבים נינהו ועוד דמסתברא טעמייהו לסמוך על הירושלמי ואבל רבתי שחילקו ביניהם ומדלא חילק תלמודא דידן אין הכרע דאיכא למימר כיון דמייתי כמה חילוקים בין שאר מתים לאביו ואמו הא גלי דאיכא למיפלג בינייהו גם לענין זה דמ\"ש ומש\"ה לא חש לאתויי הך ברייתא:"],["אבל אסור לכבס כסותו פרק אלו מגלחין [מועד קטן דף ט\"ו וסוף דף י\"ז] אבל אסור בתכבוסת ופי' אבל היינו כל ז' אלמא דאחר ז' מותר וס\"ל לרבינו דלאחר ז' מותר אף בנתר וחול ותוך ז' אסור אפי' במים בלא נתר וחול והכי משמע פשט הסוגיא לשם ע\"ש: ומ\"ש וריב\"א אסר כל ל' כ\"כ התוס' בשמו פרק אלו מגלחין (מועד קטן דף כ\"ג) בד\"ה שלשים יום לגיהוץ והביא ראייתו ממסכת שמחות ודחי דאיכא לפרש הך כיבוס דאוסר בברייתא ל' יום היינו גיהוץ וכדי לאפוקי נפשין מפלוגתא דרבוותא נהגו העולם דאחר לובשה תחילה וכן נוהגין עכשיו:","\u0003ומ\"ש רבינו ואיני יודע וכו'\u0004 ויש ליישב דס\"ל לריב\"א דתכבוסת דאסור כל ל' אינו אלא בנתר וחול דאילו במים מודה ריב\"א דשרי כל ל' וכדמשמע מדקאמר אבל אסור בתכבוסת דאלמא דוקא אבל כל ז' אבל לאחר ז' מותר והיינו במים וברייתות דאוסרין תכבוסת כל שלשים אינו אלא בנתר וחול וכ\"כ התוספות לשם לדעת ריב\"א והשתא ס\"ל לריב\"א דטפי יש להתיר גיהוץ בישנים בלא נתר וחול מבכיבוס בנתר וחול ולפי זה הא דנוהגין שאדם אחר לובשו תחילה היינו דוקא במכובס בנתר וחול ואפילו במגוהצין ג\"כ באבן חלקה מותר כיון שלבשו אחר תחילה אבל במכובס במים א\"צ להלבישו לאחר תחילה דאין בזה מחלוקת ופשיטא דשרי לאחר שבעה מיד:","\u0003וכשם שאסור לכבס וכו'\u0004 כן כתב הרמב\"ן בספר ת\"ה [ד' ס\"א ע\"ג וע\"ד] דלבישה הזכירו דאסור ואפי' המכובסים מקודם לכן: ומ\"ש וכן בכל אלו וכו' עד בלא נתר וחול פרק אלו מגלחין (סוף מועד קטן דף י\"ז): ומ\"ש ובלבד שיעשנו בצינעא בתוך ביתו תוספתא כתבוה הרמב\"ן והמרדכי:","\u0003ומ\"ש וכן המטפחת וכו'\u0004 ע\"ל בא\"ח סי' תקנ\"א נתבאר שפשט היתר לפרוש מטפחת המכובס לכבוד שבת:","כתב הרמב\"ן קרוב בעיני הדבר וכולי כלומר אף על פי שאין דין זה מפורש בתלמוד קרוב בעיני הוא דכיון דאיפסיקא הילכתא כראב\"ש דלא אסרו גיהוץ כל שלשים אלא בחדשים לבנים אבל חדשים צבועים אי נמי ישנים לבנים מכובסים יוצאים מתחת המכבש מותרים כל שלשים כמ\"ש בסמוך ס\"ד מכלל דתוך ז' אסורים הם דאם לא כן הו\"ל לראב\"ש לאשמועינן רבותא דאפי' תוך ז' מותרים אלא בע\"כ דוקא תוך שלשים לא אסרום אבל תוך ז' אסורים הם בין חדשים צבועים בין לבנים ישנים:","\u0003תניא וכו'\u0004 [דף כ\"ג] וכתב הראב\"ד וכו' טעמו דס\"ל דמ\"ש ת\"ק כל ל' יום לגיהוץ אחד כלים חדשים ואחד כלים ישנים יוצאין מתחת המכבש אחדשים נמי קאמר יוצאים מתחת המכבש דאם אינן יוצאין מתחת המכבש מותר ללבשן תוך ל' אפי' חדשים ולפי זה רבי וראב\"ש נמי דוקא ביוצאים מתחת המכבש קאמרי דאסורים חדשים הא לאו הכי מותר וא\"כ למאי דקי\"ל כראב\"ש דחדשים לבנים אסירי אין זה אלא דוקא ביוצאים מתחת המכבש ומטעם זה התיר וכו' אבל הרמב\"ן מפרש דהא דקאמר ת\"ק יוצאין מתחת המכבש לא קאי אלא אישנים אבל חדשים אסורין אפי' אינן יוצאין מתחת המכבש וא\"כ לרבי ולראב\"ש דלא אסרו גיהוץ אלא בחדשים אפי' אינן יוצאין מתחת המכבש אסורים והשתא לראב\"ש דהלכה כמותו דאין אסור אלא חדשים לבנים אפילו אין יוצאין מתחת המכבש נמי אסורין:","וחדשים לבנים מגוהצין אסורים ללבוש אפי' הן של פשתן פי' הא דאסור גיהוץ כל ל' בחדשים לבנים אפי' הן של פשתן נמי אסורין בחדשים לבנים ואע\"ג דגבי ט' באב וכו' אבל תוך ז' אסור אפי' בישנים לבנים מגוהצין אפי' הן של פשתן אלא כאן קאמר דתוך ל' דאין אסור אלא בחדשים לבנים אסורין אף בשל פשתן דכיון דתוך ל' לגהץ ולהניח מותר בין ע\"י עצמו בין ע\"י אחר כדלעיל סעיף ג' ואין איסור גיהוץ אלא בלבישה הלכך אין חילוק בין צמר לפשתים דאף בשל פשתן אסור ללובשן תוך ל' והרמב\"ם כתב וכו' וכתב עליו הרמב\"ן ואין זה נכון. ומ\"ש סמ\"ג וז\"ל כתב רבינו משה כלי פשתן אין בהם משום גיהוץ וגם בפרק אלו מגלחין אמרו משום רבי יוחנן כלי פשתן משום שמתקלקלין מותר לכבסן במועד וה\"ה באבל עכ\"ל. האי וגם ה\"פ כי היכי דלענין גיהוץ דאסור כל ל' כלי פשתן אין בהם משום גיהוץ להרמב\"ם ה\"נ גם לענין כיבוס דאסור תוך ז' אינו אסור בשל פשתן וק\"ל: כתב ב\"י בסוף סימן זה כתב הכל בו בשם מהר\"ם אבל על אביו ואמו אם יש לו בגד שבת מותר ללבשו אחר ד' שבועות וכו' ע\"ש וכ\"כ תשב\"ץ סימן תכ\"ו. ובהג\"ה מצאתי ולא ילבוש בגדים לבנים בשבת וכשמת ברגל רוחץ ברגל לכבוד י\"ט האחרון ומחליף בגדים לבנים מאחר שלא חל עליו אבילות עכ\"ה: כתב בהגהת מיימונית חל יום שלשים בע\"ש מותר לרחוץ ואסור לגלח ע\"כ וכתב הרא\"ש אבלים נוהגים ללבוש מלבושים שחורים ובכל מקום יש לעשות כפי המנהג ע\"כ. והאבל שולח מנות בפורים דהא חייב בכל המצות מכאן משמע דבשאר ימות השנה אסור לו לשלוח מנות שאלתי את מורי רבינו יהודה על אבל תוך ל' יום אם יכול להזמין לאחרים או להזמן עם אחרים ואמר לי כי פשיטא דאסור זה בכל מקום ע\"כ תשובה שאלו להר\"ר אליעזר מגרמיזא והתיר לאבל להיות בעל ברית ואסור ליכנס לסעודה וכן הורה רבינו דוד ב\"ר קלונימוס וכן הלכה למעשה משמחות מהר\"ם ונראה דהיינו דוקא תוך ז' אבל תוך שלשים כשהוא בעל ברית מותר לכנוס לסעודה דאפילו בשמחת נישואין מותר תוך שלשים אם הוא אבל על שאר קרובים ואם לא ילך הוא יתבטל המעשה כ\"ש מוהל או בעל ברית די\"ט שלו הוא ועיין בתשובת מהרי\"ל סימן קי\"ו דמתיר אפילו תוך ל' יום של אביו במוהל או בעל ברית אע\"פ דאסור במשיא יתום ויתומה ע\"ל בסימן שצ\"א:","\u0003ומ\"ש וכתב הרמב\"ן בגמרא דידן לא משוי חילוק וכו'\u0004 עד ויגערו בו חביריו וכו' האידנא אין דין זה נוהג בינינו לפי שאין לנו גיהוץ עכ\"ה:"]],["\u0010c0\u0011\u0010y0\u0011אבל אסור לגלח \u0010c1\u0011אחד שער ראשו ואחד שער זקנו ואחד כל שער שבו אפי' בית הסתרים \u0010c2\u0011לכן כ' הראב\"ד אף ע\"פ שבחול המועד מותר לגלח השער שעל השפה באבל כל ל' יום אסור והרי\"ץ גיאות כ' שאסור תוך ז' ומותר לאחר ז' וכ\"כ בה\"ג והרמב\"ן כ' שאפי' תוך שבעה מותר ליטול כל שערה שעל השפה ומהצדדין כל שמעכב האכילה \u0010c3\u0011\u0010y1\u0011ישב לגלח ואמרו לו מת אביו ה\"ז משלים ראשו אחד המגלח ואחד המתגלח \u0010c4\u0011\u0010y2\u0011כל אלו שאמרו מותר לגלח בח\"ה כגון הבא ממדינת הים שהלך להרויח ולא היה לו פנאי לגלח קודם המועד והיוצא מבית השביה ומבית האסורין ומנודה שהתירו לו חכמים והנשאל לחכם והותר כולם אסורין לגלח בימי אבלו שאם ארעו אחד מאלו קודם האבילות ונכנס מיד תוך האבל אסור לגלח אבל אם ארעו אחד מאילו ותכפוהו מיד שני אבילות זה אחר זה \u0010y3\u0011מגלח כדרכו בין בתער בין במספרים אפי' תוך ז' ואדם אחר שתכפוהו אביליו זה אחר זה מיקל שערו פי' שמגלחו קצת בתער \u0010c5\u0011אבל לא במספרים \u0010c6\u0011\u0010y4\u0011על כל המתים מגלח לאחר ל' יום על אביו ואמו עד שיגערו בו חביריו \u0010y5\u0011ואפי' פגע בו הרגל לאחר ל' יום אסור עד שיגערו בו חביריו \u0010c7\u0011\u0010y6\u0011תניא באבל רבתי אשה מותרת בנטילת שער אחר שבעה \u0010y7\u0011וכ\"כ רב אלפס שאשה מותרת בנטילת שער והקשה הרמב\"ן אם כן תהא מותרת בגיהוץ וכן כל מצות ל' לא יהא נוהגת בה על כן נראה כדברי המפרשים דנטילת שער דשרי באשה היינו במעברת סרק על פניה וטופלתו בסיד שהוא משום תכשיט שלא תתנוול על בעלה אבל בתספורת ממש אסורה כל ל' יום כמו האיש וכן כתב א\"א הרא\"ש ז\"ל \u0010c8\u0011\u0010y8\u0011תניא כשם שאסור לגלח בימי אבלו כך אסור ליטול צפרניים דברי רבי יהודה ורבי יוסי מתיר והלכתא כוותיה ומותר \u0010y9\u0011בין בשל ידים בין בשל רגלים ומיהו \u0010c9\u0011\u0010y10\u0011דוקא בשינוי כגון בידיו או בשיניו אבל במספרים או בסכין אסור \u0010y11\u0011\u0010y12\u0011\u0010y13\u0011\u0010y14\u0011\u0010y15\u0011כתב רי\"ף חזינא לקצת רבוותא דכתבו דוקא תוך ל' אבל תוך ז' אסור ואנן לא סבירא לן הכי אלא אפי' תוך ז' שרי וכ\"כ הרמב\"ן וכתב הרי\"ץ גיאות דאחר ז' מותר אפי' במספרים וכ\"כ בה\"ג וכן פסק בספר המצות אבל הרמב\"ן כתב שאין חילוק בין תוך שבעה לאחר שבעה שלעולם אינו מותר אלא ע\"י שינוי:",["אבל אסור לגלח בר\"פ אלו מגלחין (מועד קטן יד:) אבל אסור בתספורת מדאמר רחמנא לבני אהרן ראשיכם אל תפרעו מכלל דכולי עלמא מיחייב: ומ\"ש אחד שער ראשו ואחד שער זקנו וכו' שם (יח.) אמר רב יהודה אמר רב זוג בא מחמתן לפני רבי ובקשו ממנו צפרנים והתיר להם ואם בקשו ממנו שפה התיר ושמואל אמר אף שפה בקשו ממנו והתיר להם אמר אביטול ספרא משמיה דרב פפא שפה מזוית לזוית הנחה כל שמעכבת א\"ר אמי ובשפה המעכבת כתב המרדכי שמצא ר\"ם בשם ר\"ת דשמא לא התירו שפה אלא בתער ולא במספרים דומיא דתכפוהו אביליו עכ\"ל וכתב הרמב\"ן בת\"ה פי' שפה נקרא מה שמזוית לזוית והיינו מה שלמעלה מן הפה כנגד כל פתיחת הפה והכל מותר לגלח. הנחה הוא שם אחר והוא מה שמכאן ומכאן לפתיחת הפה וקורים אותו כך לפי שדרך המתגלחין להניחו וכל שמעכבת אכילה ממנה מותר: ובשפה כל שמעכבת. כלומר אף שפה אין מתירין לו לגלח הכל אלא כל שמעכב בלבד וכתב הראב\"ד דברים הללו דוקא במועד אמרו אבל באבילות אסור דתניא באבל רבתי [פ\"ז] לתספורת כיצד אסור בנטילת שער אחד ראשו ואחד כל שער שבו ואחד זקנו והרי\"ץ גיאות התיר שפה כל שמעכבת בתוך ל' ובתוך ז' אסר וכן פסקו בפסוקות ובגדולות ומסתברא שאף בתוך ז' נמי מותר דאינו בדין שיתלכלך באכילה בשפה והנחה כל שמעכבין ובירושלמי מצינו כן שפה ונטילת צפרנים אית תנויי תני ברגל מותר ובאבל אסור ואית תנויי תני ברגל אסור ובאבל מותר רבי חייא בר' אשי בשם רב הלכה כדברי מי שהוא מיקל כאן וכאן רבי יעקב בר אחא ר' שמעון בר רב משמיה דרב הלכה כדברי מי שהוא מיקל בהלכות אבל רב אמר שפה כנטילת צפרנים לכל דבר אמר ר' ירמיה ובלבד שנוטות כלומר שנוטות ויוצאות על הפה ומעכבות רבי סימון בשם ר' חנינא זוג בא לפני רבי בשפה ובנטילת צפרנים והתיר להם למדנו משם מפורש שהשפה כל שמעכבת מותר לאבל להוציא מדברי הר\"א וכן הדברים האלו מראים כדעתנו שהתרנו אפילו תוך שבעה כדין צפרנים קצרו של דבר אבל כל ל' אסור לספר אחד ראשו ואחד זקנו ואפילו של בית הסתרים אבל כל שמעכב באכילה נוטלו אפי' במספרים בתוך ז' בין למעלה מן הפה בין מן הצדדין עכ\"ל. והרמב\"ם כתב בפ\"ו כשם שאסור לספר כל שער גופו או לגלח שפמו או לקוץ צפרניו בכלי כל ז' כך אסור כל ל' יום ודבריו מבוארים כדברי הראב\"ד ז\"ל:","\u0003ולענין הלכה כיון שהרמב\"ם והראב\"ד מסכימים לדעת אחת הכי נקטינן:\u0004 ","\u0003ישב לגלח ואמרו לו מת אביו וכו'\u0004 באבל רבתי [פ\"ה] וירושלמי פ\"ק דשבת וכתבוהו הרי\"ף והרא\"ש בסוף מ\"ק וכתב המרדכי ושמא היינו טעמא דגדול כבוד הבריות וכו' ומה שהספר גומר היינו בדליכא ספר אחר במתא:","\u0003כל אלו שאמרו מותר לגלח בח\"ה כגון הבא ממ\"ה וכו'\u0004 עד מיקל שערו בתער אבל לא במספרים בפרק אלו מגלחין (מועד קטן יז:):","\u0003ומ\"ש מגלח כדרכו וכו'\u0004 אפי' תוך ז' כ\"כ הרמב\"ן בת\"ה ויליף לה מדקתני בהאי ברייתא דתכפוהו אביליו מכבס נמי כסותו במים וההוא ע\"כ תוך ז' הוא דאחר ז' אין איסור בכיבוס א\"כ גם היתר תספורת תוך ז' קא שרי וכתב ר\"י מיקל בתער פי' שיגלח מלמטה עיקרי השער כדי להקל מעליו אבל לא במספרים פירוש שיחתוך מזנבות השער מפני שזה נראה לעינים אבל תחת שערו אינו נראה והרמב\"ן כתב בת\"ה לרבינו האי תער ומספרים משונים זה מזה ויש שינוי בין לשון תורה ובין לשון חכמים כי תער של תורה בלשון חכמים מספרים והוא עשוי לגילוח והשחתה ואשר אינו משחית לגמרי קורין לו חכמים תער ובירוש' מיקל בסכין ובתספורת אבל לא במספרים ובעל הערוך הקשה עליו ובודאי שתשובה זו משובשת דתער בין בלשון תורה בין בל' חכמים הוא המשחית לגמרא כדאמרי' בפ\"ק דקידושין [לה.] איזהו גילוח שיש בו השחתה הוי אומר זה תער ומספרים בין בל' תורה בין בל' חכמים יש בה גילוח ולא השחתה וזה שאמרו כאן מקל בתער הטעתו לגאון ז\"ל בפירוש זה כסבור לומר דמפני שאין בו השחתה התירו כן ולא היא דהכא לאו משום השחתה שרינן דאטו גילוח באבל מותר אלא הכא במיקל משער ראשו ומספר ממנו קצת עסקינן כדאמר בהדיא והדבר ידוע שהחותך מן השער קצתו אין דרכו בתער וא\"א לגלחו כהוגן אלא בזוג של מספרים ומשום שהוא שלא כדרך המתגלחין ובשינוי מותר בסכין ובתספורת שהתער כאן כסכין הוא עכ\"ל:","וכתב עוד הרמב\"ן בשם התוספתא דהני דשרינן להו לספר בתוך ל' דוקא בצינעא ורבינו כתבו לענין כיבוס וממילא משמע דה\"ה לענין תספורת:","על כל המתים מגלח לאחר שלשים יום על אביו ואמו עד שיגערו בו חביריו ברייתא בפרק אלו מגלחין (מועד קטן כב:):","ומ\"ש ואפי' פגע בו הרגל לאחר שלשים יום אסור עד שיגערו בו חביריו כ\"כ הרא\"ש שם וכ\"כ הרמב\"ם בפ\"י וכתב נ\"י וסמ\"ג דהכי משמע בירושלמי וכתב הרמב\"ן בת\"ה דמשמע הכי מדאמרי' (שם) על כל המתים נכנס לבית השמחה לאחר שלשים יום על אביו ועל אמו לאחר י\"ב חדש וא\"א לי\"ב חדש בלא רגל ש\"מ שאין רגל מפסיק כלום באבילות אביו ואמו בין בשמחה בין בתספורת וגיהוץ אלא עד שיגיע זמן שקבעו להם חכמים וכתב נ\"י וי\"א דאם עברו שלשים יום ואח\"כ בא הרגל דאז הרגל מפסיק ומהני לבטל זמן הגערה והוא מדברי סמ\"ק כמ\"ש בסמוך וכ\"כ התוספות בשם הירושלמי דגרסינן רבי שמואל בר אבדימי מונה שלשים יום קמי מועדא שאיל לר' מנה א\"ל כל דבר שהוא תלוי בשבעה ובשלשים הרגל מפסיק ברם הכא עד שישלח פרע ויגערו בו חביריו ויאמרו לו צא מעמנו וי\"ס שכתוב בהם או יגערו בו חביריו בירושלמי ונראה שהוא ט\"ס כ\"א כמו שכתבתי עד שישלח פרע ויגערו בו חביריו עכ\"ל. וכך הם דברי הרי\"ף על אביו ואמו יגדל פרע עד שיגערו בו חביריו ונראה דגידול פרע היינו ל' יום ולא אתא למעוטי אלא אם גערו בו חביריו תוך ל' יום דאסור אבל הרמב\"ם כתב בפ\"ו ובפ\"י עד שישלח פרע או עד שיגערו בו חביריו ואפשר דמשמע דשילוח פרע היינו גידול שער ימים הרבה מאד דאז מותר אפילו לא גערו בו חביריו ואם גערו בו חביריו קודם שיגדל שער כ\"כ שרי והוא שיגערו בו אחר ל' יום אבל אם גערו בו תוך ל' לאו כלום הוא והגה\"מ כתבו בפ\"י בשם סמ\"ק אם עברו שלשים יום קודם הרגל הרגל מפסיק וא\"צ להמתין עד שיגערו בו חביריו וטעמא משום דאמרינן בירושלמי שיעור גערה ל' יום לכך הרגל מפסיקו ונראה דאפילו חל יום ל' ערב הרגל מותר לספר כיון דמקצת היום ככולו א\"כ אותו יום ל' מקצתו מל' השניים ולא לעניין לפחות מהמנין דלעולם בעינן ל' שניים מלבד ל' הראשונים היכא דלא גערו בו אלא נ\"מ שאם חל ערב הרגל יום ל' שמותר לגלח בו כשאר ימות השנה אם גערו בו חביריו ביום ל' דנהי דאם לא גערו בו בשאר ימות השנה צריך להמתין ולהשלים ל' שניים מ\"מ אם גערו בו ביום ל' מהני אפי' בלא רגל עכ\"ל. כתבו התוס' בפרק אלו מגלחין (מועד קטן יט.) ה\"ר י\"ט פירש כיון דקי\"ל מקצת יום ז' ככולו עולה לכאן ולכאן יכול לגלח ביום כ\"ט ובתוס' הרב לא פירש כן דלא אמרינן שיהא יום ז' לב' ימים לענין שלשים ע\"כ :","\u0003תניא באבל רבתי אשה מותרת בנטילת שער אחר שבעה:\u0004 ","ומ\"ש בשם הרי\"ף בפרק אלו מגלחין כתב גרסינן בפרק החולץ בענין ר' יוסי אומר כל הנשים יתארסו חוץ מן האלמנה מפני האיבול וכמה איבול שלשים יום אמר רב חסדא ק\"ו ומה במקום שאסרו לספר ולכבס מותר ליארס ל' של איבול שמותר לספר ולכבס אינו דין שמותר ליארס וש\"מ שהאשה מותרת בנטילת שער כדקתני באבל רבתי ע\"כ וכתב עליו הרמב\"ן בת\"ה אבל רש\"י אינו גורס שם לספר אלא גירסתו כך הוא במקום שאסור לכבס מותר ליארס ל' של אבל שמותר לכבס אינו דין שמותר ליארס וכתב שהדברים נראים לענין הסוגיא כדברי רש\"י ועוד קשה לי לדברי רבי' בעל הלכות ז\"ל הרי האשה מותרת ללבוש כלים חדשים מגוהצים לאחר ז' ואינה בגזירת ל' של גיהוץ והרי אנו כל עיקר לא למדנו בגמרא לגיהוץ אלא מן האשה התקועית ואולי נאמר דה\"ק התם באשה שנהגה אבילות ימים רבים כאיש אלא שאין הטעם נדון להתיר לה וכי אם לא תתקשט בלבנים חדשים תתגנה על בעלה תכבס ותתקשט בבגדי צבעונים חדשים ובמכילתא אחריתי דאבל תניא כל מה שיש באיש יש באשה חוץ מתספורת ולא תני גיהוץ כלל ויש מחכמי הצרפתים ז\"ל שפירשו נטילת שער זה שהתירו באשה במעברת סרק על פניה של מטה אבל תספורת ממש לשער ראשה אסור כל שלשים אפי' באשה שהרי אין דרכה כל ימות השנה בתספורת אלא מגדלות הן שער כלילית ולמה יתירו לה באבל ודברי טעם הן ונראין עכ\"ל וגם התוספות כתבו בפרק החולץ (יבמות מג.) כדברי רש\"י וכתב הרא\"ש בפ' אלו מגלחין שכן עיקר והרמב\"ם בפ\"ו פסק כדברי הרי\"ף ז\"ל. ולענין הלכה כיון שהרי\"ף והרמב\"ם מסכימים לדעת אחח הכי נקטינן :","כתב רבינו ירוחם לסרק ראשו במסרק פירש\"י והמפרשים שמותר אפילו תוך ז' שאין כאן לא תענוג ולא שמחה והמרדכי כתב במ\"ק והגה\"מ פרק ז' לסרק ראשו יש מתירין ויש רוצים לאסור כל ל' יום ומדברי ר\"י נראה דשרי שהתיר לחוף ראשו אפי' תוך ז' וסמ\"ג כתב סורק ראשו לאחר ז' ולענין הלכה נקטינן כדברי המקילים לסרוק אפילו תוך ז' :","\u0003תניא כשם שאסור לגלח בימי אבלו כך אסור ליטול צפרניים וכו'\u0004 בפרק אלו מגלחין (מועד קטן יז:) ואיפסיקא התם בגמרא הלכה כר' יוסי:","\u0003ומ\"ש בין של ידים בין של רגלים מימרא שם:\u0004 ","\u0003ומ\"ש ומיהו דוקא בשינוי וכו'\u0004 שם א\"ר חייא בר אשי אמר רב ובגנוסטרי אסור וכתבו התוספות גנוסטרי פירש בערוך שהוא כלי המתוקן ליטול צפרנים משמע שהיה מתיר בין בתער בין במספרים מיהו קאמר בגמרא ר' יוחנן דשקלינהו בשיניה משמע דוקא בשיניו שרי וכ\"כ הרמב\"ם בפ\"ה אסור ליטול צפרניו בכלי אבל בשיניו או שנוטל צפורן בצפורן מותר וכן דעת הרמב\"ן בת\"ה וכ\"כ סמ\"ג בגנוסטרי אסור פי' במספרים וה\"ה בתער:","ומ\"ש רבינו בשם הרי\"ף בפרק אלו מגלחין והכריע הרמב\"ן בת\"ה כמותו ומ\"ש בשם הרי\"ץ גיאות הביאו הרמב\"ן בת\"ה: וכתב אח\"כ ומדברי רבינו הרי\"ף נלמוד שכל ל' אסור בגנוסטרי וכתב במסקנא כדברי הרי\"ף דבגנוסטרי אסור כל ל' יום ושלא בכלי מותר אפילו תוך ז' וכ\"פ הרמב\"ם ז\"ל בפ\"ה וששי. ולענין הלכה כיון שהרי\"ף והרמב\"ם מסכימים לדעת אחת הכי נקטינן:","כתבו הגה\"מ פ\"ה בשם הר\"מ מאינגלטיר\"ה אשה שאירעה טבילתה בחוה\"מ לא תטול צפורניה בעצמה אבל אומרת לנכרית ליטול צפורניה אפילו בגנוסטרי דכיון דאמירה לנכרי שבות במקום מצוה לא גזור אבל היא עצמה אינה יכולה ליטלה יפה בשיניה או בידיה וכן הדין אם עירעה טבילת מצוה תוך ל' אחר ז' עכ\"ל :"],["אבל אסור לגלח ר\"פ ואלו מגלחין (סוף מועד קטן דף י\"ד) אבל אסור בתספורת מדקא א\"ל רחמנא לבני אהרן ראשיכם אל תפרעו מכלל דכ\"ע אסור.","\u0003ומ\"ש אחד שער ראשו וכו'\u0004 כ\"כ הרמב\"ן דה\"א באבל רבתי לתספורת כיצד אסור בנטילת שער אחד ראשו ואחד כל שער שבו ואחד זקנו ובכלל כל שער שבו הוי נמי שער בית הסתרים וראיה לדבר ומפיבושת בן שאול יצא לקראת המלך לא עשה רגליו ולא עשה שפמו:","\u0003ומ\"ש לכן כתב הראב\"ד וכו'\u0004 פי' הא דאיתא בפרק אלו מגלחין (מועד קטן דף י\"ח) זוג בא מחמתן לפני רבי וכו' דאסיקנא בסתמא דמותר לגלח השער של השפה ואיכא לפרש דבין במועד ובין באבילות קאמר דמותר אבל מדתני בהך דאבל רבתי דכל שער שבו אפילו של בית הסתרים אסור באבל לכן כתב הראב\"ד דהך סוגיא דמתיר לגלח השפה אינו אלא במועד אבל באבלות אסור כל שלשים אפי' מעכב האכילה ורי\"ץ גיאות מפרש דהך סוגיא דמתיר לגלח השפה איירי בין במועד בין באבלות תוך ל' דשרי לגלח מה שמעכב האכילה והך דאבל רבתי דאוסר כל שער שבו לא מיירי אלא באבל תוך ז' דאסור אפילו מאי דמעכב האכילה והרמב\"ן ס\"ל דאפילו תוך ז' שרי לגלח מאי דמעכב האכילה והך דאבל רבתי דאוסר כל שער שבו היינו כל שער חוץ ממאי שמעכב את האכילה דפשיטא דשרי ולא היה צריך לפרש דאינו בדין שיתלכלך באכילה בשפה ומן הצדדין כל שמעכבין:","\u0003ישב לגלח וכו'\u0004 באבל רבתי וכתב המרדכי דאם המתגלח נעשה אבל גומר דגדול כבוד הבריות וכו' וכשהמגלח נעשה אבל נמי גומר היינו בדליכא ספר אחר במתא והתירו לו משום כבוד המתגלח:","\u0003כל אלו שאמרו מותר לגלח וכו'\u0004 בפרק אלו מגלחין (סוף מועד קטן דף י\"ז):","ומ\"ש מיקל בתער אבל לא במספרים פי' מיקל משער ראשו ומספר ממנו קצת בשינוי בתער ובסכין דבתער וסכין אי אפשר לגלחו כהוגן אבל לא במספרים שהוא זוג של מספרים שמגלחין בו כהוגן כך פי' הרמב\"ן ומביאו ב\"י:","\u0003על כל המתים וכו'\u0004 שם [דף כ\"ב]. ומ\"ש ואפי' פגע בו הרגל וכו' ה\"א בירושלמי הביאוהו התוס' לשם בד\"ה עד שיגערו וכ\"כ הרא\"ש ושאר פוסקים דלא כהסמ\"ק דפסק אם עברו ל' קודם הרגל מפסיק וא\"צ להמתין עד שיגערו בו חביריו ומביאו רבינו לקמן סימן שצ\"ט וטעמו דס\"ל שיעור גערה שלשים יום אחר שלשים וכיון דבירושלמי אמרו כל דבר שהוא תלוי בשבעה ושלשים הרגל מפסיקו ברם הכא עד שישלח פרע ויגערו בו חביריו ויאמרו לו צא מעמנו א\"כ לפי זה כיון דשיעור גערה ל' יום אחר שלשים ופגע בו הרגל אחר שלשים השתא הו\"ל בכלל דבר שהוא משום ל' והרגל מפסיקו וא\"צ להמתין עד שיגערו בו ועוד האריך בהגהת סמ\"ק ע\"ש סימן צ\"ז אבל לא נהגו כמותו להקל אלא כדפסק רבינו והוא דעת כל הפוסקים וכ\"פ בש\"ע בא\"ח סימן תקמ\"ח סעיף ט' וכ\"כ בהגהת ש\"ע כאן:","\u0003תניא באבל רבתי אשה מותרת בנטילת שער וכו'\u0004 והטעם כדי שלא תתנוול על בעלה אם לא תספר שערת ראשה מה שהיא רגילה לספר והרמב\"ן בשם חכמי צרפת השיג ואמר הרי אין דרכה כל ימות השנה בתספורת אלא מגדלות הן שער כלילית ולמה יתירו לה באבל אבל להעביר סרק על פניה שלמטה וכו' שכן דרכה כל ימות השנה שלא תתנוול על בעלה הוא דשרי אבל לא נטילת שער ראשה ולמאי שכתבתי אין כאן השגה דרב אלפס לא אמר בשערות ראשה שכל אשה מגדלות אותן ואינן מגלחות אלא אדרבה אם אין להן שערות ארוכות מתקנין להן פיאה נכרית אלא באשה שיש לה רבוי שערות כגון צידעא ובת צידעא כדאיתא בפרק המוציא יין (שבת דף פ') שהיו טופלין בסיד להסיר השער ומקצתן מגלחין אותן וכל זה כדי שלא תתנוול על בעלה מחמת רבוי שערות במקום דלא שכיחי שערות לשאר נשים ובהא דוקא כתב הרי\"ף דאשה מותרת בנטילת שער וכ\"פ הרמב\"ן בפ\"ז והכי נקטינן וכן פסק ב\"י אלא דבש\"ע השמיטו אח\"כ ראיתי להרב מהר\"ר מענדל שכתב בהקדמתו לסמ\"ק שהדפיס בקראקא דחסר כאן בש\"ע סעיף ה' וכצ\"ל אשה מותרת בנטילת שער אחר ז'. הגה\"ה ויש אוסרין וכך עיקר ע\"כ לשונו. ואני אומר העיקר כדפרישית דבמקום שדרכה של אשה לגלח שערותיה אלו כגון רבוי שערות דצידעא ובת צידעא מותרת ליטלה אחר שבעה וכ\"פ הסמ\"ג והסמ\"ק:","\u0003תניא כשם שאסור לגלח בימי אבלו וכו'\u0004 בפרק אלו מגלחין סוף (מועד קטן דף י\"ז):","\u0003ומ\"ש ומיהו דוקא בשינוי וכו'\u0004 שם ריש [דף י\"ח] אמר רב ובגנוסטרא אסור ופירש רש\"י במספריים ולאו דוקא גנוסטרי אלא כל שהוא כלי כגון תער וסכין נמי אסור דאין היתר אלא בשיניו כדעביד ר' יוחנן או צפורן בצפורן ודלא כמ\"ש התוס' בשם הערוך דאינו אסור אלא בגנוסטרי שהוא כלי המתוקן ליטול צפרני' אבל בסכין או בתער ומספרים מותר דליתא: כתב המרדכי לסרק ראשו תוך ז' יש מתירין ויש רוצין לאסור כל ל' כיון דאסור בתספורת כל ל' ומדברי ר\"י שפי' שמותר לחוף אפילו תוך ז' משמע דלא אסרו אלא דרך תגלחת ותספורת שהוא ליפות עצמו אבל לסרוק מותר וראיה מחש\"מ דאסור בתספורת וכל העם חופפים וסורקים ולא היה אדם שמערער על זה עכ\"ל הר\"ם וסמ\"ק כתב וסורק ראשו במסרק לאחר ז' עכ\"ל ובש\"ע פסק לסרוק האשה במסרק מותר תוך ז' עכ\"ל משמע דדוקא באשה שצריכה שלא יהיו מסוכסכים שערותיה כשהיא טובלת לא החמירו בה משא\"כ באיש דנכון להחמיר אבל מצאתי שט\"ס הוא וצריך להגיה לסרוק ראשו וכו' מיהו בהגהת סמ\"ק כתב והא\"ז אוסר לאיש לסרוק ראשו במסרק כל ל' יום אך לאשה מתיר לאחר שבעה עכ\"ל:"]],["\u0010c0\u0011\u0010y0\u0011אבל אסור בשמחה כל ל' יום אפי' תינוק אין לו ליקח בחיקו שמא מתוך כך יבא לידי שחוק ומיהו זהו דוקא תוך ז' \u0010y1\u0011ותניא על כל המתים נכנס לבית המשתה לאחר ל' ועל אביו ואמו לאחר י\"ב חדש ואף אם השנה מעוברת מותר לאחר י\"ב חדש \u0010y2\u0011ומטעם זה אסור לו לילך בדרך בשיירא גדולה כל י\"ב חדש מפני שהוא כמו שמחה ששמחים הרבה בדרך ולשאר קרובים ל' יום \u0010c1\u0011\u0010y3\u0011א\"ר הונא ולשמחת מריעות מותר ליכנס לאלתר פי' כמו שעושין ריעים זה עם זה שאוכלים ושותים זה עם זה היום וחוזרים ואוכלים זה עם זה למחר מותר מיד אף על פי שאוכלים ושותין זה עם זה \u0010c2\u0011אין בו שמחה כמו בחופת חתנים \u0010y4\u0011בד\"א שצריך לפרוע יומו כגון שכבר אכל עם ריעיו והגיע יום הפרעון בימי אבלו אבל אסור להתחיל ולעשות סעודת מריעות עד לאחר ל' יום ועל אביו ואמו אסור בין להתחיל בין לפרוע עד לאחר י\"ב חדש תניא באבל רבתי על כל המתים אסור לילך לבית המשתה עד לאחר ל' יום \u0010y5\u0011ולאביו ואמו כל י\"ב חדש ואם היה חבורה לשם מצוה כגון קידוש החדש מותר מיד בין תוך ל' לשאר קרוביו ותוך י\"ב חדש לאביו ואמו וכתב הראב\"ד וכן משיא יתום או יתומה או עני ועניה לש\"ש שאם לא יאכל שם ויעשה הוא יתבטל המעשה מותר וכל זה לא התירו אלא מל' ואילך באביו ואמו אבל תוך ל' יום הוא אסור לכל סעודת מצוה שבעולם והרמב\"ן כ' ואינו מחוור להתיר סעודת של משיא יתום ויתומה וא\"א הרא\"ש ז\"ל הביא דברי הראב\"ד \u0010c3\u0011\u0010y6\u0011ויש נוהגין להקל בכניסת בית המשתה ולהסב שם בשעת שמחה והם אמרו שלא אסרו אלא לאכול עמהם בשעת שמחה אבל הכניסה שם מותרת שאין שמחה בלא אכילה ושתיה וה\"ר יהודה אלברצלו\"ני כתב כן שכ' יש נוהגים ליכנס תוך י\"ב חדש לחופה לשמוע הברכה או לבקר אבל לא לאכול ויש מחמירין שאין נכנס כלל \u0010y7\u0011והרמב\"ן כתב שאסור ליכנס שם כלל בין בשעת אכילה בין בשעה שעוסקים שם במזמוטי חתן וכלה \u0010y8\u0011וכ\"כ א\"א הרא\"ש ז\"ל וכן נוהגים באשכנז דכל י\"ב חדש עומד חוץ לבית לשמוע הברכות ואינו נכנס לבית כלל :",["\u0003אבל אסור בשמחה כל ל' יום אפי' תינוק אין לו ליקח בחיקו וכו'\u0004 בסוף מ\"ק [כו:] אמר רב פפא תנא באבל רבתי אבל לא יניח תינוק בתוך חיקו מפני שמביאו לידי שחוק ונמצא מתגנה על הבריות ומדנקט אבל משמע דדוקא דתוך ז' קאמר וכך הם דברי הרמב\"ם ז\"ל בפ\"ה ודברי רבינו הם בלתי מסודרים דפתח בל' יום וסיים בז' והדר סיים כל הסימן בל' ומן הראוי דין זה דלא יקח תינוק בחיקו הו\"ל לכתוב בסימן שפ\"ה אצל שאלת שלום וכן קבעו הרמב\"ם ז\"ל בפ\"ה דמיירי בדינים הנוהגים תוך ז' וכתב כל' הזה אם בשאלת שלום נאסר האבל ק\"ו שהוא אסור להרבות דברים ולשחוק שנאמר [יחזקאל כד:] דום ולא יאחוז תינוק בידו שלא יביאנו לידי שחוק:","ותניא על כל המתים נכנס לבית המשתה לאחר ל' יום ועל אביו ואמו לאחר י\"ב חדש בפרק אלו מגלחין (מועד קטן כב:): ומ\"ש ואף אם השנה מעוברת וכו' כ\"כ הרא\"ש פרק אלו מגלחין בשם ראבי\"ה וכ\"כ רבינו ירוחם והגה\"מ בפ\"ו והמרדכי במ\"ק בשמו ודייק לה מדקתני י\"ב חדש ולא קתני שנה:","\u0003ומ\"ש ומטעם זה אסור לו לילך בדרך בשיירא גדולה וכו'\u0004 נתבאר בס\"ס ש\"פ:","\u0003אמר רב הונא ולשמחת מריעות מותר ליכנס לאלתר בפ' א\"מ שם:\u0004 ","\u0003ומ\"ש בד\"א שצריך לפרוע יומו וכו'\u0004 שם אסיקנא דה\"מ בפרענותא אבל בארישותא אסור עד לאחר ל' יום פי' ארישותא הלואה דהיינו שמתחיל הוא להאכיל את חבירו אתה נושה בו [דברים כד:] מתרגמינן דאת רשי ביה. וז\"ל הרמב\"ם בפ\"ו שמחת מריעות שהיה חייב לפרוע אותה מיד מותר לעשותה מיד אחר ז' אבל אם אינו חייב לפורעה אסור להכנס לה עד ל' יום:","\u0003ומ\"ש ולאביו ואמו כל י\"ב חדש כ\"כ שם הרי\"ף והרא\"ש והרמב\"ם בפ\"ו והרמב\"ן בת\"ה:\u0004 תניא באבל רבתי על כל המתים אסור לילך לבית המשתה וכו' (פ\"ט) והביאה הרמב\"ן בת\"ה על כל המתים אסור לילך לבית המשתה עד שימלאו ל' יום על אביו ואמו לאחר י\"ב חדש ואם היתה חבורה לשם מצוה כגון קידוש ר\"ח מותר. ומ\"ש רבינו מותר מיד בין תוך ל' לשאר קרוביו וכו' וכן מ\"ש בשם הראב\"ד וכן משיא יתום או יתומה וכולי בפרק אלו מגלחין אהא דאמר רב הונא ולשמחת מריעות מותר ליכנס לאלתר כתב הרא\"ש הקשה הראב\"ד דהכא משמע דבסעודת מצוה איכא איסורא טפי מבסעודת הרשות ובאבל רבתי תניא על כל המתים אסור לילך לבית המשתה עד ל' יום לאביו ואמו עד שיגערו בו חביריו אא\"כ היתה לשם שמים אלמא דסעודת מצוה יש בה היתר יותר מבסעודת הרשות ותירץ האי לש\"ש דשרי היינו שהוא משיא יתום ויתומה או עני וענייה לש\"ש ואם לא יכנס שם יתבטל המעשה אבל בנשואי עשיר שהזמינו לסעודה להתכבד בו אסור ליכנס שם ירושלמי אם היתה חבורת מצוה או קידוש החדש מותר חבורת מצוה כגון חבורת פסח חבורת אכילת קדשים ומעשר שני וכן כל דבר שצריך בעצמו אע\"פ שאוכל בחבורה ויש שם משתה ושמחה ובכל זה לא התירו אלא מל' ואילך באביו ואמו אבל תוך ל' לכל סעודה שבעולם אסור כנ\"ל הראב\"ד ז\"ל עכ\"ל ונמוקי יוסף הקשה קושיא זו ותירץ דההוא לש\"ש מיירי בסעודת מצוה דליכא שמחה כגון ברית מילה דאיכא צעריה דינוקא א\"נ במשיא יתום ויתומה שאם לא יכנס הוא יתבטל המעשה ע\"כ והרמב\"ן בת\"ה כתב על דברי הראב\"ד ול\"נ דחבורת מצוה כגון קידוש ר\"ח ואכילת קדשים ופסח אע\"פ שאוכל בחבורה ויש שם משתה ושמחה מותר לאחר ז' וברייתא דקתני ואם היתה חבורת מצוה ארישא נמי תניא ומשיא יתום ויתומה אינו מחוור להתיר לזה סעודה שלהם עכ\"ל:","\u0003ויש נוהגים להקל בכניסת בית המשתה וכו'\u0004 והוא אמר שלא אסרו אלא לאכול עמהם וכו' כלומר טעמם של הנוהגים להקל מפני שהם אומרים שלא אסרו ליכנס לבית המשתה אא\"כ אוכל עמהם אבל אם אינו אוכל עמהם מותר ליכנס והג\"מ בפ\"י הביא סברא זו וכמו שאכתוב בסמוך בס\"ד ומ\"ש והר\"י אלברצלוני\"א כתב כן היינו לומר שהזכיר סברא זו אבל ג\"כ כתב שיש מחמירין שאין נכנסין כלל ולא הכריע בדבר כמבואר בת\"ה.","\u0003ומ\"ש ג\"כ רבינו בשם הרמב\"ן הוא בס' ת\"ה.\u0004 ","\u0003ומ\"ש בשם הרא\"ש וכן נוהגין באשכנז וכו'\u0004 בפרק אלו מגלחין. והגה\"מ כתבו בפ\"ו דהא דאינו נכנס לבית השמחה דוקא לסעודת שמחה אבל לילך לבית הנישואין וברכת אירוסין מותר מיד אחר ז' שהרי אין שום שמחה שם לא ריקוד ולא טפוח ושחוק וראב\"ן פי' דוקא אחר ל' ולא נתן טעם לדבריו ע\"כ לשונו הר\"מ ובסמ\"ג כתב רבי' יהודה וה\"ר יוסף מפי ר\"ת ור\"י היו מתירים לבא לסעודת חתן אכן מצאתי שכתב ה\"ר יוסף בפ\"ב דמ\"ק אסור ליכנס לבית השמחה כגון סעודת אירוסין ונישואין לאכול בין עם החתן בין עם המשמשין עד ל' יום ועל אביו ואמו עד י\"ב חדש עכ\"ל וז\"ל המרדכי בפרק אלו מגלחין רבינו טוביה היה מחמיר על האבל שלא לאכול בחופה תוך ל' כי אם עם המשמשים וכן נמי בסעודת מילה וכ\"ש עם הבחורים בחנויות דלא שרינן אלא סעודת מצוה דלית בה שמחה כגון קידוש החודש ועיבור השנה כדמפרש בירושלמי: ולענין הלכה כיון שהרמב\"ן והרא\"ש מסכימים לדעת אחת הכי נקטינן וכ\"ש שה\"ר יוסף מצא כדבריהם : כתב עוד ועל שבוע הבן רגיל לומר דלא הוי שמחה כדאיתא בפ\"ק דכתובות [ח.] דלא מברכים שהשמחה במעונו משום צערא דינוקא שטרודין בו ולא הוי שמחה גמורה עכ\"ל התוספות [מ\"ק כב:] כתבו בשם רבינו שמשון דבסעודת ברית מילה מותר ליכנס דלא חשיבא שמחה משום צערא דינוקא והר\"א לא היה מתיר דפשוט דגרע משמחת מריעות וגם פירש דאסור לאכול אפי' עם המשמשין ופסק דכניסה בלא אכילה שרי וז\"ל סמ\"ק בסעודת ברית מילה נוהגין להתיר ומורי הר\"י אבי הספר אוסר מפי רבותיו וכן ה\"ר טוביה היה אוסר בין בסעודת חתן בין בסעודת ברית מילה משום דהוא נקראת שמחה דכתיב (תהלים קי\"ט) שש אנכי על אמרתך וגם הוא מחמיר ואוסר לאכול עם המשמשים אם אינו אוכל בבית אחר במקום שאין מברכין שהשמחה במעונו עכ\"ל ובהגה\"א פרק אלו מגלחין בשם א\"ז כתב אסור לאכול בין עם החתן בין עם המשמשים עד לאחר שלשים יום ואפילו בחדר אחר שלא במקום החופה וכמדומה אני שאם היה צריך י' לחתן שאז מותר לו ליכנס ולאכול עם החתן עד כאן לשונו: וכתב הרוקח בסימן שנ\"ד דיום ב' שלאחר נישואים רגילים לאכול דגים ושאל לר\"י אם יכול האבל לאכול עמהם והשיב כשמפסיק מלומר שהשמחה במעונו שוב אינו נקראת סעודת שמחה אע\"פ שאסור בכל שמחת מרעות מיהו הכא כיון דהוו רגילים עד השתא למימר שהשמחה במעונו והשתא לא אמרי לא מיקרי סעודת שמחה עכ\"ל: וכתוב בתשוב' מהרי\"ל דבעל ברית ומוהל מותרי' די\"ט שלהם הוא וכ\"כ בפרנס דמהר\"מ תוך ל' של אביו היה בעל ברית ורחץ וכתב עוד שמותר ללבוש בגדי שבת עד אחר בית הכנסת אלמא דחשיב ליה כרגל מדשרי ליה בגדי שבת דגזירת ל' הוא כמו גיהוץ וכ\"כ תשב\"ץ דמותר בעל ברית והמוהל לאכול שם הלכך לע\"ד האוכל שם לש\"ש כשהוא בעל ברית ה\"ז זריז ונשכר עד כאן לשונו. והמרדכי כתב בשם כמה גדולים במ\"ק הלכה למעשה שמותר להיות בעל ברית ואסור ליכנס לסעודה ולענין הלכה כיון דמהרי\"ל דבתרא הוא מורה בה להקל הכי נקטינן וכבר נתבאר כיוצא בזה לענין ט\"ב בטור א\"ח סי' תקנ\"ט:"],["\u0003אבל אסור בשמחה כל ל' יום אפי' תינוק וכו'\u0004 נראה דה\"ק כל ל' יום שוין דאסור בשמחה אלא דאיכא חילוק בין שמחה לשמחה דלוקח תינוק בחיקו אסור כל ז' ותו לא כיון דאינה אלא חששא שמא מתוך כך יבא לידי שחוק והוא מימרא דרב פפא בסוף פ' אלו מגלחין אבל ליכנס לבית המשתה דאיכא ודאי שמחה אסור כל ל' על כל המתים אבל על אביו ואמו י\"ב חודש וכו' ומ\"ש ואף אם השנה מעוברת וכו' כ\"כ הרא\"ש ושאר פוסקים ודייקי לה מדקתני י\"ב חודש ולא קתני שנה ונראה כיון דמותר ליכנס לבית המשתה דאיסורו מפורש בברייתא כל שכן לישב במקומו וללבוש בגדי שבת שאינו אלא מנהג וכן מותר להסתפר דלגמרי הפסיק אבילות לאחר י\"ב חדש וכך אני מורה ובא דלא כיש שעושין פשרה בסברת הכרס:","\u0003אמר רב הוצא ולשמחת מריעות מותר ליכנס לאלתר וכו'\u0004 משמע מלשון רבינו מדכתב והגיע יום הפרעון בימי אבלו דאפילו תוך ז' מותר כיון שהגיע זמנו עכשיו לפרוע והיינו דקאמר לאלתר אבל הרמב\"ם בפ\"ו כתב מותר לעשותה אחר ז' אלמא דתוך ז' אסור והכי מסתברא וכן פסק בש\"ע:","ומ\"ש אין בו שמחה כמו בחופת חתנים פי' דאף ע\"פ דבחופת חתנים אסור תוך ל' כדתניא ולשמחה ל' יום התם בנישואין איכא שמחה אבל בסעודת מריעות ליכא שמחה כ\"כ וכן פירש\"י והקשה הרא\"ש ע\"ש הראב\"ד מדתני' באבל רבתי דלסעודת מצוה ומשתה דהיתה לשם שמים תוך ל' ולסעודת חתן הא איכא מצוה ולשם שמים ותירץ דלא שרינן לשם מצוה אא\"כ דיתבטל המעשה אם לא יכנס הוא לסעודה כגון משיא יתום ויתומה וכמ\"ש רבינו בסמוך אבל בנשואי עשיר שהזמינו לסעודה להתכבד בו אסור ליכנס שם תוך ל' ואפילו היכא דיתבטל המעשה לא שרינן תוך שלשים אלא באבל לשאר קרוביו אבל באביו ואמו אסור תוך שלשים לכל סעודת מצוה שבעולם. והא דכתב בהגהות ש\"ע בסתם אבל תוך ל' אסור לכל סעודת מצוה שבעולם אינו אלא באביו ואמו דסמיך ליה אבל לשאר קרובים מותר תוך ל' כמפורש בדברי רבינו:","\u0003ויש נוהגים וכו'\u0004 והם אומרים שלא אסרו אלא לאכול וכו' כצ\"ל כלומר טעמא שנוהגי' להקל מפני שאומרי' שלא אסרו ליכנס לבית המשתה אא\"כ נכנס ואוכל עמהם אבל ליכנס גרידא ואינו אוכל שרי והר\"י ברצלונ\"י כתב כן דיש נוהגין להקל בזה אבל כתב עוד ויש מחמירין מפני שמפרשים הא דתניא אסור ליכנס לבית המשתה בסתמא אפי' אינו אוכל עמהם משמע דבכניסה גרידא נמי איכא שמחה דפשיטא דשמח עמהם דלא גרע מהולך בדרך בשיירא דאסור מפני ששמחים בדרך ושמח עמהם כ\"ש בנכנס לבית המשתה והכי מסתברא וכתב רבינו שכ\"כ הרמב\"ן והרא\"ש ושכן נוהגין באשכנז דכל י\"ב חדש אינו נכנס לבית כלל אלא שומע הברכות מחוץ לבית וכתב בהג\"ה ש\"ע וכל זה בבית שעושין החתונה ואוכלין ושותין ושמחים שם אבל בחופה שעושין בב\"ה שמברכין שם ברכת אירוסין ונישואין ואין שם שמחה כלל מותר מיד אחר ז' ויש אוסרין עד ל' וכן נראה לי ושתי הסברות כתובים בהגהות מיימוניות בשם מהר\"ם ומביאו ב\"י מיהו באבל על שאר קרובים נראה דלד\"ה שרי לשמוע הברכות בחופה שעושין בב\"ה תוך שלשים וכתב עוד בהגהת ש\"ע ויש מקומות שמחמירין להיות האבל עומד כל י\"ב חודש חוץ לב\"ה לשמוע הברכות ומ\"מ נראה דאבל יכול לברך ברכת אירוסין ונשואין תחת החופה שבב\"ה וכן יוכל להכניס החתן כדרך ארצנו ששני אנשים מכניסין החתן תחת החופה ויוכל ללבוש קצת בגד שבת בשעה שמכניסין ובלבד שיהא אחר ל' וכן נוהגין עכ\"ל ונראה דכל שכן שיש להתיר לאבל על שאר קרוביו תוך ל' להכניס החתן כדרך ארצנו דטפי יש להתיר תוך ל' על שאר קרוביו מתוך י\"ב חדש על אביו ואמו כמו שנתבאר בסמוך בדין כניסה לסעודת נישואין דיתום ויתומה היכא דיתבטל המעשה אם לא יכנס שם עוד כתב בהגהות מיימונית וז\"ל ובסמ\"ג כתב אהא דתניא אם היתה סעודת מצוה מותר שרבינו יהודה וה\"ר יוסף מפי ר\"ת ור\"י היו מתירים לבא לסעודת חתן עכ\"ל. אכן מצאתי שכתב ה\"ר יוסף בפרק בתרא דמ\"ק אסור ליכנס למי שמת קרובו לבית המשתה כגון סעודת אירוסין ונשואין כדי לאכול אבל ליכנס בלא אכילה מותר ואין חילוק בדבר דאסור לאכול בין עם המשמשין עד ל' יום ועל אביו ואמו עד י\"ב חודש עכ\"ל הגהות מיימוני והב\"י העתיק לשונו בטעות כמו שהוא בדפוס ועל כן כתב ולענין הלכה כיון שהרמב\"ן והרא\"ש מסכימים לדעת אחת שלא ליכנס אף בלא אכילה הכי נקטינן וכ\"ש שהר\"ר יוסף מצא כדבריהם עכ\"ל דליתא אלא אדרבה הר\"ר יוסף התיר בפירוש ליכנס בלא אכילה מיהו ודאי נקטינן כהרמב\"ן וכהרא\"ש כמ\"ש ב\"י וכדפרי' בסמוך: ובסעודת ברית מילה כתבו התוס' ע\"ש רבינו שמשון דמותר לאבל לסעוד שם תוך ל' דלא חשיבא שמחה משום צערא דינוקא ורבינו טוביה מחמיר ואוסר תוך ל' דמשמע דשייך ביה שמחה דכתיב שש אנכי על אמרתך ונוהגין שלא לאכול בשום סעודה חוץ לבית בין אבל על שאר קרובים תוך ל' בין על אביו ואמו תוך י\"ב חודש ודוקא בסעודת ברית מילה או פדיון הבן וסיום מסכתא וכיוצא בזה אבל במשיא יתום ויתומה ואם לא יכנוס הוא לסעודה יתבטל המעשה איכא חילוק דלשאר קרובים מותר תוך ל' ועל אביו ואמו לא שרי אלא לאחר ל' כמ\"ש בסמוך. ואם האבל אינו יוצא מפתח ביתו מותר לאכול בסעודת מילה אפי' תוך ז' וכן בפדיון הבן ושאר סעודות שאין בהן שמחה כל כך אבל בסעודת נישואין יש להחמיר והכי משמע בת\"ה סימן רס\"ח בשם ריב\"א וכ\"כ בהגהת ש\"ע. כתב בהגהת אשיר\"י בשם א\"ז סוף מ\"ק דאין לאכול בין עם החתן בין עם המשמשים עד לאחר ל' יום ואפי' בחדר אחר שלא במקום החופה וכן נוהגין דלא כהסמ\"ק דמיקל בזה וכתב בהגהות ש\"ע אבל מותר לאבל תוך ל' לשמש שם אם ירצה ואוכל בביתו ממה ששולחין לו מן הסעודה. כתב הרוקח דביום ב' שלאחר נישואים דאין אומרים שהשמחה במעונו שוב אינה נקראת סעודת שמחה ומותר לאבל לאכול בסעודה של דגים ומביאו ב\"י ובהגהת ש\"ע. מיהו בליל ב' אע\"פ דנוהגין בקראקא שלא לברך שהשמחה במעונו אין לאבל לאכול באותה סעודה דלא דמי ליום ב' שכבר בעל בעילת מצוה בליל ב' כפי מנהגם ולכך עושין סעודה של דגים ביום ב' משום ברכת דגים כדאיתא בפ\"ק דכתובות הלכך אינה נקראת סעודת שמחה כיון שכבר נגמרו הנשואין ואין אומרים לא אשר ברא ולא שהשמחה במעונו אבל בלילה ב' מקמי בעילת מצוה דמברכין אשר ברא עדיין לא נגמרו הנשואין ומקרי סעודת שמחה ועיקר שמחה הויא באותה סעודה ומה שנהגו שלא לומר שהשמחה במעונו נראה שהוא מפני דמתאספין אנשים ונשים מועטים בחדר אחד ואיכא הרהורי עבירה ואין שמחה במעונו בדוכתא דאיכא איסורא כמ\"ש בספר החסידים משא\"כ בשבת במנחה דאיכא רוב עם ואנשים בלחוד ונשים בלחוד אבל הנישואין ודאי לא נגמרו בליל ב' מדברכין אשר ברא ולא בעל בעילת מצוה הלכך אסור לאבל לאכול באותה סעודה דליל ב' ובתשובה הארכתי יותר:"]],["\u0010c0\u0011\u0010y0\u0011כל ל' אסור לישא \u0010y1\u0011או ליארס אפי' בלא סעודת אירוסין ונשואין ולאחר ל' מותר אפי' על אביו ואמו ואפי' לעשות סעודות אירוסין ונשואין כדרכו \u0010c1\u0011\u0010y2\u0011והרמב\"ם כתב כל ל' לנישואים אבל ליארס מותר אפי' ביום המיתה \u0010c2\u0011\u0010y3\u0011ולא נהירא \u0010c3\u0011\u0010y4\u0011מתה אשתו אסור לישא אחרת עד שיעברו עליה ג' רגלים רבי יהודה אומר ראשון ושני אסור שלישי מותר ופסק הרמב\"ם כת\"ק \u0010y5\u0011והרי\"ץ גיאת והרמב\"ן פסקו כרבי יהודה ולזה הסכים א\"א הרא\"ש ז\"ל \u0010y6\u0011לא שנא אם הרגלים קרובים כמו פסח ועצרת לא שנא אם הם רחוקים \u0010y7\u0011אבל ר\"ה ויום הכפורים לא חשיבי כרגלים לדבר זה \u0010y8\u0011ודוקא לישא אסור אבל ליכנס לבית המשתה הוי דינא כמו בשאר קרובים \u0010c4\u0011\u0010y9\u0011והיא שמת בעלה אינה מתאבלת אלא ל' יום אלא שאסורה ליארס ולינשא עד ג' חדשים משום הבחנה כדאיתא ביבמות \u0010y10\u0011תניא אין לו בנים מותר לישא לאלתר משום פ\"ו ואם יש לו בנים קטנים מותר לישא לאלתר משום פרנסתן או \u0010y11\u0011אם אין לו מי שישמשנו מותר לישא לאלתר ופירש הרמב\"ן דלעולם אסור ל' יום וקורא אותו לאלתר משום דזמן נישואין אחרי מיתת אשתו ג' רגלים או ב' לכך קורא לאחר ל' יום לאלתר ושאר כל המפרשים פירשו לאלתר ממש תוך ל' \u0010y12\u0011אבל תוך ז' ודאי כתב ר\"ת שאסור לכנוס \u0010c5\u0011\u0010y13\u0011תניא אעפ\"כ אסור לבא עליה עד לאחר ל' יום \u0010y14\u0011ופר\"ת דהיינו דוקא למי שיש לו בנים קטנים או מי שאין לו מי שישמשנו שאין ממהר לישא אלא כדי שתשמשנו אבל מי שאין לו בנים וממהר לישא משום פריה ורביה מותר לכנוס ולבעול מיד אחר ז' והרמב\"ם לא חילק ובכולם התיר ליארס ולכנוס מיד ולבעול אחר ל' וא\"א הרא\"ש ז\"ל כתב כר\"ת \u0010c6\u0011\u0010y15\u0011וכל זמן שאין לו בן ובת חשיב לא קיים פריה ורביה היו לו בנים ומתו לא קיים פריה ורביה אבל הניחו בנים כבר קיים ל\"ש ברא לברא וברתא לברתא או ברא לברתא וברתא לברא ודוקא תרי מתרי אבל תרי מחד לא \u0010c7\u0011\u0010y16\u0011מעשה בא' ששדך ומת אחי המשודכת קרוב לחופה אחר שהזמין הקרואים והתיר ר\"ת שתכנס לחופה תוך ל' יום משום פריה ורביה שלו כיון ששדך זאת ואם לא ישאנה לא ישא אחרת \u0010y17\u0011אבל אם לא שדך אף על פי שחפץ בזאת יותר מבאחרת דבר זה אסור וכן הורה א\"א הרא\"ש ז\"ל הלכה למעשה לאחד ששדך והכין כל צרכי חופה ומת אחות המשודכת והוא לא קיים פריה ורביה והתיר לו לכנוס ולבעול אחר ז' שהיה סומך על ר\"ת כיון שהיה לו הפסד בדבר אם לא יכנוס אבל בלא הפסד אמר שלא היה מתיר:",["\u0003כל ל' יום אסור לישא בפרק אלו מגלחין (מועד קטן כג:) ת\"ר כל ל' יום לנישואין:\u0004 ","ומ\"ש או ליארס שם כתב הרא\"ש הא דקתני נישואין לאו משום דליארס שרי דהא תניא בפרק החולץ (יבמות מג:) רבי יוסי אומר כל הנשים יתארסו חוץ מן האלמנה מפני האיבול ל' יום אלא משום דרבותא דנישואין נקטיה לאשמועינן דנישואין שרי לאחר ל' יום וכן צ\"ל דאי ס\"ד דאיסור נישואין תוך ל' יום אתא לאשמועינן תיפוק ליה משום דאסור לילך לבית המשתה כל ל' יום ובנישואין כל ל' יום אף בלא סעודה איכא שמחה ואף לנישואין דאחר אסור למיזל ור\"ת היה אומר דס\"ד למשרייה בדידיה טפי מבאחריני ומתוך כך היה אומר ר\"ת אע\"ג דאסרינן באביו ואמו לבית השמחה י\"ב חדש שרי לישא אשה אחר ל' יום ואפי' יש לו בנים גדולים דלא אסרו אלא בית השמחה דליכא מצוה אבל נישואין אפי' יש לו כמה בנים איכא מצוה דאמרינן בפרק הבא על יבמתו (יבמות סב:) הלכה כר' יהושע דאמר ישא אשה בזקנותו וה\"ר יוסף הביא ראיה לדבריו דלא אסרינן אלא בית המשתה של רשות דאמרינן במסכת שמחות על כל המתים אסור לילך לבית המשתה עד ל' יום ועל אביו ואמו י\"ב חדש אא\"כ היתה סעודה של מצוה עכ\"ל וכ\"כ הרמב\"ן בת\"ה דודאי אפי' אירוסין בלא סעודה אסורים כל ל' כדתנן ר' יוסי אומר כל הנשים יתארסו חוץ מן האלמנה מפני האיבול וכדמפרשינן עלה בגמרא בדוכתא ובתשובה לרבינו האי התיר לישא אשה ולעשות סעודת אירוסין ונישואין לאחר ל' יום אפי' על אביו ואמו וכן עיקר עכ\"ל.","\u0003ומ\"ש רבינו שהרמב\"ם התיר ליארס אפי ביום המיתה הוא בפ\"ו:\u0004 ","ומ\"ש עליו ולא נהירא גם הרמב\"ן כתב עליו ולא דק דהא בהדיא איתמר התם כל ל' יום לאירוסין דוק ותשכח עכ\"ל. וטעמו של הרמב\"ם משום דאיכא למימר דהא דקתני חוץ מן האלמנה מפני האיבול ר' יוסי קתני לה ולא קי\"ל כוותיה א\"נ אף רבי יוסי לא אסר ליארס מפני האיבול אלא בסעודה אבל בלא סעודה מישרא שרי וה\"ק כל הנשים יתארסו בכל גווני אפי' בסעודה חוץ מן האלמנה דאיכא בה צד דאסורה ליארס מפני האיבול כגון בסעודה וטעמא דמפרשים הכי מדשרי בירושלמי ליארס אפי' בתשעה באב שמא יקדמנו אחר ברחמים כמ\"ש רבינו בהלכות תשעה באב אית לן למימר דבפרק אלו מגלחין בדוקא קתני נישואין אבל אירוסין מותר. והרמב\"ן והרא\"ש לא ילפי מהתם משום דאבילות ישנה שאני והרמב\"ם סבר דבחששא דשמא יקדמנו אחר ברחמים לית לן לפלוגי בין אבילות ישנה לחדשה: ולענין הלכה נקטינן כהרמב\"ם דמיקל באבל הוא ומסתבר טעמיה :","מתה אשתו אסור לישא אחרת עד שיעברו עליה ג' רגלים רבי יהודה אומר ראשון ושני אסור ג' מותר בפרק אלו מגלחין (שם) ומ\"ש שפסק הרמב\"ם כת\"ק הוא בפ\"ו:","ומ\"ש שהרי\"ץ גיאות והרמב\"ן פסקו כרבי יהודה בת\"ה כתב ומסתברא כרבי יהודה דהלכה כדברי המיקל באבל וכ\"כ הרי\"ץ גיאת ז\"ל ולזה הסכים הרא\"ש בפרק אלו מגלחין ומדברי הרי\"ף נראה שסובר כדברי הרמב\"ם וכתבו הגה\"מ שכן דעת ר\"ח וראבי\"ה וריצב\"א ורשב\"ם וכתוב בכתבי מהר\"ר איסרלן בסי' א' דכן נראה לו עיקר. ולפי דרך פסק שלנו ג\"כ כיון שהרי\"ף והרמב\"ם מסכימים לדעת אחת הכי נקטינן.","\u0003ומ\"ש ל\"ש אם הרגלים קרובים וכו':\u0004 ","ומ\"ש אבל ר\"ה וי\"ה לא חשיב כרגלים לדבר זה כן כתב הרא\"ש בפרק א\"מ ז\"ל ויש שהיו רוצים לומר שאם מתה אשתו קודם ר\"ה שישא אחרת אחר הסוכות דקי\"ל דר\"ה ויה\"כ כרגלים ולא מסתבר כלל דהא דהצריכו להמתין ג' רגלים לאו משום תוספת אבילות אלא כדי שתשכח ותשקע הראשונה מדעתו בשעה שהוא עם השנייה כדתניא [נדרים כ:] ולא תתורו אתרי לבבכם מכאן א\"ר נתן לא ישתה אדם בכוס זה ויתן עיניו בכוס אחר וא\"ר אלעזר לא נצרכה אלא לב' נשיו הילכך צריך הרחקת זמן ואין ר\"ה וי\"ה כרגלים בדבר זה אלא קבעו הדבר והזמן ברגלים אע\"פ שאין הרחקת הזמן שוה בהם מ\"מ שמחת הרגלי' מסייעת השכחה מדעתו ע\"כ וכ\"כ הרמב\"ן בת\"ה וכתב המרדכי בסוף מ\"ק ששאלו למור\"ם על אחד שהיה תפוס והתנה לו השר להוציאו אם ישא אותה אשה שרוצה לתת לו ועברו עליו ר\"ה ויוה\"כ וסוכות ממיתת אשתו והשיב דלא חשיבי רגלים ואין להתיר לו כדי שיתירוהו מפני הצער כי היכי דשרי למי שיש לו בנים קטנים דאין לסמוך על דברי השר ואפי' אם יתירו השר אין זה דומה למי שהניחה לו אשתו בנים קטנים דשרי מתוך חיי הבנים עכ\"ל ואני אומר אם לדין יש תשובה שאם מפני חיי הבנים התירו כ\"ש מפני חייו שאפשר שימות מחמת צער התפיסה ועוד דהו\"ל כשבוי דכולהו איתנהו ביה ואפי' מספק שמא יקיים השר דברו ראוי להתיר לו וכ\"ש דאפשר לו שלא לבא עליה עד שיגיע זמן וכי ההיא דיוסף הכהן ועוד יש לתמוה עליו דאטו מי גרע צער דתפיסה ממי שאין לו מי שישמשנו:","\u0003ומ\"ש ודוקא לישא אסור אבל ליכנס לבית המשתה דינא כשאר קרובים פשוט הוא.\u0004 ","ומ\"ש והיא שמת בעלה אינה מתאבלת אלא ל' יום כן משמע מדתניא בפ' החולץ (יבמות מג:) ר' יוסי אומר כל הנשים יתארסו חוץ מן האלמנה מפני האיבול ואיתמר עלה כמה איבול שלה ל' יום ומ\"ש אלא שאסורה ליארס ולינשא עד ג' חדשים משום הבחנה כדאיתא ביבמות פרק החולץ (יבמות מג.) ומשמע התם דהלכה כר\"מ דאמר הכי וכ\"פ כל הפוסקים כמו שיתבאר בטוא\"ה סי' י\"ג והמרדכי בסוף מ\"ק כתב הטעם שאין האשה צריכה להמתין ג' רגלים משום דאשה בבעל כל דהו ניחא לה: כתב הרמב\"ם בפ\"ו וכן האשה שהיתה אבילה לא תבעל עד ל' יום וכתב עליו הרמב\"ן בת\"ה משמע דנשאת היא מיד ולא דק דאנן אפי' באירוסין תנן חוץ מן האלמנה מפני האיבול וכמה ל' יום עכ\"ל ואני אומר דהא ל\"ק דאיכא למימר דכיון דסבר הרמב\"ם דמותר ליארס ביום המיתה כמו שנתבאר ממילא לא קי\"ל כר\"י דחייש לאיבול וא\"נ קי\"ל כר\"י למי שיש לו בנים קטנים מותרת לינשא כההיא דיוסף הכהן שמתה אשתו ואמר לאחות אשתו לכי ופרנסי את בני אחותך אבל אי קשיא הא קשיא דמשמע ודאי דלא מיירי בשהיא אבילה אשאר קרובים דכיון דהאיש אינו אסור בתשמיש המטה אלא תוך ז' למה תאסר האשה אחר ז' אלא באשה שהיתה אבילה על בעלה מיירי וקאמר דכשם שהאיש שמתה אשתו ולא קיים מצות פריה ורביה או שיש לו בנים קטנים או אין לו מי שישמשנו אע\"פ שמותר לו לכנוס מיד אסור לו לבא עליה עד ל' יום כן האשה שמת בעלה ונשאת מיד לא תבעל עד ל' יום וכיון דקי\"ל דכל הנשים אסורות ליארס ולינשא עד ג' חדשים משום הבחנה ואפי' שם אינן ראויות לילד וכמו שפסק הוא ז\"ל בהלכות גירושין היכי משכחת לה אלמנה נשאת בתוך ל' יום ואפי' עברה ונשאת אסורה היא ליבעל עד ג' חדשים והיאך התיר שתבעל לאחר שלשים ואפשר לומר דה\"ק מתורת איבול על בעלה אסורה להבעל כל ל' יום ואילו לא היה אלא משום איבול בלבד היתה מותרת להבעל אחר ל' אבל משום הבחנה אסורה להבעל עד ג' חדשים וסמיך על מ\"ש בהלכות גירושין:","\u0003תניא אין לו בנים מותר לישא אשה לאלתר וכו'\u0004 עד משום פרנסתן בפרק אלו מגלחין:","\u0003ומ\"ש שאם אין לו מי שישמשנו מותר ג\"כ לישא אשה לאלתר ירושלמי בפרק החולץ פסקוהו הפוסקים.\u0004 ומ\"ש שפירש הרמב\"ן דלעולם אסור ל' יום וכו' בת\"ה. ומ\"ש ושאר כל המפרשים פירשו לאלתר ממש תוך ל' מבואר בפסקי הרא\"ש פ' אלו מגלחין: ולענין הלכה נקטינן כדברי שאר מפרשים דרבים נינהו:","ומ\"ש אבל תוך ז' כתב ר\"ת שאסור ליכנוס ג\"ז שם ובתוספות פרק קמא דכתובות (ד.).","ומ\"ש תניא אף על פי כן אסור לבא עליה עד לאחר ל' יום גם זה בפרק אלו מגלחין בברייתא (מועד קטן כג.).","\u0003ומ\"ש שפר\"ת דהיינו דוקא למי שיש לו בנים קטנים וכו'\u0004 כ\"כ שם הרא\"ש בשמו ובשם הראב\"ד ז\"ל וכ\"כ המרדכי ג\"כ שם בשם ר\"ת. ומ\"ש בשם הרמב\"ם הוא בפ\"ו ובתשובת הרא\"ש כלל כ\"ז סימן י' כתוב שמדברי הרי\"ף נראה שהוא סובר כדברי הראב\"ד ור\"ת שמדברי הרמב\"ם נראה שאינו מחלק בין נושא מפני פריה ורביה לנושא מפני שאין לו מי שישמשנו ותמה הוא דסברא הוא לחלק בינייהו: ולענין הלכה כיון שהרי\"ף ור\"ת והראב\"ד והרא\"ש מסכימים לדעת אחת הכי נקטינן:","\u0003ומ\"ש וכל זמן שאין לו בן ובת חשיב לא קיים מצות פריה ורביה וכו'\u0004 עד אבל תרי מחד לא כ\"כ הרי\"ף והרא\"ש בפרק אלו מגלחין והוא מסקנא דגמרא דס\"פ הבא על יבמתו (ס\"ב): כתב המרדכי בסוף מ\"ק ה\"ר חיים רצה להתיר לישא אשה לר' אליעזר לאלתר מדמסיק בפרק הבע\"י (שם) נשא בבחרותו ישא בזקנותו משום פריה ורביה משמע דלא קי\"ל כברייתא דמ\"ק והריב\"ם לא הניחו:","\u0003ומ\"ש רבי' מעשה באחד ששידך ומת אחי המשודכת וכו'\u0004 והתיר ר\"ת שתכנס לחופה תוך ל' וכו' בפסקי הרא\"ש פ' אלו מגלחין:","\u0003ומ\"ש אבל אם לא שידך וכו'\u0004 דבר זה אסור שם כתבו הרא\"ש והמרדכי והגה\"מ פ\"ו כלשון הזה ושמא אפי' אם לא היה משודך היה מתיר מאחר שחפץ בה יותר מאחרת כדאשכחן ביוסף הכהן שמתה אשתו ואמר לאחותה בבית הקברות לכי ופרנסי בני אחותיך כדאיתא פ' אלו מגלחין (מועד קטן כג.) דמשתריא איהי משום פרנסת בניו ואע\"פ שהיתה אבילה מאחותה ומיהו איכא למימר לפי שמרחמת על בני אחותה יותר מאחרת עכ\"ל ומדברים אלו יתבאר לך שיש קיצור בדברי רבינו שהו\"ל לכתוב דלישא אחות אשתו אפי' לא שידך מותר אם יש לו בנים קטנים כההיא דיוסף הכהן ואותו מעשה שהורה הרא\"ש ואמר שבלא הפסד לא היה מתיר לא היתה אחות אשתו: כתוב בפסקי התוספות אין לו מי שישמשנו כי אם בנות גדולות אם אינן אצלו יש לו להקל ואם הן אצלו יש לו להחמיר כי יש לו מי שישמשנו ובנים גדולים צ\"ע אך הכל לפי צרכי שמוש ואם הוא עשיר להשכיר שמשים נראה להחמיר עכ\"ל. ובכתבי מהר\"ר איסרלן סימן ג' כתוב ובההיא דאין לו מי שישמשנו כתבו תשובה דאפי' אם הוא עשיר ויש לו משרתים די אם אין בתו או כלתו אתו שישמשנו בחפיפת הראש ובכיבוס בגדים שאין ראוי לו להשתמש באחרות כה\"ג אז שרי ע\"כ: ובתשובות מיימוניות דשייכי להלכות אבל צידד רשב\"א לבקש צדדי היתר לאיש שמתה אשתו שישא תוך ג' רגלים ור\"י אחיו סותר דבריו ע\"ש ובכתבי מהר\"ר איסרלן סימן נ\"א כתוב נראה דסומכין העולם אאותן צדדין שצידד רשב\"א להתיר:"],["\u0003כל ל' אסור לישא או ליארס וכו'\u0004 בפרק אלו מגלחין (מועד קטן דף כ\"ג) מוכח דל' יום בין לנישואין בין לאירוסין וטעמא משום דאיכא שמחה אפי' בלא סעודה והא דמותר לאחר ל' אף באביו ואמו היינו משום דקא מקיים מצוה דפרו ורבו ואפילו יש לו כמה בנים איכא מצוה דהלכה כרבי יהושע דאמר ישא אשה בזקנותו ולא דמי למשיא יתום ויתומה דקא מקיים מצוה ואפ\"ה לא שרי באביו ואמו ליכנס למשתה אפי' לאחר ל' דהתם לא קעביד מצוה בעצמו אלא מעשה לאחרים אבל הכא עושה מצוה בעצמו וצריך עליה שרי לאחר ל' ודמי למשיא יתום ויתומה שאם לא יכנס הוא שם יתבטל המעשה וכן חבורת מצוה כגון אכילת פסח וקדשים ומעשר שני וכיוצא בזה דברים שצריך הוא לעשותם בעצמו אף על פי דאיכא שמחה שרי לאחר ל':","\u0003ומ\"ש והרב רבינו משה בר מיימוני כתב וכו'\u0004 טעמו דמפרש הא דאמרינן כל ל' לאירוסין היינו בסעודה אבל בלא סעודה שרי פן יקדמנו אחר ברחמים כמו שהתירו ליארס אפי' בט\"ב עצמו מה\"ט גופיה.","ומ\"ש רבינו ולא נהירא ס\"ל דפשט הסוגיא משמעה כל ל' לאירוסין אפי' בלא סעודה ומט\"ב אין ראיה דבאבילות ישנה הקילו טפי והרב רבינו משה בר מיימוני סבר דבחששא דשמא יקדמנו ברחמים ליכא לפלוגי בין אבילות ישנה לחדשה וכן פי' ב\"י ופסק כהרמב\"ם אבל דעת הרמב\"ן והרא\"ש כדעת רבינו וכן עיקר מיהו לקשר עצמו בשידוכין בלא אירוסין ודאי מותר אפי' ביום המיתה:","\u0003מתה אשתו וכו'\u0004 שם [בדף כ\"ג] וטעמא דת\"ק כיון דצריך שישכח אהבת אשתו הראשונה שלא יהיו ב' דעות במטה אם כן צריך שלשה רגלים דלאחר שעברו עליו שמחה של שלשה רגלים לא יהא זכור שוב מן הראשונה ור\"י סבר דכשעברו עליו שמחת שני רגלים שוב לא יהא זכור מן הראשונה ואפשר דפלוגתייהו תלוי בפלוגתא אי בתלתא זימני הוי חזקה כרבי או בתרי זימני הוה חזקה כרבן שמעון בן גמליאל דקיימא לן בנישואין ומלקיות כרבי ווסתות ושור המועד כרבן שמעון ב\"ג וכדאיתא בפרק הבע\"י (יבמות סוף דף ס\"ד) ונראה לפי זה דאין לומר כאן הלכה כדברי המיקל באבל דמטעם זה פסק הרמב\"ן כרבי יהודה דהא לא פליגי באבילות אלא בחזקה כדפרי' ועוד כתבו התוס' לשם דאין לומר הלכה כר\"י משום דקי\"ל הלכה כדברי המיקל באבל דהא מילתא דפליגי בה הכא אין זו באבל דימי אבלו כבר כלו להן עכ\"ל וא\"כ לפי זה הלכה כת\"ק דהם רבים לגבי יחידאה וכן הוא דעת רוב הפוסקים והכי נקטינן וכן פסק מהרא\"י בכתביו ריש ספרו ע\"ש:","\u0003והיא שמת בעלה וכו'\u0004 ה\"א בפרק החולץ (יבמות דף מ\"ג) וה\"א בירושלמי הביאו הרי\"ף והרא\"ש בפרק אלו מגלחין. וכתב המרדכי הטעם דאיש דוקא לא ישכח אהבת אשתו הראשונה עד ג' וב' חדשים אבל אשה בבעל כל דהו ניחא לה ושוכח אהבת הראשון אחר ל' יום: ומ\"ש אלא שאסורה ליארס ולינשא עד שלשה חדשים ה\"א פ' החולץ (יבמות דף מ\"א) ותימה על מה שכתב הרמב\"ם וכן האשה שהיתה אבילה לא תבעל עד ל' יום דאי באבילה על שאר קרובים מיירי ודאי דמותרת בתשמיש לאחר ז' כמו האיש ואי באבילה על בעלה מיירי ונשאת תוך ל' שלא כדין הלא אסורה להבעל עד לאחר ג' חדשים משום הבחנה ותירץ ב\"י כאן וכן בכסף משנה דמיירי באבילה על בעלה וה\"ק מתורת איבול אינה אסורה אלא עד לאחר ל' אבל משום הבחנה אסורה להבעל עד שיעברו ג' חדשים וסמך על מ\"ש בהל' גירושין עכ\"ד ושרי ליה מאריה דהיאך יכתוב הרמב\"ם בלשון פסק דין לא תיבעל עד ל' יום כיון דאף לאחר ל' נמי לא תיבעל מוטב היה שלא יכתוב דבר ולא יתן מכשול לפני הקורא למי שלא יהא זכור מ\"ש בה' גירושין ויורה טעות להיבעל אחר ל' יום אלא היה לו לסמוך על מ\"ש בה' גירושין ונראה פשוט דמיירי באבילה על שאר קרובים ואע\"פ דהיכא דלא נשאת אינה אסורה בתשמיש אלא תוך ז' כמו איש הכא דנשאת באבילה החמירו גם באשה דאסורה עד ל' יום והאי וכן האשה שכתב הרמב\"ם קאי אתחלת דבורו שכתב לשם בנישואין כיצד אסור לישא אשה כל שלשים וכו' עד ואסור לו לבא עליה עד ל' יום אלמא שהחמירו באיש שנשא אשה בימי אבלו שלא לבא עליה עד ל' יום ואע\"פ שעשה כדין ומכל שכן היכא שנשאה שלא כדין כגון שקיים פריה ורביה ונשאה בימי אבלו דפשיטא דאסור לבא עליה עד ל' יום וע\"ז קאמר הרמב\"ם וכן האשה שהיתה אבלה על שאר קרובים ונשאת תוך ימי אבלה שלא כדין לא תבעל עד ל' יום דאיש ואשה שוין דכי היכי דאיש שנשא באבלו אסור לו לבעול עד ל' יום אף על פי שאינו אבל אלא משאר קרובים הכי נמי באשה ואם לא נשא באבלו דמותר לו לבעול אחר ז' ה\"נ באשה דאין חילוק בין איש לאשה באבלן על שאר קרובים אלא בין נישאו ובין לא נישאו כנ\"ל ודו\"ק: עוד כתב הרמב\"ן על דברי הרמב\"ם שכתב וכן האשה וכו' וז\"ל משמע דנשאת היא מיד ולא דק דאנן אפילו באירוסין תנן חוץ מן האלמנה מפני האיבול וכמה שלשים יום עכ\"ל ולמאי דפרישית ניחא דהרמב\"ם לא קאמר דנשאת היא מיד אלא דאם עברה ונשאת וכך צריך לפרש להרמב\"ן גופיה הך ברייתא דתניא אף על פי כן אסור לבא עליה עד לאחר שלשים יום דמיירי בעברה ונשאת כמו ש כתוב בסמוך: תניא אין לו בנים וכו' ופירש הרמב\"ן וכו' פי' הרמב\"ן סובר דאסור כל ל' יום כדתני כל ל' יום לנישואין דסתמא תניא ובכל אבל קאמר דאסור ל' יום לא לישא ולא ליארס אלא דהכא במתה אשתו תניא דאם לא קיים פריה ורביה א\"צ להמתין ג' רגלים או ב' אלא כונס לאלתר אחר ל' יום ולפי זה קשה היכי תניא אף על פי כן אסור לבא עליה עד לאחר ל' יום הלא אפילו לארוס אותה אסור עד אחר ל' יום וצריך לומר דהך ברייתא מיפרשא להרמב\"ן דמיירי בעבר וכנס לאלתר תוך ל' דאף על פי כן אסור לבא עליה עד לאחר שלשים יום ואם כן צריך שמירה הוא ישן בין האנשים והיא ישנה בין הנשים ושאר כל המפרשים פירשו לאלתר ממש תוך ל' דהשתא ניחא הא דתניא אף על פי כן אסור לבא עליה עד לאחר ל':","\u0003תניא אף על פי כן וכו'\u0004 ופר\"ת וכו' טעמו דהיכא דאינו נושא אשה מפני שיש לו בנים או אין לו מי שישמשנו אלא משום פריה ורביה ודאי מותר לכנוס ולבעול מיד אחר ז' דאי אסור לבעול עד לאחר ל' לאיזה צורך התירו לו לכנסה תוך ל' משום פריה ורביה הלא לא יבא אליה ולא מקיים פריה ורביה מיהו תוך ז' ודאי כיון דאסור בתשמיש המטה אסור נמי לכנסה: ומ\"ש והרמב\"ם לא חילק וכו' פירוש דהרמב\"ם מפרש כפשוטו דמותר לכנוס מיד אפי' תוך ז' וכ\"כ בכסף משנה דלהרמב\"ם מותר לכנוס תוך ז' ואף ע\"פ דאבל אסור כל ז' בתשמיש המטה ועוד דאוסרה עליו שלא יבא אליה עד ל' יום אפ\"ה מותר לכנסה מיד תוך שבעה כיון דבכניסה כדי לקיים מצות פריה ורביה קעביד מצוה רבה ודו\"ק ולענין הלכה פסק בש\"ע דבאין לו מי שישמשנו או יש לו בנים קטנים מותר לו לקדש מיד ולכנוס אחר ז' ולא יבא עליה עד לאחר ל' ואם לא קיים מצות פריה ורביה מותר לבא עליה אחר ז' והא דפסק דמותר לקדש מיד הוא לדעת הרמב\"ם דמתיר לקדש אפילו ביום המיתה ולא קי\"ל הכי כדלעיל בסעיף ב' אלא רשאי לקדשה ולכנסה מיד אחר ז' ולא יבא עליה עד לאחר ל' אא\"כ לא קיים פריה ורביה דמותר לבא עליה אחר ז':","\u0003ומ\"ש וכל זמן שאין לו בן ובת כו'\u0004 מבואר באבן העזר סימן א':","\u0003מעשה באחד וכו'\u0004 וכן הורה א\"א הרא\"ש ז\"ל הלכה למעשה לאחד ששידך וכו' לכאורה קשה דלא היה צריך לספר המעשה שנעשה אלא סתם יאמר וכן הורה הרא\"ש הלכה למעשה וי\"ל דלפי דבמעשה של ר\"ת לא אמר אלא שר\"ת התיר שתכנס לחופה תוך ל' יום משום פריה ורביה שלו ומשמע דבכניסה לחופה לשם פריה ורביה מקיים מצות פריה ורביה אע\"פ שלא יבא עליה עד לאחר ל' כדפרישית בסמוך סעיף ו' להרמב\"ם לכך מספר המעשה שהתיר הרא\"ש לכנוס ולבעול אחר ז' וכו': כתב בהגהת ש\"ע וכן אם יש לו בנים קטנים ונתרצה לאחות אשתו מותר לכנסה כי היא מרחמת על בני אחותה יותר מאחרת עכ\"ל והוא מדברי הרא\"ש והמרדכי מיהו ודאי אע\"פ שמותר לכנסה מ\"מ לא יבא עליה עד לאחר שלשים כדלעיל:"]],["\u0010c0\u0011\u0010y0\u0011אבל כל ג' ימים הראשונים אינו יוצא לבית האבל ולא לבית הקברות ומכאן ואילך הולך ואינו יושב במקום המנחמין \u0010c1\u0011אלא במקום המתנחמין וכן הדין ביציאתו לבית הקבר ג' ימים הראשונים אינו יוצא מכאן ואילך הולך ועומד בשורה אצל האבל \u0010c2\u0011\u0010y1\u0011תניא אבל שבת ראשונה פי' שבוע ראשונה אינו יוצא מפתח ביתו \u0010y2\u0011אפי' לדבר מצוה כגון למילה וכיוצא בו שנייה יוצא ואינו יושב במקומו ואינו מדבר שלישית יושב במקומו ואינו מדבר רביעית הרי הוא כשאר כל אדם \u0010c3\u0011\u0010y3\u0011אפילו לא שלמו ג' שבועות כגון שמת באמצע שבוע מיד כשכלתה אותה שבוע וב' של אחריה חשוב רביעית דלא בעינן מעת לעת \u0010c4\u0011\u0010y4\u0011ולענין יציאת האבל לבית הכנסת כתב הרי\"ץ גיאת שיוצא אפי' בחול \u0010y5\u0011והראב\"ד כתב שאפי' בשבת אינו יוצא \u0010c5\u0011\u0010y6\u0011ואינו כדברי שניהם אלא בחול אינו יוצא כל עיקר ובשבת תלוי במנהג וכ\"כ רב האי שהכל כמנהג המדינה היכא דרגילי דאתי לבי כנישתא מקדים ואתי מצפרא קמי צבורא לבי כנישתא והיכא דרגילי למיתב בביתיה יתיב ובבבל בכפרים כולי עלמא נפקי לבי כנישתא ובכרכים ועיירות גדולות רובן יושבין בבתיהן וריעיהן וגומלי חסד באין עליהן ומיעול עיילי לבי כנישתא ויתבי במקום אבילים ומצלי וכ' \u0010y7\u0011א\"א הרא\"ש ז\"ל ונוהגין באשכנז שהאבל הולך לב\"ה בשבת ואחר התפלה יוצא האבל תחילה ויושב לפני ב\"ה וכל הקהל הולכין אחריו ויושבין אצלו ועומד האבל והולך לביתו וכל הקהל הולכין אחריו ויושבין שם שעה אחת \u0010y8\u0011וסומכין על דבר הגדה בפרקי רבי אליעזר ראה שלמה המלך שמדת גמילות חסדים גדולה לפני הקב\"ה לפיכך כשבנה ב\"ה בנה שני שערים אחד לחתנים ואחד לאבילים ולמנודים והיו ישראל הולכים בשבתות בין השערים הללו הנכנס בשער חתנים יודעין שהוא חתן ואמרו לו השוכן בבית הזה ישמחך בבנים ובבנות הנכנס בשער האבילים ושפמו מכוסה היו יודעין שהוא אבל ואומרים לו השוכן בבית זה ינחמך והנכנס בשער האבלים ואין שפמו מכוסה היו יודעין שהוא מנודה ואומרים לו השוכן בבית זה יתן בלבך לשמוע דברי חבירך ויקרבוך משחרב ב\"ה התקינו חכמים שיהיו חתנים ואבילים הולכין לבתי כנסיות ולבתי מדרשות ואנשי המקום רואין את החתן ושמחים עמו ואת האבל \u0010c6\u0011ויושבין עמו לארץ כדי שיצאו כל ישראל ידי חובתן בגמילות חסדים ועליהם הוא אומר ברוך נותן שכר טוב לגומלי חסדים:",["\u0003אבל כל ג' ימים הראשונים אינו יוצא לבית האבל וכו'\u0004 בפרק אלו מגלחין (מועד קטן כא:) ת\"ר אבל כל ג' ימים הראשונים אינו הולך לבית האבל מכאן ואילך הולך ואינויושב במקום המנחמים אלא במקום המתנחמים. ומ\"ש וכן ביציאתו לבית הקבר וכו' כ\"כ המרדכי על ברייתא זו וז\"ל מכאן ראיה כשהולך האבל עם שאר אבלי מתים לבית הקברות שיש לו לעמוד אצל האבילים בשעת צ\"ה וי\"א ב' ימים הראשונים אינו הולך לבית הקברות ללות המת עכ\"ל: וכ\"כ הגה\"מ בפ\"ז . תניא באבל רבתי פ\"ו על ברייתא זו בד\"א בזמן שיש שם כדי נושאי המטה וקובריה אבל אין שם כדי נושאי המטה וקובריה יוצא עמהם אפי' ביום הראשון ופשוט הוא שהרי הוא חייב בכל המצות וכיון שאין שם כדי נושאי מטה וקובריה יהא המת מוטל בבזיון אם לא יצא הוא לסייעם וז\"ל הרמב\"ן בת\"ה באבל תניא אבל ג' ימים אינו יוצא אחר המטה מג' ועד ז' יוצא בשכונתו אבל לא בשכונה אחרת פי' כשמת לאחרים מת בשכונתו יוצא אחר המטה לבית הקברות. כתוב בתה\"ד סימן ר\"צ אבל שרי לצאת מפתח ביתו בלילה לאחר שכלתה הרגל מן השוק או לא. תשובה יראה דהמיקל בכה\"ג מפני הצורך לא הפסיד כולי האי ונתן טעם לדבר :","\u0003תניא אבל שבת ראשונה אינו יוצא מפתח ביתו וכו'\u0004 עד רביעית הרי הוא כשאר כל אדם פרק א\"מ [כג.] ומה שכתב פי' שבוע ראשון כ\"כ שם הרא\"ש בשם רש\"י וכ\"נ מדברי הרמב\"ם פ\"ז:","\u0003ומ\"ש אפי' לדבר מצוה וכו'\u0004 כן כתב בתשובת הרא\"ש כלל כ\"ז וכתב שם והא דקשיא לך דאבל חייב בכל המצות היינו במצות עשה שבגופו כגון ציצית ותפילין או למול את בנו אבל לילך לחופה ולמילה לשמוע ברכה בשביל גמילות חסדים אין לו לצאת מפתח ביתו. וכ\"כ רבינו ירוחם בשם המפרשים ובהגהות אשיר\"י כתוב דמוהל דחל עליו מילה תוך ימי אבלו בג' ימים הראשונים אל יצא מפתח ביתו ובשאר הימים יתפלל בביתו ואח\"כ ילך לב\"ה וימול ואבל מותר להיות בעל ברית ויתפלל בביתו וכשמביאין הנער לב\"ה לימול ילך ויהיה בעל ברית עכ\"ל ונראה שאם היא מצוה שתיבטל או תדחה אם לא יצא האבל שיוצא דומיא דההיא דאין שם כדי נושאי מטה וקובריה דבסמוך ולדידן שהאבל יוצא לב\"ה להתפלל בשני וחמישי מפני קריאת התורה כ\"ש שיצא כדי למול אפי' תוך ג' ימים ראשונים ואפילו יש שם מוהל אחר . וכתב נימוקי יוסף אהא דתניא מכאן ואילך הולך וכו' ואע\"ג דאמרינן אבל אינו יוצא מפתח ביתו היינו דוקא לטייל אבל לדבר מצוה שרי ומתוך כך נראה דמותר לאבל ללכת לב\"ה לשמוע תפלה או מגילה וכ\"ש בט\"ב שכולם אבילים והו\"ל כהולך לבית האבל עכ\"ל וגם הרא\"ש כתב מכאן נהגו באשכנז שבליל ט\"ב הולך לב\"ה וכן למחרת עד גמר קינות ואז הולך לביתו:","\u0003ומ\"ש אפילו לא שלמו ג' שבועות וכו'\u0004 בסימן שצ\"ט כתב רבינו בשם ה\"ר שמשון דאם קבר מתו שעה א' לפני הרגל שאותה שעה והרגל חשובים כי\"ד ומיד אחר הרגל יש לו דין שבוע ג' ואפי' בר\"ה ועצרת שאינו אלא יום א':","ומ\"ש ולענין יציאת האבל לב\"ה כתב הרי\"ץ גיאת שיוצא אפי' בחול כ\"פ הרמב\"ן בת\"ה בשמו וטעמו משום דהשתא לבית האבל הולך מג' ימים ואילך לבית התפלה לא כ\"ש וג' ימים הראשונים לבית האבל אינו יוצא לבית התפלה יוצא ודחה הרמב\"ן דבריו:","ומ\"ש רבינו בשם הראב\"ד כ\"כ הרא\"ש בפרק אלו מגלחין בשמו וטעמו מפני שהוא ז\"ל מפרש שבת ראשונה דקתני בברייתא היינו שבת ממש דאינו יוצא לב\"ה בשבת והכי איתא באבל רבתי שאינו הולך לב\"ה אבל לבית המדרש הולך בשבת אבל לא בחול וכך פירש הרמב\"ן בת\"ה:","\u0003ומ\"ש רבינו ואינו כדברי שניהם וכו'\u0004 וכ\"כ רב האי שהכל כמנהג המדינה וכו' הרמב\"ן בת\"ה כתב תחילה כדברי הראב\"ד ז\"ל דאפי' בשבת אינו יוצא לב\"ה ואח\"כ כתב דברי רבינו האי ואח\"כ כתב דברי הרי\"ץ גיאת וכתב לסתור דעתו וכתב בסוף דבריו וכל זה לשבור דברי הרי\"ץ גיאת שהוא מנהיג לאבילים לצאת לב\"ה בחול אבל תשובת רבינו האי שכתבנו למעלה אפשר שהיא עולה ולא אמר הגאון לצאת לב\"ה בחול אלא בשבת לפי שאין אבילות בשבת ויפרש הגאון שבת שבוע של ימי אבילות בחול וכן פירש\"י וכן נהגו כדעה הזאת לצאת שם בשבת ולא בחול כל ז' ויש להם על מה שיסמכו בדברי הגדה שכך מצינו בפרקי ר\"א ראה שלמה שמדת ג\"ח גדולה לפני הקב\"ה וכו' עכ\"ל ופי' זה הוא בפי\"ו: \u0005ב\"ה וכתב הריב\"ש בתשובה סי' קנ\"ה שנשאל על מקום שנוהגים לצאת לב\"ה בבוקר כל ז' ימי אבילות והשיב בסרקסטא נוהגים האבילים כל ז' ללכת לב\"ה שחרית וערבית ואחר התפלה כשחוזרים לבתיהם עם רוב הקהל המלוים אותם בכניסתם לחצר המקוננת מעוררת לווייתם והנשים סופדות וכיון שעושים זה לכבוד המת אין לבטל מנהגם וכן י\"ל במנהג עירכם כיון שאין הולכים אלא לב\"ה אם לספוד על המת או לומר עליו ניחום נפש אין לבטל מנהגם כיון שהוא לכבוד המת שהרי אפי' להלין המת שהוא אסור מן התורה אם הלינו לכבודו מותר:\u0006","ומ\"ש רבינו בשם הרא\"ש הוא בפרק אלו מגלחין ודבריו הם מבוארים שהם כדברי הרמב\"ן שכתבתי בסמוך והכי נקיטינן וכתב המרדכי במ\"ק על הא דפרקי ר\"א ואע\"פ דבפרהסיא הוא מקום מצוה שאני ומשום פרהסיא אמרי (שבת יב:) בקושי התירו לנחם אבילים בשבת והא דקאמר שיושבים עמו לארץ משום שרוב עם לא סגי להו בלא\"ה ומשנה מקומו כדי שירגישו הכל כדאמרי' לעיל שנייה יוצא ואינו יושב במקומו ונהגו משום כבוד המת שגם שאר קרובים משנין מקומותם אבל בשבת א' אינו יוצא מפתח ביתו עכ\"ל","ועל מ\"ש בפרקי ר' אליעזר שבשבת היה יוצא האבל ושפמו מכוסה כתב הרמב\"ן בת\"ה אע\"פ שאין אבילות בשבת כיון שיש לו מנעלים ברגליו מותר ועושין כן כדי להכיר בינו ובין המנודה עכ\"ל. ובזמן הזה אינו יוצא בשפמו מכוסה דאנו מתי מעט והכל יודעים שהוא אבל אע\"פ שאין שפמו מכוסה: כתב נ\"י בס\"פ המוכר פירות מכאן נ\"ל פשוט שבאותן המקומות שנהגו לישב בשבת במקומו והם אבילים ואינם רוצים לשנות מקומם בשבת מפני שאומרים שאסור לנהוג אבילות ובחול דוקא משנים מקומם לכבוד שזה מנהג טעות הוא שהרי התירו כאן מעמדות ומושבות בבית הקברות בשבת ופירש רשב\"ם הטעם מאחר שלא היו עושים אבילות אלא מעמדות ומושבות בלבד משמע שבישיבה לכבוד האבל אין בו משום חששא כלל עכ\"ל ואין הנדון דומה לראיה דהתם שאני שהיו עושים מעמדות ומושבות בב\"ה כדי שיאספו רוב עם שלא היה בית הכנסת אחת מכילה אותם אבל כשמשנים מקומם בב\"ה למקום אבילות מיחזי כנוהגים אבילות בשבת ויישר כחם של הנוהגים שלא לשנות מקומם בשבת: וכתב ע\"ש דליל שני מיום ראשון הוא חשוב לענין אנינות ליאסר בקדשים וכתב הריטב\"א נראה דה\"ה לענין הבראה תופס לילו בחול אם חזרו אחר בין השמשות אבל בשבת אין הבראה דמדברים שבפרהסיא הוא עכ\"ל. ואיני יודע טעם לדברים שהרי עשוים בני אדם להביא מאכל למי שלא היה יכול להכין מע\"ש ואע\"פ שאינו אבל הלכך לא מינכר דדבר של אבילות הוא ותו דלא אסרו אלא לאבל עצמו שלא ינהוג דברים שהאבל חייב לנהוג בהם בחול אבל לאחרים שלא יביאו אותו אין שום טעם לאסור וכן פשט המנהג בכל העולם להברות האבל בשבת ולא נשמע בעולם שום פוצה פה ומצפצף: וכתב הכלבו אבל תוך שבעה לא יצא מפתח ביתו ואפי' בשבת אבל מתפללים בביתו ובתפלת חול אין אומרין תחנה ולמנצח ושיר מזמור לאסף וגם בתפלת ערבית של שבת אין אומרים ברכה אחת מעין שבעה ולא במה מדליקין ואין מתפללים בבית לכל מת אם אינו יוצא במטה שהיה כבן שש או שבע וכבר ביארנו שמקומות אחרים מתפללים אם הוא בן שנה וכן אין מתפללים בבית שאין בו אבילים אלא ראשונה הסמוכה לקבורה להניח דעתו של מת על דרך מה שנמצא באגדה ואפי' היה גדול שיצא במטה ואפי' היה שם נשים אבילות ובי\"ה הולך האבל לב\"ה עי\"ה במנחה וכן בכל שאר תפלות היום הגדול והנורא ההוא ואין מונעים שום דבר מן התפלה וכן בר\"ה ע\"כ: כתב סמ\"ק אסור לצאת מפתח ביתו אכן מפני צרכיו ילך שפיר חוץ לעיר וינעול מנעליו וכשיבא לבית אשר ילין בו יחלוץ מנעליו. והתוס' כתבו בסוף מ\"ק [כז.] אע\"פ שאינו יוצא מפתח ביתו בעיר הא אמרינן יצא לדרך נועל נכנס לעיר חולץ אלמא מותר לצאת בו ושמא דוקא בדבר האבד מותר לצאת לדרך :"],["\u0003אבל כל ג' ימים וכו'\u0004 בפרק אלו מגלחין (מועד קטן כ\"א) ונראה דטעם ג' ימים כמ\"ש הר\"ר ירוחם בשם הראב\"ד דאפילו העני אסור במלאכה ג' ימים הראשונים משום דאמרו חז\"ל ג' לבכי ואם יעסוק במלאכה יתעצל בבכי מביאו ב\"י ריש סימן ש\"פ אף כאן אינו יוצא אף לבית האבל ולא לבה\"ק שלא יתעצל בבכי ומהאי טעמא סדרן התלמוד דין מלאכה ודין יציאה לבית האבל ולבה\"ק סמוכין יחד:","ומ\"ש אלא במקום המתנחמין קשה היאך יהא יושב במקומם והלא מתנחמין יושבים שם וצריך לומר דלאו דוקא במקומם ממש אלא סמוך להם וכ\"כ רש\"י סמוך לאבילים וכן כתב רבינו בסמוך ועומד בשורה אצל האבל:","\u0003תניא אבל שבת ראשונה שם [דף כ\"ג]. ומ\"ש פי' שבוע ראשונה וכו'\u0004 כלומר אין פירושו בשבת ממש אלא פי' שבוע בלא שבת ויתבאר בסמוך: ומ\"ש כגון למילה וכיוצא בו כלומר למצוה שאין שם שמחה ואצ\"ל למצוה שיש שם שמחה כגון לשמוע ברכות שבחופה או בבית חתנים וכיוצא בו והא דאמר דאבל חייב בכל המצות היינו במצות שהוא חייב לעשות בעצמו כגון למול את בנו וק\"ש ותפלה וכיוצא בו:","\u0003ומ\"ש אפילו לא שלמו ג' שבועות וכו'\u0004 פי' דאי מעת לעת קאמר הו\"ל למימר שבעה ימים הראשונים אינו יוצא מפתח ביתו שניים וכו' מדקאמר שבת ראשונה משמע אפילו עומד באמצע השבוע מיד לאחר השבת כלתה לה שבוע הראשונה וכדלעיל בסי' ר\"כ גבי נדרים עיין שם:","ולענין יציאת האבל לב\"ה כתב הרי\"ץ גיאת שיוצא אפילו בחול טעמו משום דאבל חייב בכל המצות ומצוה היא להתפלל בב\"ה דכל מי שיש לו ב\"ה בעירו ואינו מתפלל שם נקרא שכן רע. והראב\"ד ס\"ל כיון דיכול להתפלל בעשרה בביתו אינו חייב להתפלל בב\"ה ולפיכך אפי' בשבת אינו יוצא ומפרש הא דקתני שבת ראשונה אינו יוצא היינו שבת ממש דאינו יוצא לב\"ה אף בשבת מדקתני שנייה יוצא ואינו יושב במקומו דהיינו ישיבה בב\"ה דאי לשוק מאי יושב במקומו איכא אלא לב\"ה קאמר:","\u0003ומ\"ש ואינו כדברי שניהם וכו'\u0004 וה\"ט דכיון שאין אבילות בשבת יוצא בשבת ופירוש שבת ראשונה אינו יוצא היינו שבוע הראשונה בחול אינו יוצא אבל בשבת יוצא:","\u0003ויושבין עמו לארץ כו'\u0004 כתב במרדכי דמ\"ק הא דקאמר דיושבין עמו לארץ משו' שרוב עם לא שני להו בלאו הכי ומשנה מקומו כדי שירגישו הכל וכו' ומביאו ב\"י: כתב מהרש\"ל על שינוי מקום אמרינן במ\"ק בשבת רביעית הרי הוא ככל אדם ולא חילקו בין אביו ואמו לשאר קרובים אלא מנהג בעלמא הוא כפי חפצו של אדם לכבוד אבותיו וכן כתב מהר\"ר מנחם מעיל צדק עכ\"ל ונהגו שמשנין את מקומם כל היום עד אחר ברכו ואע\"פ שמקצת היום ככולו אפ\"ה נוהגין אבילות כל היום מפני הכבוד אף באבילות דשלשי' על שאר קרובים ואין לשנות מן המנהג וע\"ל סוף סימן שצ\"ה: כתב בהגהת אשיר\"י בשם הא\"ז מוהל שחל עליו יום המילה בימי אבלו בשלשה ימים הראשונים אל יצא מפתח ביתו ושאר כל הימים יתפלל בביתו ואחר כך ילך לבית הכנסת וימול ואבל מותר להיות בעל ברית (פי' סנדק) ויתפלל בביתו וכשמביא הנער לב\"ה למולו ילך ויהיה בעל ברית ולאחר מילה לא יכנס עכ\"ל ואי ליכא מוהל אחרינא ילך אפי' ביום ראשון רוקח וכ\"כ ב\"י ועיין בהגהת ש\"ע:"]],["\u0010c0\u0011\u0010y0\u0011אין מתקשין על המת יותר מדאי וכל המתקשה עליו יותר מדאי על מת אחר הוא בוכה אלא ג' ימים לבכי ז' למספד ול' לתספורת וגיהוץ \u0010c1\u0011וכתב הרשב\"א בד\"א בשאר העם אבל ת\"ח הכל לפי חכמתן ואין בוכין עליהן יותר מל' יום \u0010y1\u0011ואין מספידין עליהן יותר מי\"ב חדש \u0010y2\u0011וכן חכם שבא שמועתו לאחר י\"ב חדש אין מספידין אותו. \u0010y3\u0011תניא באבל רבתי יוצאין לבית הקברות ופוקדין על המתים ג' ימים ואין חוששין משום דרכי אמורי ומעשה שפקדו אחד וחיה כ' שנים והוליד ה' בנים ואח\"כ מת \u0010c2\u0011\u0010y4\u0011א\"ר לוי כל ג' ימים יראה האבל עצמו כאילו חרב מונחת לו בין כתיפיו מג' ועד ז' כאילו זקופה כנגדו בקרן זוית מז' ועד ל' כאילו עוברת לפניו בשוק \u0010y5\u0011ירושלמי כל אותה השנה הדין מתוח כנגד אותה משפחה א\"ר יוחנן כל ז' החרב שלופה עד ל' היא רופפת לאחר י\"ב היא חוזרת לתערה למה הדבר דומה לכיפה של אבנים כיון שנתרועעה אבן אחת מהן נתרועעה כולם א\"ר אלכסנדרי נולד בן זכר באותה משפחה נתרפאה כל המשפחה \u0010y6\u0011כתב הרמב\"ם ז\"ל כל מי שאינו מתאבל כמו שצוו החכמים הרי זה אכזרי אלא יפחד וידאג ויפשפש במעשיו ויחזור בתשובה \u0010y7\u0011ואחד מבני החבורה שמת תדאג כל החבורה כולה:",["אין מתקשין על המת יותר מדאי וכל המתקשה עליו יותר מדאי על מת אחר הוא בוכה אלא ג' ימים לבכי וכו' בסוף מועד קטן [כז:] ומה שכתב בשם: \u0005ב\"ה נראה שיש להגיה ולכתוב במקום הרשב\"א הרמב\"ם שזה הוא לשונו בפ' י\"ג:\u0006 הרשב\"א כן נראה ממה שיבא בסמוך: ומה שכתב ואין בוכין עליהם יותר משלשים יום בפרק הנושא אשה [דף קג:] שצוה רבי בשעת פטירתו הושיבו ישיבה לאחר שלשים יום דלא עדיפנא ממשה רבינו ע\"ה דכתיב ויבכו את משה ל' יום:","ומ\"ש ואין מספידין עליהם יותר מי\"ב חדש שם בפטירתו של רבי ספדו ל' יום בליליא ויממא מכאן ואילך ספדי ביממא וגרסי בליליא או ספדי בליליא וגרסי ביממא עד דספדי תריסר ירחי שתא.","ומ\"ש וכן חכם שבא שמועתו לאחר י\"ב חדש אין מספידין אותו בפרק הערל (יבמות עט.) גבי שאול שלא נספד כהלכה אמר דוד שאול נפקי ליה תריסר ירחי שתא ולא דרכיה למספדיה וכ\"כ הרמב\"ן בת\"ה בשם גאון שאין מנהג ואין דרך ארץ להזכיר המת לאחר י\"ב חדש לפיכך מקום מרוחק שאין מגעת שמועת ת\"ח אלא לאחר י\"ב חדש פטורים מלהספיד אפי' יום שמועה:","\u0003תניא באבל רבתי יוצאין לבית הקברות ופוקדים על המתים ג' ימים וכו'\u0004 בפ\"ח:","\u0003א\"ר לוי כל ג' ימים יראה האבל עצמו כאילו חרב מונחת לו בין כתפיו וכו'\u0004 בסוף מ\"ק (שם):","\u0003ירושלמי כל אותה השנה הדין מתוח כנגד אותה המשפחה א\"ר יוחנן כל ז' החרב שלופה וכו'\u0004 עד נתרפאת כל המשפחה בסוף מ\"ק:","\u0003כתב הרמב\"ם ז\"ל כל מי שאינו מתאבל כמו שצוו החכמים הרי זה אכזרי וכו'\u0004 פי\"ג מהל' אבל:","ומ\"ש ואחד מבני חבורה שמת תדאג כל החבורה כולה הוא בפרק ר\"א דאורג (ק\"ו:):"],["\u0003אין מתקשין וכו'\u0004 בסוף מ\"ק [דף כ\"ז] מימרא דרב יהודה אמר רב ומייתי עלה עובדא דההיא איתתא דהוי לה ז' בני ומיתו כולהו וגם היא מתה על דהוות קא בכיא ביתירתא ומיהו נראה דמי שמת בלא בנים יכול לבכות עליו טפי מג' והכי משמע בסוגיא דקאמר התם אל תבכו למת יותר מדאי ואל תנודו לו יותר מכשיעור הא כיצד ג' לבכי וז' להספד שלשים לגיהוץ ולתספורת מכאן ואילך אמר הקב\"ה אין אתם רחמנים בו יותר ממני בכו בכה להולך להולך בלא בנים דסיפיה דקרא ארישיה קאי דקאמר אל תבכו יותר מדאי אבל בכו בכה יותר מדאי להולך בלא בנים:","\u0003וכתב הרשב\"א בד\"א וכו'\u0004 וכן חכם וכו' פי' ל\"מ בחכם שמת בעירו שהיו בוכין ומספידין עליו ז' ושלשים אין בוכין ואין מספידין עליו יותר אלא אפי' חכם שבא שמועתו לאחר י\"ב חדש דאכתי לא בכו ולא הספידו עליו כל עיקר אפ\"ה אין מספידין עליו לאחר יב\"ח וכדאמרינן בפרק הערל גבי שאול:","\u0003א\"ר לוי וכו'\u0004 מז' ועד ל' כאילו עוברת לפניו בשוק כך הוא גירסת רבינו אבל בספרים שבידינו הגירסא הוא מכאן ואילך כאילו עוברת כנגדו בשוק וכך הוא באלפסי ופי' התוס' מכאן ואילך כאילו עוברת כנגדו בשוק עד יב\"ח וכדאיתא בירושלמי דבסמוך דלאחר יב\"ח חוזרת היא לתערה אבל לגירסת רבי' צריך לפרש דהך דרבי לוי מיירי בשאר קרובים ולפיכך אחר ל' אין לחוש דשוב אינה עוברת לפניו אפי' בשוה והך דירוש' מיירי באביו ואמו דכל אותן י\"ב חדש הדין מתוח וכו':"]],["\u0010c0\u0011\u0010y0\u0011אבל כיון שעומדין המנחמין מאצלו ביום ז' מותר ברחיצה \u0010y1\u0011דמקצת היום ככולו ל\"ש מקצת יום ז' ל\"ש מקצת יום ל' \u0010y2\u0011י\"א דוקא מקצת יום שצריך לנהוג אבילות קצת היום ומה שנהג בלילה לא חשבינן ככל היום וי\"א דה\"ה נמי מקצת הלילה חשיב ככל היום והר\"מ מרוטנבור\"ק כתב דגבי ז' כיון שצריך ספירות ז' לא חשבינן מקצת לילה ככל היום אבל בשמועה רחוקה שאינו נוהגת אלא יום אחד אם שמע בלילה חשיב ככל היום ור\"ת התיר בשעת הדחק לרחוץ בליל ז':",["אבל כיון שעומדין המנחמין מאצלו ביום ז' מותר ברחיצה מימרא בפ' אלו מגלחין (מועד קטן י\"ט:):","ומ\"ש דמקצת היום ככולו ל\"ש מקצת יום ז' ל\"ש מקצת יום ל' שם איפסיקא הלכת' כאבא שאול דאמר הכי וכתב רבי' ירוחם יום ז' מקצתו ככולו לא מיד בהנץ החמה אלא אחר שיעמדו המנחמין מאצלו דהיינו אחר שהתפללו עם האבל אבל ביום ל' לענין גיהוץ ותספורת די בהנץ החמה וכ\"כ המפרשים עכ\"ל:","\u0003ומ\"ש י\"א דוקא מקצת היום וכו'\u0004 וי\"א דה\"ה נמי מקצת הלילה חשוב ככל היום הרא\"ש כתב שם בפסקיו וז\"ל כתוב שם בתוס' ריב\"ם מספקא לר' הא דאמר מקצת היום ככולו אי אמרינן נמי מקצת הלילה ככולו או דוקא יום בעינן ונ\"מ אם באת לו שמועה רחוקה בלילה וישב מקצת הלילה אם מותר לרחוץ בלילה ולבסוף כתב משום דבלילה לא מוכחא מילתא שהרי דרך בני אדם לחלוץ מנעליהם בלילה ורשב\"ם כתב נוהגים העם לישב מקצת יום ז' ומה שיושבין מקצת לילה באבילות אינן מחשיבין אותו ולא ידענו טעמא מאי והר\"מ כתב אם שמע שמועה רחוקה בלילה דמקצת הלילה ככולו ואע\"ג דגבי ז' לא אמרינן מקצת הלילה ככל היום כדאמרינן לעיל אבל כיון שעמדו מנחמים מאצלו מותר ברחיצה ומשמע דוקא ביום ז' וכ\"נ דכשמנה ל' צריך למנות עד מקצת יום ל' מדאמרינן בפ\"ב דמגילה (כ.) וכן שומרת יום כנגד יום וכו' אלמא כל דבר דלא סליק ביומיה ובעי ספירה לא אמרי' מקצת הלילה ככל היום הילכך אבל לא יצא מפתח ביתו עד הנץ החמה וכן ביום ל' לא יגלח עד הנץ החמה ומיהו לענין שמועה רחוקה דלא בעי ספירה אלא סגי בשעה אחת סלקא אפי' בלילה עכ\"ל והמרדכי בפ\"ב דמגילה ובפרק אלו מגלחין לא הביא אלא דברי הר\"מ והרמב\"ן בת\"ה האריך לסתור דברי התוס' והעלה דלעולם מקצת לילה חשוב ככל היום: ולענין הלכה נקטינן כדברי הר\"מ דבתראה הוא ומסתבר טעמיה: כתב בתה\"ד סימן רצ\"ב מי שמת אביו ואמו בר\"ח ניסן כשיגיע אחריו כ\"ט באדר ונהג דין אבילות די\"ב חדש במקצת אותו היום כלו לו אבילות די\"ב או לא תשובה יראה דלא כלו עדיין וצריך לנהוג אבילות דיב\"ח עד שיכנס ר\"ח ניסן ולא דמי ליום ז' ול' דהתם הספירה הוא לפי הימים אבל גבי אבילות דיב\"ח דלא הזכירו בשום מקום אלא יב\"ח ולא שנ\"ד ימים דהספירה הוא לפי החדשים אי הוי אמרינן מקצתו ככולהו הוה שרי בתחילת חדש י\"ב והא ודאי ליתא ולכך לא כלו עד שיכנס ר\"ח ניסן : ומ\"ש רבי' שר\"ת התיר בשעת הדחק לרחוץ בליל ז' כ\"כ הרמב\"ן בת\"ה בשמו:"],["\u0003אבל כיון שעמדו וכו'\u0004 הכי איפסיקא הילכתא בפרק אלו מגלחין (מועד קטן דף י\"ט) דמקצת היום ככולו בין בזו ובין בזו י\"א דוקא מקצת יום וכו' עד ככל היום כל זה כתב הרא\"ש שם: מצאתי כתוב בהגה\"ה כתב רשב\"ם נוהגים העם לישב במקצת יום ז' ביום ממש ומה שיושב בלילה לא חשיב מקצתו ככולו וגם בשבת כשהוא שביעי לאבילות נוהג דברים שבצינעא כל הלילה ור\"ת התיר בשעת הדחק אחר מקצת ליל ז' בדברים האסורים בו אבל אין נוהגין כן עכ\"ה פסק ב\"י כמ\"ש בת\"ה סימן רצ\"ב דמי שמת אביו בר\"ח ניסן לא סגי בנוהג אבילות במקצת יום כ\"ט אדר שאחריו אלא צריך לנהוג אבילות עד שיכנס ר\"ח ניסן וכתב עוד דנהגו להוסיף עוד כל אותו היום שמת בו אביו לנהוג בו דין יב\"ח וכתב בזה ב' טעמים אחד משום דאומר בו קדיש וברכו ומתענה בו לכך נוהגים אבילות באותו יום לפ\"ז היה נראה דאם חל בשבת כיון דאינו מתענה אע\"פ דאומר קדיש אין להחמיר וכ\"ש באשה דאינה אומרת קדיש דאין לה לנהוג אבילות כשחל בשבת לפי טעם זה אבל כתב עוד טעם שני דהיכא דמתענה ואומר קדיש וברכו ביום המיתה והוא מת היום ונקבר למחר דאבילות לעולם מיום קבורה מנינן לפי טעם זה ודאי אפי' חל בשבת חייב לנהוג אבילות של דין יב\"ח כל אותו היום כיון דהוא יום דמישלם בו יב\"ח ובין איש בין אשה צריך לנהוג אבילות כל אותו היום והכי נקטינן לחומרא מפני כבוד אביו ואמו. מיהו נראה דכשהשנה מעוברת דמותר ליכנס לבית המשתה לאחר י\"ב חדש כדלעיל בריש סי' שצ\"א אז אין נוהג דין י\"ב חדש ביום שמת בו אביו אע\"פ שאומר קדיש וברכו ומתענה בו ביום דמאחר דכבר נכנס למשתה והפסיק מאבילותו שוב אינו חוזר לאבילותו וכענין זה כתב הרמב\"ן בדין מקצת היום ככולו אי סגי במקצת לילה עיין בספר ת\"ה בדף ע' ע\"ב:"]],["\u0010c0\u0011\u0010y0\u0011כתב הראב\"ד אבל שלא נהג אבילות תוך ז' בין בשוגג בין במזיד משלים אותו כל ל' חוץ מהקריעה שאם לא קרע בשעת חימום אינו קורע אלא תוך ז' \u0010c1\u0011\u0010y1\u0011וכתב א\"א הרא\"ש ז\" דוקא שלא נהג אבילות כלל כל ז' אבל אם זלזל במקצת הימים ולא נהג בהן אבילות כגון מי שאמרו לו שמת לו מת ביום הראשון והיה בעיר אחרת ולא נהג אבילות ביום ראשון וביום השני בא לעירו ונהג אבילות אין צריך להשלים ומונה ז' מיום ראשון \u0010c2\u0011\u0010y2\u0011מי שמת אביו או אמו והיה קטן באותה שעה והגדיל קודם שעברו עליו ל' יום כתב הר\"מ מרוטנבורק שצריך להתאבל משיגדיל ואינו מונה מיום קבורה אלא ז' ושלשים מונה הכל משיגדיל ואם עברו עליו ל' יום קודם שהגדיל בטל ממנו גזירת ז' ושלשים ומשלים י\"ב חדש מיום קבורה וא\"א הרא\"ש ז\"ל כתב כיון שהיה קטן בשעת קבורה אפילו הגדיל תוך ל' או אפילו תוך ז' בטל ממנו כל דין אבילות:",["\u0003כתב הראב\"ד אבל שלא נהג אבילות תוך ז' וכו'\u0004 משלים אותו כל ל' חוץ מן הקריעה וכו' כן כתב הרמב\"ן בת\"ה והרא\"ש פרק אלו מגלחין בשמו ולמד כן מדתניא בפרק אלו מגלחין (מועד קטן דף כ.) קיים כפיית המטה שלשה ימים קודם הרגל א\"צ לכפות אחר הרגל דברי ר' אליעזר וחכ\"א אפי' יום אחד אפי' שעה אחת ומדקתני כי האי לישנא ולא קתני לישנא דמתניתין הקובר את מתו ג' ימים קודם הרגל וקתני קיים כפיית המטה ש\"מ בעינן קיום אבילות קודם הרגל שאם לא קיים אבילות קודם הרגל שוגג או מזיד אין רגל מפסיקו שלא יהא חוטא נשכר ומינה ילפינן לכל אבל שלא נהג אבילותו תוך ז' שישלים אבילתו חוץ מן הקריעה שאם עבר ולא קרע בשעת חיובו שאין קורע אחר ז' כענין שאמרו מי שאין לו חלוק תוך ז' קורע לאחר ז' אינו קורע ודוקא בשאר מת מצוה כדלקמן עכ\"ל כלומר דעל אביו ואמו אם לא קרע תוך ז' קורע אחר ז' כדין מי שמת אביו ואמו ולא היה לו חלוק תוך ז' ונזדמן לו אחר ז' שקורע והולך כמו שנתבאר בסימן ש\"מ:","\u0003ומ\"ש בשם הרא\"ש דוקא שלא נהג אבילות כלל כל ז' וכו'\u0004 כן כתב בתשובות כלל כ\"ז דע\"כ לא קאמר הראב\"ד אלא בשלא נהג אבילות כל ז' דומיא דההיא דקיום כפיית המטה קודם הרגל אבל זלזל במקצת הימים ולא נהג בהם אבילות א\"צ להשלימם:","\u0003מי שמת אביו או אמו והיה קטן באותה שעה והגדיל וכו'\u0004 עד סוף הסימן הכל כתב באורך בפסקי הרא\"ש בסוף מ\"ק והגה\"מ כתב דברי הר\"מ ורבינו ירוחם אחר שהביא דברי הר\"מ ודברי הרא\"ש כ' ומ\"מ דברי הר\"מ רבו דברי קבלה הן כ\"ש להחמיר ואינו נ\"ל דהא קי\"ל הלכה כבתראי וקי\"ל הלכה כדברי המיקל באבל הילכך נקטינן כדברי הרא\"ש:"],["\u0003כתב הראב\"ד אבל שלא נהג אבילותו וכו'\u0004 כן כתב הרמב\"ן בשמו בסה\"ת [דף ע' ע\"ד] והביא ראיה לדבריו וכ\"כ הרא\"ש פרק אלו מגלחין: ומ\"ש חוץ מן הקריעה וכו' לע\"ד איכא להסתפק היכא שהיה אנוס כגון שהיה חולה ומסוכן שאי אפשר לקרוע או כגון שאין דעתו צלולה ומיושבת עליו וחזר לבוריו ולדעתו אחר ז' שמא חשוב עכשיו כשעת חמום דלא דמי לשוגג או מזיד דעבר שעת חמום כיון שהיה בריא בשעה ששמע שמת לו מת ונתחייב באותה שעה אבל זה שהיה חולה ומסוכן לא נתחמם אלא בשעה שחזר לבוריו ודעתו צלולה ומיושבת ובאותה שעה חלה עליו חובת קריעה וכך דעתי נוטה:","\u0003ומ\"ש בשם הרא\"ש דוקא שלא נהג וכו'\u0004 בתשובה כלל כ\"ז דין ד':","\u0003מי שמת אביו או אמו והיה קטן באותה שעה והגדיל וכו'\u0004 כתב ב\"י ורבי' ירוחם אחר שהביא דברי הר\"מ ודברי הרא\"ש כתב ומ\"מ דברי הר\"מ רבו דברי קבלה הן כ\"ש להחמיר ואינו נ\"ל דהא קי\"ל הלכה כבתראי וקי\"ל הלכה כדברי המיקל באבל הילכך נקטינן כדברי הרא\"ש עכ\"ל. וכ\"פ בש\"ע ולפענ\"ד דיש להשיב על דברי ב\"י שאע\"פ שהלכה כדברי המיקל באבל היינו דוקא בשכנגדו חלוק עליו אבל לא כנגד רבו דפשיטא דשומעין להרב אפי' בא להחמיר והתלמיד מיקל דשומעין לרבו דלא כמה שהבין ב\"י מדברי הר\"י במ\"ש כל שכן להחמיר דרצ\"ל דיש לשמוע למהר\"ם דמחמיר אע\"פ שלא היה רבו של הרא\"ש וע\"כ השיג עליו ממאי דקי\"ל הלכה כדברי המיקל באבל דליתא אלא ה\"ק וכל שכן ששומעין לרבו היכא דרבו מחמיר וכ\"כ הרא\"ש גופיה בפרק בתרא דתענית בדין דבר שבצינעא כשחל ט\"ב בשבת דר\"י א\"ז מווינא מחמיר ומהר\"ם תלמידו מיקל וסוף דבריו מיהו נכון להחמיר כדברי מורי אפי' הוא מיקל ואני מחמיר היה לנו לעשות כדבריו וכ\"ש שהוא מחמיר ואני מיקל אלמא דאפי' באבילות ישנה ומדרבנן אין להקל מטעם הלכה כדברי המיקל באבל אלא אין הלכה כתלמיד במקום רבו כלל אפי' נחלקו בסברא כ\"ש כשהרב מודה כמו שהיה מקובל מרבותיו והתלמיד נחלק עליו מסברתו וראייתו דאין שומעין לתלמיד ואע\"פ שמהר\"מ כתב וז\"ל נ\"ל שחייב להתאבל משהגדיל וכו' על הראיות שהביא לדין זה אמר נ\"ל שבכך וכך יש להביא ראיה אבל גוף הדין היה מקובל מרבותיו כך נראה לפי דעת הר\"ר ירוחם שאמר שמהר\"ם דברי קבלה הן ועוד נראה דמה שמביא הרא\"ש ראיה מפרק מי שהיה טמא בגר שנתגייר בין ב' פסחים וכן קטן שהגדיל בין ב' פסחים דפליגי ביה רבי ור' נתן דמשמע דכל היכא דאינו אלא תשלומין כי הכא גבי אבילות דהוי תשלומין לאבילות שהיה לו לעשות א\"כ הכא כיון דידע ולא נתחייב בה לא שייך ביה תשלומין וה\"נ גבי מצות ראייה פ\"ק דחגיגה [דף ט'] בחיגר ביום ראשון ונתפשט ביום שני דלא שייך ביה תשלומין כיון דלא הוה בר חיובא ביום ראשון ואין לדחות ולומר דלא דמי להכא דדוקא במצוה דאורייתא דקרבן פסח ומצות ראייה אמרינן כיון דנדחה נדחה לגמרי אבל לא במצוה דרבנן דשפיר איכא למימר דרבנן תיקנוהו שלא יהא נדחה וה\"א בהגה\"מ ספ\"ד דהל' אבל וסמ\"ק ס\"ס נ\"ז בדין אונן במ\"ש די\"א כיון דנדחה שלא הבדיל במ\"ש שוב לא יבדיל ומביאין ראיה מהך דחיגר ודחה דבריהם משום דיש לחלק בין דאורייתא לדרבנן ותו איכא לתמוה בדברי ב\"י והוא שמחלוקת זו בהבדלה כתובה באשיר\"י בברכות ר\"פ מי שמתו דמביא דברי רבי' יהודה שפוסק שאין להבדיל ביום א' דכיון שנדחה נדחה וראיה מהך דחגר ומהר\"ם נחלק עליו והרא\"ש קיים ד\"ר יהודה וראייתו וכבר מבואר דחייב הראייה מהך דהחגר מטעם דאיכא לחלק בין דאורייתא לדרבנן וכדפרישית והרי לך דכמחלוקתן בהבדלה כך נחלקו בקטן שהגדיל דטעם אחד וראיה אחת לשניהם דלמהר\"ם צריך להבדיל ביום ראשון ואינו נדחה וכן בקטן שהגדיל חייב באבילות דאין דחוי למצות בדרבנן ולהרא\"ש ורבי' יהודה יש דיחוי אפי' בדרבנן וא\"כ קשה על מ\"ש בש\"ע דבסימן שמ\"א פסק כמהר\"ם דחייב להבדיל ביום א' וכאן פסק כהרא\"ש בקטן שהגדיל דפטור והפסקים סותרין זו את זו ואין להם יישוב ולפענ\"ד דהעיקר כמהר\"ם דאינו נדחה לא בהבדלה ולא בקטן שהגדיל כיון דמצוה דרבנן נינהו הם תקנו שלא יהא נדחה ומ\"ש עוד הרא\"ש לדחות ראיית מהר\"ם מכיסוי הדם משום דאיכא לחלק בין מצוה הנדחית לגוף הדחוי וכו' גם מהר\"ם סובר כך אלא דמביא ראיה מאחר דאשכחן נמי לפעמים דאין דחוי אצל מצות אפי' בדאורייתא כגון בכסוי הדם ובזר ששימש אע\"פ שיש לחלק כמו שמחלק הרא\"ש בין מצוה הנדחית לגוף הדחוי מ\"מ איכא ראיה דבדרבנן מיהא לא אמרינן כלל כיון דנדחה נדחה ואם לא היינו מוצאים בשום פעם דאמרינן אין דחוי אצל מצוה בדאורייתא אלא בכל ענין יש דחוי לא היה ראוי לחלק ולומר דבדרבנן אין דחוי השתא דבדאורייתא נמי אשכחן זימנין דאין דחוי א\"כ בדרבנן אמרינן שפיר בכל דוכתא דאין דחוי דאין סברא לומר שום דחוי בדרבנן וכדפרישית דכיון שהם תקנוהו תקנוהו בכל ענין ולא חילקו ובתשובה הארכתי יותר בס\"ד:"]],["\u0010c0\u0011\u0010y0\u0011כתב הרמב\"ן שמתאבלין על פי עד אחד ועד מפי עד ונכרי מסיח לפי תומו דמילתא דעבידא לגלויי לא משקר \u0010y1\u0011והר\"מ מרוטנבורק מפקפק בדבר והיה תמה האיך נהגו העולם להתאבל על פי עד אחד:",["\u0003כתב הרמב\"ן שמתאבלין ע\"פ עד אחד ועד מפי עד ונכרי מסיח ל\"ת וכו'\u0004 בת\"ה והביא ראיה לדבר וכתב בסוף דבריו זה הכלל עדות שמשיאין האשה על פיו קרובים מתאבלין:","\u0003ומ\"ש והר\"מ היה מפקפק בדבר וכו'\u0004 וטענת הרמב\"ן וטענת הר\"מ הכל כתוב באורך בפסקי הרא\"ש ובמרדכי והגה\"מ פרק ו' משמע שבסוף דבריו הסכים הר\"מ להתאבל על פי עד אחד ואפי' אשה או נכרי מל\"ת אבל אם הנכרי מתכוין להעיד לא ודלא כקצת רבוותא שהיו אומרים דאפילו מתכוין הנכרי להעיד מתאבלין על פיו: כתב המרדכי בסוף מ\"ק והגה\"מ פרק ו' שני עדים אומרים מת ושנים אומרים לא מת מספיקא אינו מתאבל כדאמרינן בפרק יש בכור (בכורות מט.) גבי מת ביום ל' דר\"ע משויה ליה ספיקא לענין פדיון ואפ\"ה מודה לענין אבילות דכיום שלפניו דמי:"],["\u0003כתב הרמב\"ן שמתאבלין על פי עד אחד וכו'\u0004 וכן פסק בש\"ע וז\"ל הרמב\"ן בספר ת\"ה [דף ע\"ט ע\"ג] דמילתא דעבידא לאיגלויי הוא ולא משקרי בה אינשי כדאמרינן גבי קידוש החדש דעד אחד מהימן מ\"ט כל מילתא דעבידא לאיגלויי לא משקרי בה אינשי כדאיתא בפרק אם אינן מכירין וה\"נ אמרינן בפרק האשה רבה גבי עד אחד ביבמה לשוק וראיה לדבר ממעשה דר' חייא בפרק אלו מגלחין (מועד קטן דף כ) דהימניה לרב דמתו אחיו ואחותו ונהג עליהם יום אחד שמועה רחוקה ואע\"ג דהוא יחיד וקרוב ולא בדרך עדות אלא ברמיזה בעלמא אלמא בכה\"ג לא בעינן עדות ברורה וזה הכלל כל עדות שמשיאין האשה על פיו קרובים מתאבלין עכ\"ל ולפע\"ד דמ\"ש וזה הכלל וכו' כך כוונתו דאי איתא דבמקום שמשיאין את האשה ע\"פ עדות זו דאין הקרובים מתאבלין א\"כ בחזקת חי מחזקינן ליה ודאי דלא היו משיאין האשה לאיש אחר דהו\"ל תרתי דסתרי אהדדי אלא בע\"כ צ\"ל דכשמשיאין האשה ע\"פ עדות זו כ\"ש דמתאבלין עליו א\"כ בעלמא נמי היכא דאין משיאין האשה על פיו כגון שאין לו אשה נמי הקרובים מתאבלין דפשיטא דאין דין אחד חלוק פעם מתאבלין דנאמן הוא בעדותו ופעם אין מתאבלין דאין נאמן בעדותו זה דבר דאין לו שחר אלא בע\"כ לעולם נאמן וה\"נ. ולפ\"ז ג\"כ כשאחד כותב לחבירו שמת פלוני נמי מתאבלין כיון דמשיאין האשה ע\"פ כתב של ישראל שמצאו שכתוב בו פלוני מת כמבואר בא\"ה סי' י\"ז מיהו בזה צ\"ע במעשה שבא לפנינו שכתבו לאחד ממרחקים שפלוני מת ואיכא ספק אם הוא תוך ל' או לאחר ל' אם חייב להתאבל מספק ונראה דחייב להתאבל דאע\"ג דבשאר ספיקות אינו חייב להתאבל דהא דתני הספיקות מתאבלין עליהן היינו דוקא ספק בן ז' לאחרון ספק בן ט' לראשון מטעם דגנאי היה הדבר אם לא היו מתאבלין עליו לא זה ולא זה כדכתב המרדכי בסוף מ\"ק וב\"י מביאו לעיל בס\"ס שע\"ד אבל שאר ספיקות אין מתאבלין כגון ב' אומרים מת וב' אומרים לא מת כדכתב המרדכי ומביאו ב\"י אפ\"ה נראה דכאן יש לחלק דהתם מחזקינן ליה בחזקת חי ואמרינן לא מת אבל הכא אדרבה מטעם חזקת חי צריך הוא שיתאבל דאמרינן מקרוב מת ועדיין הוא תוך ל' וכדתנן בפרק כל הגט המביא גט והניחו זקן או חולה נותן לה בחזקת שהוא קיים והארכתי בתשובה בס\"ד וכן הראו לי בתשובת בן ל\"ב שהורה כך מטעם זה. אחר כמה שנים אירע מעשה אחר הגיע כתב מהרב שבויניציא\"ה להחכם הרופא מהר\"ר שמואל כ\"צ מקראקא שמת אחיו בסתם והיה ספק שמא הוא תוך ל' כי מיום הכתיבה לא היה כי אם כ\"ו יום עד הגיע הכתב לקראקא והורתי בזו דא\"צ לנהוג אבילות דאי איתא דאפשר היה שיגיע הכתב לידו בתוך ל' לא היה כותב הרב בסתם מת אחיו אלא היה מבאר בכתבו באיזה יום בחדש מת כדי שיתאבל אם יגיע הכתב לידו תוך ל' אלא בע\"כ ידע הרב מוויניצא\"ה דאי אפשר שיגיע הכתב לידו תוך ל' וראייה מהא דתניא חבר שמת והניח מגורה מליאה פירות אפי' הן בני יומן הרי הן בחזקת מתוקנים משום דחזקה הוא על חבר שאינו מוציא דבר שאינו מתוקן מתחת ידו וכדאיתא בפרק כל היד (נדה דף טו) אבל בסתם אדם שכותב לחבירו בסתם מת אחיך צריך להתאבל עליו דמוקמינן ליה בחזקת חי ושמא תוך ל' הוא והכותב לא דק:"]],["\u0010c0\u0011\u0010y0\u0011בענין האבילות איכא פלוגתא דרבוותא אם יש ממנו מן התורה הגאונים כתבו שאבילות יום ראשון אם הוא יום מיתה אז הוא דאורייתא ושאר הימים דרבנן \u0010y1\u0011והראב\"ד הוסיף לומר דגזירות שלשים לגיהוץ ולתספורת דאורייתא \u0010y2\u0011ור\"ת ור\"י פירשו שאין שום אבילות דאורייתא אלא אנינות לחוד הוא דהוי דאורייתא ביום ראשון ואנינות לחוד ואבילות לחוד האסור בזה מותר בזה ואונן אינו אסור ביום ראשון מן התורה אלא באכילת קדשים ומעשר שני ועוד החמירו בו חכמים לאוסרו בדברים המפורשים בפרק מי שמתו אבל אבילות לא מצאנו בשום מקום שיהא מן התורה \u0010y3\u0011והרמב\"ן האריך בו מאד וסיום דבריו נמצינו למדים שאבילות יום ראשון שהוא יום מיתה וקבורה מן התורה ולא כל הנוהגים באבל אלא בז' מתים המפורשים בתורה שהן אביו ואמו בנו ובתו ואחיו ואחותו הבתולה ואשתו נשואה אבל ג' מתים שהוסיפו עליהן לאבילות שהן אחיו מאמו ואחותו מאמו נשואה וארוסה מאב או מאם ואחותו אנוסה או מפותה אבלותן מד\"ס \u0010c1\u0011\u0010y4\u0011וכ\"כ הרמב\"ם אלא שכתב אשתו בכלל אותם שהם מד\"ס והוא ודאי מן התורה אם היא גדולה אבל אשתו קטנה מד\"ס \u0010y5\u0011וא\"א הרא\"ש ז\"ל הסכים לדברי ר\"ת ולר\"י:",["בענין האבילות איכא פלוגתא דרבוותא אם יש ממנו מן התורה הגאונים כתבו שאבילות יום ראשון אם הוא יום מיתה אז הוא דאורייתא כלומר אם הוא יום מיתה וקבורה הוא דאורייתא לדעת הגאונים וכן דעת הרי\"ף בכ\"ב דברכות ובפרק אלו מגלחין וכ\"פ הרמב\"ם בפ\"א וכ\"כ הרשב\"א דלא אמרו הגאונים אלא ביום מיתה והוא עצמו יום קבורה הא זה בלא זה לא:","ומ\"ש שהראב\"ד הוסיף לומר דגזירת ל' לגיהוץ ולתספורת הוי דאורייתא כ\"כ הרמב\"ן בת\"ה בשמו והוא ז\"ל חלק עליו:","\u0003ומ\"ש שר\"ת ור\"י פירשו שאין שום אבילות דאורייתא וכו'\u0004 כ\"כ הרמב\"ן כת\"ה וה\"ר יונה בפ\"ב דברכות בשם חכמי הצרפתים ז\"ל:","\u0003ומ\"ש והרמב\"ן האריך מאד וכו'\u0004 עד אבל אשתו קטנה מד\"ס הוא בת\"ה:","ומ\"ש בשם הרמב\"ם הוא בפרק ב' ואיפשר שאע\"פ שהוא מן התורה קרי לה ד\"ס לפי שאינה מפורשת בתורה לענין טומאה ולא אתיא אלא ממדרש חכמים בשארו כתב בין לענין טומאה בין לענין אבילות שהוא מד\"ס שכתב בפרק הנזכר לענין טומאה לאשתו עשאוה כמת מצוה כיון שאין לה יורש אלא היא לא תמצא מי שיתעסק בה וכתב עליו הרמב\"ן ההיא באשתו קטנה תניא בהדיא כדאיתא פרק האשה רבה [דף צט:] וי\"ל שהרמב\"ם נתכוין לומר דלאשתו בין קטנה בין גדולה אינו מיטמא אלא מד\"ס ולגדולה הוי מד\"ת אלא דאתיא ממדרש חכמים שזה נקרא ד\"ס לדעתו ז\"ל ולקטנה הוי מד\"ס ממש כלומר דאין לה עיקר בתורה מטעם אשה אלא שחכמים עשאהו כמת מצוה כיון שאין לה יורש אלא הוא וז\"ל הרמב\"ם בפרק הנזכר ומדבריהם שיתאבל האיש על אשתו הנשואה וכן האשה על בעלה ומתאבל על אחיו ועל אחותו שהם מאמו אפי' הכהן שאינו מטמא לאחיו ואחותו מאמו ולאחותו הנשואה אף על פי שהיא מאביו מתאבל הוא עליהן. ואם היתה אחותו זו הנשואה מאחיו הרי הוא מתאבל עליה דין תורה. וכתב עליו הרמב\"ן בת\"ה מ\"ש באחותו נשואה שאבילותם מן התורה זה לא ידענו לו צד סמך ומקום טענה:","\u0003ומ\"ש רבינו וא\"א הרא\"ש ז\"ל הסכים לדברי ר\"ת ור\"י הוא בפרק אלו מגלחין:\u0004 "],["\u0003בענין האבילות כו'\u0004 אם הוא יום מיתה אז הוא דאורייתא כתב ב\"י כלומר אם הוא יום מיתה וקבורה הוא דאורייתא לדעת הגאונים וכו' עכ\"ל ודבר פשוט הוא שכל זמן שלא נקבר אין שם אבילות אלא משיסתם הגולל כדלעיל בריש סימן שע\"ה וא\"כ בע\"כ הא דקאמר הכא דהאבילות הויא דאורייתא ביום מיתה אינו אלא כשנקבר בו ביום שמת ונסתם הגולל:","\u0003ומ\"ש וכ\"כ הרמב\"ם אלא שכתב אשתו בכלל אותם שהם מד\"ס והוא ודאי מן התורה וכו'\u0004 פי' רבינו בא להשיג על מ\"ש הרמב\"ם בסתם דאשתו הוא מד\"ס דפי' מד\"ס הוא כלומר מדבריהם והא ליתא דגדולה ודאי מן התורה הוא כדילפינן משארו אין שארו אלא אשתו ואף על פי דקטנה הוא מדבריהם דתקינו לה רבנן נשואין ליתומה קטנה כדי שלא ינהגו בה מנהג הפקר מ\"מ לא היה לו להרמב\"ם לומר בסתם שאשתו הוא מד\"ס כיון דגדולה הוא מן התורה ומיהו ידוע דרכו של הרמב\"ם שכל מה שאינו מפורש בתורה אע\"פ שהוא מן התורה ממדרש חכמים כגון הכא דדרשינן אין שארו אלא אשתו בין לענין טומאה בין לענין אבילות מד\"ס קרינן לה ורצונו לומר דאם היא גדולה הוי מן התורה אלא דאתיא ממדרש חכמים שזה נקרא ד\"ס לדעתו ז\"ל ולקטנה הוי מד\"ס ממש כלומר מדבריהם דאין לו עיקר בתורה וכ\"כ ב\"י והוא דבר פשוט:"]],["\u0010c0\u0011\u0010y0\u0011הקובר מתו קודם הרגל בענין שחל עליו אבילות ונהג בו אפילו שעה אחת קודם הרגל הרגל מפסיק האבילות ומבטל ממנו גזירת ז' וימי הרגל עולין לו למנין ל' הרי שבעה לפני הרגל וימי הרגל ומשלים עליהם השלשים ודוקא שנהג אבילות באותה שעה \u0010c1\u0011אפי' לא נהג אלא דברי' שבצינעא כגון ששמע שמועה קרובה ביום שבת שחל להיות ערב הרגל שאע\"פ שאינו נוהג אלא דברים שבצינעא הרגל מפסיק אבל אם שגג או הזיד ולא נהג אבילות או שהיה קרוב לחשיכה ולא היה יכול לנהוג אין הרגל מבטל האבילות \u0010y1\u0011וכל שכן אם לא ידע במיתת המת קודם הרגל שאין הרגל מבטלה \u0010y2\u0011אלא נוהג ברגל דברים שבצינעא ומונה ז' אחר הרגל ובאותם השבעה מלאכתו נעשית ע\"י אחרים ועבדיו ושפחותיו עושין בצינעא בתוך ביתו דכיון דכבר נתבטל בשבעת ימי הרגל ממלאכה אע\"פ שלא נתבטל מחמת האבל אלא מחמת הרגל מ\"מ סוף סוף נהג כדין אבילות בענין המלאכה הילכך אין להחמיר בו כמו בשאר אבילות ומלאכתו נעשית על ידי אחרים וכל ימי הרגל רבים מתעסקים בו לנחמו הילכך אין מתעסקין בו לנחמו אחר הרגל ורגל עולה למנין שלשים שהרי דין שלשים דהיינו גיהוץ ותספורת נוהגין ברגל \u0010y3\u0011וכתב הרמב\"ן ולא מתורת רגל לבד אסור בהן אלא אף מתורת אבל שהרי מתורת הרגל מותר ללבוש בגדים מגוהצין חדשים ולבנים ונוטל צפרניו במספרים ושמח שמחת מריעות והבא ממדינת הים ומבית השביה ומשאר דרכים שמנו חכמים מותרין לספר ולכבס ומדין אבילות אסורים בכולן כמו בחול שהוא אסור בתספורת ובגיהוץ בין לכבס בין ללבוש ואפי' הבא ממדינת הים ואסור בשמחת מריעות ואסור בנטילת צפרנים במספרים \u0010y4\u0011ומדברי א\"א הרא\"ש ז\"ל יראה שאינו אסור כלל מתורת אבילות אלא בדברים האסורין לו מתורת הרגל \u0010c2\u0011\u0010y5\u0011הקובר מתו ברגל בחה\"מ נוהג דין אנינות כל זמן שאינו נקבר \u0010y6\u0011ולאחר שיקבר נוהג דברים שבצינעא \u0010y7\u0011והרמב\"ם כתב שאינו נוהג אפי' דברים שבצינעא \u0010y8\u0011ולא נהירא \u0010c3\u0011\u0010y9\u0011והרגל עולה למנין שלשים שמשלים עליהם שלשים אפי' קברו בחג \u0010y10\u0011ולא אמרינן דחג שמיני עצרת מבטל \u0010y11\u0011ומתעסקין ברגל לנחמו \u0010c4\u0011ולאחר הרגל מתחיל למנות שבעה וכשיכלו ז' למיתת המת אף על פי שעדיין לא כלו ז' ימי האבילות מלאכתו נעשית ע\"י אחרים ו) \u0010c5\u0011ואין רבים מתעסקין בו לנחמו כגון אם קברו בג' ימים אחרונים של הרגל מלאכתו נעשית ע\"י אחרים בג' ימים אחרונים של האבל \u0010c6\u0011\u0010y12\u0011ואם נהג ז' לפני הרגל והרגל פגע בו תוך שלשים הרגל מבטל ממנו גזירת שלשים אפי' אם חל יום ז' בערב הרגל דמקצת היום ככולו ועולה תחלתו לסוף ז' וסופו עולה לתחילת שלשים ומותר לספר ולכבס ולרחוץ ערב הרגל \u0010y13\u0011וכן אם חל יום שמנה בשבת שבערב הרגל מותר לספר ולכבס ולרחוץ בע\"ש \u0010y14\u0011ואם לא גילח בע\"ש או בערב הרגל מותר לגלח אחר הרגל שכבר נתבטל ממנו גזירת ל' אבל תוך הרגל לא יגלח כיון שהיה אפשר לו לגלח קודם הרגל ואם חל שביעי שלו בשבת בערב הרגל אסור לגלח בערב שבת ומותר לגלח אחר הרגל וכן בתוך הרגל כיון שלא היה יכול לגלח קודם הרגל \u0010c7\u0011\u0010y15\u0011ואם חל יום ששי או יום ראשון שלו ערב הרגל מותר לספר ולכבס כיון שאי אפשר לו לעשותם בלילה אבל אסור לרחוץ עד הלילה כיון שאפשר לו לרחוץ בלילה אע\"פ שמותר לכבס מבעוד יום אסור לו ללובשן עד הלילה וריב\"א כתב כמו שאסור לרחוץ כך אסור לכבס כל היום ומיהו בערב סמוך לחשיכה מותר בשניהם וא\"צ להמתין עד הלילה והרמב\"ם כתב שאינו מותר לא לגלח ולא לרחוץ ולא לסוך ולא לעשות שום מלאכה עד שנכנס י\"ט וי\"ט מפסיק שאר הז' ולאחר י\"ט משלים ל' מיום המיתה וסברא ראשונה הוא סברת הראב\"ד ולזה הסכים א\"א ז\"ל והא דרגל מבטל גזירת ל' דוקא בשאר מתים אבל באביו ואמו אינו תלוי בשלשים אלא אסור לספר עד שיגערו בו חביריו ומיהו כתוב בספר המצות דוקא שפוגע בו הרגל בתוך ל' אבל אם עברו שלשים ואח\"כ פגע בו הרגל או אפי' אם חל יום ל' ברגל הרגל מבטלו \u0010c8\u0011\u0010y16\u0011ר\"ה ויום הכפורים חשובין כרגלים לדחות האבילות ועולין בשביל ז' ימים אע\"פ שאינו אלא יום אחד כעצרת \u0010y17\u0011וזה הכלל לכל המועדים נהג שעה אחת לפני הפסח אותה שעה חשובה כשבעה ושמונת ימי הפסח הרי ט\"ו ומשלים עליהן ט\"ו שעה לפני עצרת חשובה כשבעה ועצרת חשוב כשבעה כיון שאם לא קירב קרבן עצרת בעצרת יש לו תשלומין כל ז' חשוב כשבעה הרי י\"ד ומשלים עליהם י\"ו וי\"ט שני של עצרת עולה למנין י\"ו כיון שאנו בקיאין בקביעותא דירחא ואין אנו עושין יום טוב שני אלא משום מנהג חשוב כחול ועולה למנין י\"ו שעה לפני ראש השנה מבטל ממנו גזירת ז' ור\"ה הרי י\"ד ומגלח ערב יום הכיפורים שמבטל ממנו גזירת שלשים שעה אחת לפני י\"ה וי\"ה הרי י\"ד ומגלח ערב החג שעה אחת לפני החג והחג י\"ד ושמיני עצרת שהוא רגל בפני עצמו חשוב כז' הרי כ\"א ויום ב' של שמיני עצרת שהוא כמו חול כדפרישית הרי כ\"ב ומשלים עליהם ח' \u0010y18\u0011וי\"א שהקובר מתו קודם ר\"ה אין י\"כ מבטל ממנו גזירת ל' וכן אם קוברו קודם י\"ה אין החג מבטל ממנו גזירת שלשים דתרי קולי בחדא אבילות לא עבדינן שיבא רגל אחד ויבטל גזירת שבעה ויבא רגל אחר ויבטל גזירת שלשים וכן דעת בה\"ג שכתב היכא שמת לו מת שעה קודם ר\"ה עולה למנין שבעה ור\"ה שבעה הרי י\"ד וז' שבין ראש השנה לי\"ה הרי כ\"א וי\"ה שהוא כרגל חשוב כשבעה הרי כ\"ח יום ונקיט בתר י\"ה ב' ימים וסברא ראשונה היא סברת הרמב\"ן ולזה הסכים א\"א ז\"ל \u0010y19\u0011כתב ה\"ר שמשון הקובר מתו שעה אחת לפני הרגל שאותה שעה והרגל חשובין כי\"ד ומיד אחר הרגל יש לו דין שבוע ג' לענין שיושב במקומו ואינו מדבר אפילו בר\"ה ועצרת שאינו אלא יום אחד כתב בה\"ג הלכה למעשה הקובר מתו ברגל לא חיילא עליה אבילות אלא אחר הרגל ונקיט יומי דאבילות מי\"ט האחרון אף ע\"ג דלא נהיג ביה אבילות עולה למנין ז' ולא נקיט לאחר הרגל אלא ששה ימים ומאן דשכיב ליה שכבא ביום שני שהוא י\"ט האחרון או ביום שני דעצרת נהיג ביה אבילות דהוא יום מיתה וקבורה דהכי אסכימו רבנן דאבילות יום ראשון דאורייתא דדחי עשה דרבנן וכן כתבו כל הגאונים \u0010y20\u0011וכ\"כ הרמב\"ן וכתב וכבר פירשנו שאינו קורע בי\"ט שני ופירשנו לדעת הגאונים שאין דינן אלא בשבעה מתים המפורשים בתורה אבל באותן שהוסיפו עליהן מדברי סופרים אין מתאבלים עליהם בי\"ט וי\"א דביום טוב שני של ר\"ה אין מתאבלין כלל דקדושה אחת להן אע\"פ שעולה אינו נוהג בו אבילות וזו היא דעת הרמב\"ם ולפי דעתו ודעת הגאונים כיון שהוא דרבנן אתי אבילות יום ראשון שהוא דאורייתא ודחי ליה הלכך נוהג בו כבשאר י\"ט שני של גליות ע\"כ וא\"א הרא\"ש ז\"ל כתב אלו דברי הראשונים אבל חכמים האחרונים כתבו שאין שום אבילות דאורייתא אף ביום הראשון כי אם אנינות וראיותיהן ברורות וחזקות ולא תזוז מינה ע\"כ ומ\"מ לא היה מוחה במי שנוהג כדברי הגאונים:",["הקובר את מתו קודם הרגל בענין שחל עליו אבילות ונהג בו אפי' שעה אח' קודם הרגל מפסיק האבילות וכו' בפרק אלו מגלחין (מועד קטן יט.) תנן הקובר את מתו ג' ימים קודם לרגל בטלה ממנו גזירת שבעה שמונה ימים קודם לרגל בטלה ממנו גזירת שלשים ובגמרא [כ.] ת\"ר קיים כפיית המטה שלשה ימים קודם לרגל א\"צ לכפותה אחר הרגל דר\"א וחכ\"א אפי' יום אחד ואפי' שעה אחת ואסיקנא בגמרא דהלכה כחכמים. ומ\"ש וימי הרגל עולין לו למנין ל' וכו' מימרות אמוראי שם. ומ\"ש ודוקא שנהג אבילות באותה שעה וכו' אבל אם שגג או הזיד ולא נהג אבילות וכו' אין הרגל מבטל האבילות כן דקדק הראב\"ד מדקתני קיים כפיית המטה וכתבתי לשונו בסימן שצ\"ו: וכתב רבי' ירוחם ומ\"מ נ\"ל דרגל עולה למנין ל' דלא גרע מקובר מתו ברגל עכ\"ל ודבר פשוט הוא דבנודע לו מיתת המת קודם הרגל מיירי. ומ\"ש אפי' לא נהג אלא דברים שבצינעא וכו' הרגל מפסיק כ\"כ המרדכי במ\"ק וכ\"כ הגה\"מ:","\u0003ומ\"ש וכ\"ש אם לא ידע במיתת המת קודם הרגל שאין הרגל מבטלו פשוט הוא:\u0004 ","ומ\"ש אלא נוהג ברגל דברים שבצינעא ומונה ז' אחר הרגל ובאותן הז' מלאכתו נעשית ע\"י אחרים וכו' עד ורגל עולה למנין ל' נלמד מדין הקובר את מתו ברגל שיתבאר בסמוך.","ומ\"ש בשם הרמב\"ן הוא בת\"ה והביא ראיה לדבר מדאמרינן בגמרא לענין ז' לא קמיבעיא לי שאין רגל עולה למנין ז' דלא נהג מצות ז' ברגל כי קמיבעיא לי למנין ל' דקא נהגא מצות ל' ברגל דאסור בתספורת וכיבוס וא\"ת שאין אבילות חלה עליו ברגל אלא שהוא נוהג בהן מפני הרגל בדברים שכל אדם אסור בו מצות ל' מנאו בו שתעלה למנין שלשים והרי במצות ז' נמי נוהג קצת ברגל שאינו מכבס כסותו במים והרבים מתעסקים בו כדין אבל ואפ\"ה כיון דלא נהיג במצות ז' כדינו אינו עולה אלא ש\"מ אבילות נמי נוהג בהם וכל גזירת ל' עליו ותמה על עצמך היאך יהא שמח בשמחת מריעות והרבים מתעסקין בו כאבל אלא ש\"מ שהוא נוהג במצות ל' כמנהגו בהם בחול וטעמא דמילתא מפני שהם מצות לא תעשה ומדין הרגל נמי נוהג במקצתן הילכך כשנוהג בכולן באבילותו אין אבילותו מתפרסמת עליו לפיכך אמרו עולה למנין ל' דקא נהגו מצות ל' ברגל כולו כדינו בחול ואינו עולה למנין ז' שאינו נוהג ברובן של מצות ז' עכ\"ל:","ומ\"ש ומדברי א\"א ז\"ל יראה שאינו אסור כלל מתורת אבילות אלא בדברים האסורים לו מתורת הרגל נראה שלמד כן מדכתב בפרק א\"מ שהטעם שאין שמיני עצרת מבטל גזירת ל' לקובר מתו בתוך החג היינו משום דלא נהג כלל דין ל' אע\"ג שגיהוץ ותספורת אסורים במועד מ\"מ מטעם אבילות מיהו לא נאסר. ולענין הלכה נקטינן כדברי הרמב\"ן שהם נכוחים בטעם וראיה: דין שמע שמועה קרובה בשבת ערב הרגל יתבאר בסימן ת\"ב בס\"ד:","הקובר את מתו ברגל בחה\"מ נוהג כל דין אנינות כל זמן שאינו נקבר דקדק לכתוב בח\"ה דאילו בי\"ט אינו נוהג דיני אנינות כמו שנתבאר בסי' שמ\"א ואע\"ג דבי\"ט שני נוהג דיני אנינות וכן נוהג ג\"כ בי\"ט ראשון אם רוצה לקברו ע\"י עממין כמו שנתבאר שם רבי' מילתא פסיקתא נקט דבח\"ה ודאי נוהג אנינות ובדין הוא דהו\"ל לכתוב דבי\"ט ב' נמי נוהג אנינות אלא שסמך על מ\"ש בסימן הנזכר:","ומ\"ש ולאחר שיקבר נוהג דברים שבצינעא בריש כתובות (ד'.) מסייע לר' יוחנן דאמר אע\"פ שאמרו אין אבילות במועד אבל דברים שבצינעא נוהג:","ומ\"ש בשם הרמב\"ם שאינו נוהג דברים שבצינעא בפ\"י כתב הרגלים וכן ר\"ה ויה\"כ אין דבר מדברי אבילות נוהג בהם. וכתב הרמב\"ן בת\"ה שיש כת מן החכמים שסוברים כמותו וטעמא משום דהא דקאמר בריש כתובות מסייע ליה לר' יוחנן דאמר אע\"פ שאמרו אין אבילות במועד אבל דברים שבצינעא נוהג הוא שמועתו של ר' יוחנן הוא השמועה האמורה בפרק אלו מגלחין אהא דגרסינן אביי אשכחיה לרב יוסף דפריס סודרא ארישיה ואזיל ואתי בביתיה א\"ל לא סבר לה מר אין אבילות בשבת א\"ל הכי א\"ר יוחנן דברים שבצינעא נוהג והם מפרשים דדוקא בשבת לפי שהיא עולה הנהיגו בה בצינעא אבל ברגלים שמפסיקים ואינן עולים לדברי הכל אינו נוהג לא בצינעא ולא בפרהסיא עכ\"ל. ונראה מדבריו שהיו גורסים בההיא דר' יוחנן דריש כתובות בשבת במקום במועד.","ומ\"ש רבינו ולא נהירא הוא משום דהרמב\"ן חלק על הרמב\"ם וסיעתו והאריך לטעון עליהם והעלה דדברים שבצינעא נוהגים במועד וכ\"פ התוס' והרא\"ש בריש כתובות וכתבו שכ\"פ בה\"ג ולענין הלכה נקטינן כוותייהו דרבים נינהו וגם כי בה\"ג שדבריו דברי קבלה סבר כותייהו.","ומ\"ש רבינו והרגל עולה למנין ל' שמשלים עליו ל' אפי' קברו ברגל מבואר בברייתא שם פרק א\"מ.","ומ\"ש ולא אמרינן דחג שמיני עצרת מבטל שם [כד:] אמר רבינא הילכך יום אחד לפני החג וחג ושמיני שלו הרי כאן כ\"א יום כלומר ולא צריך למינקט אחר הרגל אלא ט' ימים הרי בהדיא דאין חג שמ\"ע מבטל גזירת ל' אפי' קבר מתו קודם הרגל וכ\"ש כשקברו ברגל: וכתב שם הרא\"ש שהטעם מפני שלא נהג כלל דין ל' אע\"ג דגיהוץ ותספורת אסורים במועד מ\"מ מטעם אבילות לא נאסר. וכתבו הגה\"מ בפרק י' דשמיני עצרת אינו עולה לו כ\"א יום אחד כשקברו ברגל .","\u0003ומ\"ש ומתעסקים ברגל לנחמו ולאחר הרגל מתחיל למנות ז' וכו'\u0004 עד בשלשה ימים האחרונים של האבל ברייתא שם וכתב הגה\"מ בפ\"י בשם סמ\"ק אם עברו ג' ימים אחר הקבורה מותרת מלאכתו על ידי אחרים כל ימי אבילותו עכ\"ל וכתב רבינו ירוחם אותם הימים שנשארו מן הרגל אחר קבורת המת דינן לענין מלאכה המותרת במועד כדין ז' ימי אבילות שמלאכתו נעשית על ידי אחרים פי' בבתיהם אבל לא בביתו ודוקא דבר שאינו אבד אבל דבר האבד הוא בעצמו עושה ועבדיו ושפחותיו עושין בצינעא בתוך ביתו כי לא נאסרו עבדיו ושפחותיו עכ\"ל ואהא דתניא ואין רבים מתעסקים בו שכבר נתעסקו בו ברגל פירשו התוספות תנחומין וברכת השורה והרי\"ט פי' לענין הבראה ע\"כ ומשמע דדוקא לדברים אלו הוא דאין מתעסקים עמו אבל מבקרין אותו כל ימי אבלו וכך מפורש בירושלמי פרק אלו מגלחין הקובר את מתו שלשה ימים בתוך הרגל מונה ז' לאחר הרגל ג' ימים הראשונים הרבים מתעסקים עמו ד' ימים האחרונים אין הרבים מתעסקים עמו מהו להראות לו פנים ר' יעקב בר אידי בשם ר' חנינא והלא אמרו אין אבל בשבת מפני מה אמרו להראות לו פנים לאו מפני הכבוד והכא נמי מפני הכבוד ויש לתמוה על הרי\"ף שהשמיט הא דקתני מלאכתו נעשית ע\"י אחרים וכו' עד סוף הברייתא וכן יש לתמוה על הרמב\"ם שסתם וכתב בפ\"י שהקובר את מתו ברגל שאחר הרגל מתחיל למנות ז' ונוהג בהן כל דברי אבילות: כתב הרא\"ש בפרק אלו מגלחין ובפ\"ק דכתובות דאיכא מ\"ד דאי איתרמי ליה אבילות ברגל שצריך הוא שיישן בין האנשים והיא בין הנשים והראב\"ד והרא\"ש דחו דבריו וכתבו רבינו בסימן שפ\"ג:","ואם נהג ז' לפני הרגל והרגל פגע בו תוך שלשים הרגל מבטל ממנו גזירת שלשים אפי' אם חל יום ז' בערב הרגל וכו' בפרק אלו מגלחין (מועד קטן יט:) איפליגו תנאי בחל יום ז' בערב הרגל ואיפסיקא הילכתא בגמרא כאבא שאול דאמר מצות ז' מבטלת גזירת ל' כלומר שאם חל יום ז' שלו בערב הרגל בטלה ממנה גזירת שלשים דמקצת היום ככולו ויום ז' עולה לכאן ולכאן:","ומ\"ש וכן אם חל יום ח' בשבת שבערב הרגל שם מודים חכמים לאבא שאול כשחל ח' שלו בשבת ערב הרגל שמותר לגלח בע\"ש:","ומ\"ש ואם לא גילח בערב הרגל או בע\"ש מותר לגלח אחר הרגל שכבר נתבטל גזירת ל' זה פשוט אליבא דאבא שאול דאיפסיקא הלכתא כוותיה ומ\"ש אבל תוך הרגל לא יגלח כיון שהיה איפשר לו לגלח קודם הרגל ואם חל יום ז' שלו בשבת ערב הרגל אסור לגלח בע\"ש ומותר לגלח אחר הרגל וכן בתוך הרגל כיון שלא היה יכול לגלח קודם הרגל שם אמתני' דאלו מגלחין במועד תנא האבל מותר בגילוח ה\"ד אילימא שחל ח' שלו בערב הרגל איבעי ליה לגלוחי בערב הרגל אלא ח' שלו בשבת ערב הרגל איבעי ליה לגלוחי ע\"ש לא צריכא שחל ז' שלו בשבת ערב הרגל וסבר לה כאבא שאול דאמר מקצת היום ככולו ויום שביעי עולה לכאן ולכאן וכיון דשבת הוי אנוס הוא:","\u0003ואם חל יום ששי או יום א' שלו ערב הרגל מותר לספר ולכבס וכו'\u0004 כבר נתבאר בטוא\"ח סימן תקמ\"ח: \u0005ב\"ה והא דרגל מבטל גזירת ל' דוקא בשאר מתים וכו' עד הרגל מבטלו עיין בטור אורח חיים סימן תקמ\"ח:\u0006 כתוב בתשב\"ץ על אבל שחל יום ג' בערב י\"ה ונצטווה לרחוץ אבל לא ללבוש לבנים דוקא ביום ג' מותר פחות מכאן לא וכתב עוד שפעם אחד אירע לאחד יום ששי לימי אבלו בערב פסח ואמר דכיון שהיה זמן שחיטת פסח ואז בימיהם היו קורין הלל והיה יו\"ט אין אבילות נוהג בו ואין לדבר זה ולא לראשון לא סמך ולא ראיה:","ר\"ה ויה\"כ חשובים כרגל לדחות האבילות וכולי בפרק אלו מגלחין פלוגתא דתנאי במתני' [יט.] ואיפסיקא בגמרא [כד:] הלכתא כר\"ג דאמר ר\"ה ויה\"כ כרגלים וכחכמים דאמרי עצרת כרגלים:","\u0003ומ\"ש זה הכלל לכל המועדים נהג שעה אחת לפני הפסח אותה שעה חשובה כז' וכו'\u0004 שעה אחת לפני עצרת חשובה כז' ועצרת חשוב כז' וכו' (שם) דרש רב ענני בר ששון יום אחד לפני עצרת ועצרת הרי כאן י\"ד דא\"ר אלעזר מנין לעצרת שיש לה תשלומין כל ז' שנאמר בחג המצות ובחג השבועות וכו' אדבריה רב פפא לרב איויא סבא ודרש יום אחד ור\"ה הרי כאן י\"ד אמר רבינא הילכך יום א' לפני החג וחג ושמיני שלו הרי כאן כ\"א יום ומ\"ש די\"ט שני של עצרת עולה למנין י\"ו הואיל ובקיאינן בקביעא דירחא כ\"כ שם הרא\"ש וכתב רבינו ירוחם (נתיב כ\"ח ח\"ג) דביום שני של ר\"ה לא אמרינן הכי דתרווייהו כחד יומא חשיב הילכך יום אחד לפני ר\"ה וב' ימים של ר\"ה הרי י\"ד ומשלים עליהם י\"ו ע\"כ ודבריו לדעת י\"א ובה\"ג שכתב רבינו בסמוך דאילו לדעת הרמב\"ן והרא\"ש די\"ה מבטל ממנו גזירת ל' אין נפקותא ביום שני של ר\"ה אם עולה או אינו עולה ומ\"ש גבי שעה אחת קודם ר\"ה שמגלח בעי\"כ וכן בשעה אחת לפני יה\"כ שמגלח ערב החג כ\"כ הרא\"ש שם בשם הרז\"ה והרמב\"ן ז\"ל:","ומ\"ש וי\"א שהקובר מתו קודם ר\"ה אין י\"ה מבטל ממנו גזירת ל' וכן אם קברו קודם י\"ה אין החג מבטל ממנו גזירת ל' וכו' כ\"כ הרא\"ש שם בשם הראב\"ד שדקדק כן וכתב שם שהרמב\"ן דחה דבריו והסכים הרא\"ש לדברי הרמב\"ן ז\"ל וכתבו הגה\"מ שלזה הסכים הר\"מ וגם בהג\"א כתב בשם א\"ז שיש לסמוך על זה הלכה למעשה והרמב\"ם כתב בפ\"י הקובר את מתו אפי' שעה אחת קודם הרגל או קודם ר\"ה וי\"ה בטלה ממנו גזירת ז' נמצא מונה לאחר ר\"ה וי\"ה כ\"ג יום ולאחר פסח י\"ו יום עכ\"ל. וכבר כתבתי בטור א\"ח סימן תקמ\"ח שכתב הרמב\"ן ליישב דבריו ושכתב דמכל מקום אין דבריו נראין ולענין הלכה כיון שהר\"ם והרא\"ש וא\"ז מסכימים לדברי הרמב\"ן הכי נקטינן :","כתב ה\"ר שמשון הקובר מתו שעה אחת לפני הרגל שאותה שעה והרגל חשובים כי\"ד ומיד אחר הרגל יש לו דין שבוע שלישית וכו' בפרק אלו מגלחין כ\"כ הרא\"ש בשמו וגם הגה\"מ בפ\"י כ\"כ: כתב בה\"ג הלכה למעשה הקובר מתו ברגל לא חיילא עליה אבילות אלא הרגל ונקיט יומי אבילות מי\"ט האחרון וכו' כ\"כ הרא\"ש בפרק אלו מגלחין והרמב\"ן בת\"ה בשמו וכ\"פ הרי\"ף בפרק אלו מגלחין וכ\"פ הרמב\"ם בפ\"י: ומ\"ש בדברי הרמב\"ן ולפי דעתו ודעת הגאונים כיון שהוא דרבנן וכו' היינו לומר דהרמב\"ם הוא סובר כדעת הגאונים דאבילות יום ראשון דאורייתא קאמר דלפי דעת זו יום ב' של ר\"ה אע\"ג דכיומא אריכתא הוא כיון דקדושה דידיה דרבנן היא אתי אבילות יום ראשון דאורייתא ודחי לה ואע\"ג דגם הרמב\"ם סבר דאבילות יום א' דאורייתא סובר דכיון דשני ימים של ר\"ה קדושה אחת הן הוי כאילו הן דאורייתא ובנוסחת ת\"ה שבידינו כתוב ולפי דעתם ודבריהם של הגאונים כיון שהוא מדרבנן וכו'. ומ\"ש בשם הרא\"ש אלה דברי הראשונים אבל חכמים האחרונים כתבו שאין שום אבילות דאורייתא אף ביום ראשון וכולי בפרק אלו מגלחין וחכמים האחרונים הללו שכתבו מבואר בדבריו שם שהם ר\"ת וה\"ר יהודה והג\"מ כתבו בפרקי' שכדאי הגאונים שדבריהם דברי קבלה לסמוך עליהם. ולענין הלכה כיון שהגאונים והרי\"ף והרמב\"ם והראב\"ד והרמב\"ן סוברים דאבילות יום ראשון דאורייתא כמו שנתבאר בסימן שצ\"ח הכי נקטינן .","ומ\"ש רבינו בשם הרמב\"ן שאינו קורע בי\"ט שני כ\"כ גם הרמב\"ם בפרק י\"א ואע\"פ שכתב נ\"י בפרק א\"מ שהמפרשים נסתפקו אם קורע בי\"ט ב' אם לאו לא שבקינן פשיטותא דהרמב\"ם והרמב\"ן משום ספיקא דידהו ואפילו לדידיה כיון דספיקא נינהו אינו קורע דשב ואל תעשה עדיף: מת מעי\"ט ומסופקים שמא לא יספיקו לקוברו ונתנוהו לנכרים והוליכוהו לקבר אם חל עליהם אבילות מיד ובטלה גזירת ז' או לא נתבאר בסימן שע\"ה גרסי' בירושלמי אין מראין פנים לא בר\"ה ולא ביה\"כ וכתב הרמב\"ן בת\"ה שהרי\"ץ גיאת העלה מתוך הירושלמי דכשחל י\"ה בשבת מראין בו פנים והוא ז\"ל פירש הירושלמי בהפך דבין חל בשבת בין חל בחול אין מראין בו פנים ולענין הלכה נקטינן כהרמב\"ן דבתרא הוא (פי' מראין פנים מבקרין האבל):"],["\u0003הקובר מתו קודם הרגל וכו'\u0004 בפרק אלו מגלחין (מועד קטן דף י\"ט) תנן הקובר את מתו ג' ימים קודם לרגל בטלה הימנו גזירת שבעה שמנה ימים בטלה הימנו גזירת ל' וכו' ובגמרא מייתי ברייתא דחכמים פליגי ואמרי דגזירת ז' בטלה אפי' לא היה אלא יום אחד ואפי' שעה אחת וכתב הרי\"ף והרא\"ש ואסיקנא דהכי הילכתא ועוד כתב הרא\"ש שהראב\"ד הכריח מהך ברייתא מדפליגי בקיים כפיית המטה אי בעינן ג' ימים אי סגי בשעה אחת שמע מינה דאין הרגל מפסיק אלא א\"כ נהג אבילות דאי אפילו לא נהג כלל לא הו\"ל למתני קיים כפיית המטה אלא הו\"ל למתני הקובר מתו כלישנא דמתני' אלמא קיים אין לא קיים לא ומה שלא פירש במתני' קא מפרש בברייתא ועיין בב\"י הביא ל' הראב\"ד בריש סי' שצ\"ו וז\"ש רבינו ודוקא שנהג אבילות וכו' וכן מ\"ש רבינו וכל שכן אם לא ידע במיתת המת וכו' רצונו לומר דלא ידע קודם הרגל אלא משנכנס הרגל נודע לו לפיכך עולין לו ימי הרגל למנין ל' כיון שנהג אבילות ברגל בדברים שבצינעא אבל אם לא נודע לו משנכנס הרגל אין ימי הרגל עולין לו אלא מאותו יום שנודע לו שנהג דברים שבצינעא אבל מקמי הכי דלא נהג דברים שבצינעא אינן עולין לו וכ\"כ בספר המאור וז\"ל ואי איכא מקרובי המת מאן דאתיא ליה שמועה ביום י' שלאחר החג אי הויא ליה כשמועה קרובה או כשמועה רחוקה יש מן החכמים שנסתפקו לו זה הדבר ותלה הדבר להקל משום דהויא ליה ספק אבילות וכדברי המיקל באבילות נקטינן ולדעתי נ\"ל בזה הדבר להחמיר שאין הדברים נראין שיעלה הרגל למי שלא בא לו עדיין שמועת המת וכו' והאריך בראיות וטעמים ונלפע\"ד דהחכמים שהורו להקל נסתפקו במ\"ש הראב\"ד דדוקא מנהג אבילות שעה אחת הוא דמפסיק דשמא אפי' לא נהג אבילות כלל כיון שקבר מתו שעה אחת קודם הרגל מפסיקו וא\"כ בשנקבר ערב הרגל דקי\"ל יום א' לפני החג והחג ושמיני שלו הרי כאן כ\"א יום וט' ימים אחר החג הו\"ל שלשים השתא לפ\"ז כד אתיא ליה השמועה ביום עשירי שלאחר החג הו\"ל ל\"א וחשבינן ליה שמועה רחוקה או שמא כיון שלא נהג כלל אבילות אין החג מפסיק וגם אינו עולה והו\"ל ספק אבילות והכריח בעל המאור להחמיר משום דדבר פשוט הוא דאינו מפסיק ואינו עולה לו הרגל למי שלא ידע במיתת המת וכדכתב הראב\"ד גם הר\"ר ירוחם ונמוקי יוסף הסכימו לדברי הראב\"ד ובעל המאור וכך הוא דעת הרמב\"ן בסת\"ה [דף ע\"ו ע\"א] והכי נקטינן וכתב מהרש\"ל לפי זה היכא דמת ביום א' ונקבר ביום ב' אע\"פ שהקרובים שהיו אצל הקבורה מונין מיום הקבורה כי אז היתה סתימת הגולל מ\"מ אותן שלא היו אצל הקבורה ולא נודע להן המת עד שהגיע יום ל' מיום הקבורה א\"צ לנהוג אבילות כיון דיום שמיעה דידהו הויא יום ל\"א מיום המיתה והו\"ל שמועה רחוקה דלגבי דין שמיעה יום המיתה הוא עיקר וכדתנן הריני כיום שמת בו אבא הריני כיום שמת בו גדליה ב\"א:","\u0003ומ\"ש אפי' לא נהג אלא דברים שבצינעא כגון ששמע שמועה קרובה ביום שבת כו'\u0004 כ\"כ המרדכי במ\"ק וכ\"כ הגהת מיי' והאריך בזה הביאו ב\"י לקמן סימן ת\"ב:","\u0003הקובר את מתו ברגל בחה\"מ כו'\u0004 כלומר דאילו בי\"ט איכא לחלק דבי\"ט שני נוהג אנינות אבל בראשון אינו נוהג אנינות אא\"כ רוצה לקברו ע\"י עממים אבל בח\"ה אין חילוק לעולם נוהג אנינות וע\"ל סי' שמ\"א ס\"ב וכן פי' ב\"י. ומ\"ש ולאחר שיקבר נוהג דברים שבצינעא ה\"א בכתובות (דף ד) דא\"ר יוחנן אע\"פ שאמרו אין אבילות במועד אבל דברים שבצינעא נוהג וכתבו התוס' לשם דה\"ג פסקו הלכה כרבי יוחנן והרמב\"ם היה גורס בההיא דר' יוחנן בשבת במקום מועד וסבר דוקא שבת כיון דעולה ואינו מפסיק נוהג בו דברים שבצינעא אבל רגלים דמפסיקין ואינן עולין אינו נוהג לא בצינעא ולא בפרהסיא וכתב הרמב\"ן בסת\"ה [דף ע\"ד ע\"ג] דאנו סומכין על דברי הראשונים שדבריהם דברי קבלה כ\"ש שהגירסא הכתובה בכל הספרים היא במועד ועוד האריך וע\"ש ולכן כתב רבי' ולא נהירא והכי נקטינן לאיסורא ואפ\"ה נראה דלא חיישינן למימר דילמא כיון דאיכא מורי הוראה דמתירין לו דברים שבצינעא א\"כ קילא ליה הך אבילות וצריך שמירה שישן הוא בין האנשים וכו' וכדחיישי' גבי חתן דלא אמרינן קילא ליה אלא היכא דאיכא תרתי דקילא ליה ואיכא נמי אפושי שמחה וע\"ל בסי' שפ\"ב סעיף ד' ה' ו':","\u0003ומ\"ש והרגל עולה למנין ל' וכו'\u0004 נראה דמ\"ש ולא אמרינן דחג ש\"ע מבטל וכולי ה\"ק לא אמרינן דמבטל לגמרי היכא דקברו לפני הרגל אלא אינו עולה אלא לז' וכן בקברו ברגל לא אמרינן דמבטל ממנו ז' ממנין ל' אלא אינו עולה לו אלא ליום אחד דבין בזו ובין בזו אין ש\"ע מבטל אבילות דכל אחד לפי עניינו אבל מהרש\"ל בתשובה סימן ה' למד מל' רבינו דדוקא מבטל הוא דאינו מבטל הא לענין עליית ז' ימים למנין השלשים שפיר עולה דאם לא כן לאשמועינן דאפי' אינו עולה כי אם ליום אחד כ\"ש דאינו מבטל עכ\"ל ואין זה קושיא כלל דרבינו כתב ל' דאינו מבטל דמשמע הא והא כדפרישית דאינו מבטל לגמרי בקובר מתו לפני הרגל וגם אינו מבטל ממנו ז' בקובר מתו ברגל והכי משמע לשונו שאמר והרגל עולה וכו' אפי' קברו בחג ולא אמרינן דחג שמיני עצרת מבטל וכו' דה\"ק לא מיבעיא בקברו קודם החג דאינו מבטל לגמרי אלא אפי' קברו בחג אינו מבטל ממנו ז' ועוד איכא לתמוה דלפי פי' מהרש\"ל היאך תולה רבי' דין זה דאינו מבטל לגמרי אבל עולה למנין ז' בקובר מתו בתוך הרגל הלא אפי' בקוברו לפני הרגל נמי כך הדין כמ\"ש אח\"כ וזה הכלל וכו' ועוד דהתוס' פרק אלו מגלחין בד\"ה הקשה בתוס' הרב [דף כ\"ד] פסקו להדיא דאינו עולה אלא ליום א' וכ\"כ המרדכי וכ\"כ ב\"י ע\"ש הגהת מיי' וטעמם נכון דכיון דלא אשכחן בתלמודא דש\"ע עולה לו למנין ז' אלא בקובר מתו לפני הרגל א\"כ איכא למימר התם שאני כיון דכבר בטל ממנו הרגל גזירת ז' וגם ז' ימי החג עלו לו למנין ל' הילכך גם ש\"ע חשוב כז' למנין ל' אבל בקובר מתו ברגל דלא בטל ממנו כלום אין כח לש\"ע שיהא חשוב כז' למנין ל' עד שימנה תחלה ז' ימי אבילות ודבר זה הוא פשוט והרב ז\"ל דחהו מדחי אל דחי ואינו מתיישב כלל לפע\"ד ע\"כ נראה כמו שפסקו התוס' והמרדכי והגהת מיי' הכי נקטינן דלא כמהרש\"ל:","\u0003ומ\"ש ולאחר הרגל מתחיל למנות ז' וכו'\u0004 עד מלאכתו נעשית ע\"י אחרים בג' ימים אחרונים של אבל פי' אחרים עושים מלאכתו בבתיהם אבל לא בביתו של אבל ומיהו עבדיו ושפחותיו עושין לו בצינעא בתוך ביתו וכתב ה\"ר ירוחם דכן הדין באותם הימים שנשארו מן הרגל אחר קבורה לענין מלאכה המותרת במועד אפי' אינו דבר האבד שמלאכתו נעשית על ידי אחרים בבתיהם ועבדיו ושפחותיו עושין ל בצינעא בתוך ביתו ואם הוא דבר האבד מותר לעשות בעצמו ע\"כ ומביאו ב\"י וכ\"כ התוס' פרק אלו מגלחין סוף (מועד קטן דף י\"ט) בד\"ה ומלאכתו נעשית והכי נקטינן:","\u0003ומ\"ש ואין רבים מתעסקים בו לנחמו וכו'\u0004 פירש ב\"י על שם הירושלמי דדוקא קאמר ואין רבים מתעסקים בו לנחמו דעסקי דברי תנחומין הוא דאין צריך לנחמו מנין הימים שניחמוהו ברגל אבל מראים לו פנים מפני הכבוד כדרך שמראים פנים לאבל בשבת מפני הכבוד והכי משמע לישנא דקאמר אין מתעסקים בו לנחמו דדוקא לנחמו לא אבל מראים לו פנים וכך פסק בש\"ע והכי נקטינן:","\u0003ואם נהג שבעה וכו'\u0004 וכן אם חל יום שמנה בשבת שבערב הרגל וכו' בפרק ואלו מגלחין (מועד קטן דף י\"ט) פליגי תנאי בחל יום שבעה בערב הרגל ואיפסיקא הילכתא כאבא שאול דמקצת היום ככולו ויום שביעי עולה לו לכאן ולכאן ומודים חכמים לאבא שאול כשחל שמיני שלו להיות בשבת ערב הרגל שמותר לגלח ע\"ש ואיכא לתמוה אמ\"ש רבינו וכן אם חל יום שמנה בשבת דמשמע דלא זו אף זו קאמר והא ליתא דבחל יום שבעה בערב הרגל פליגי ביה ובחל יום שמנה בשבת אף חכמים מודים לאבא שאול ונראה ליישב דקשיא ליה לרבי' לאיזה צורך קאמר תלמודא דמודים חכמים לאבא שאול כשחל ח' שלו להיות בשבת ערב הרגל דמאי נפקא מינה אפילו לא יהיו מודים הלא הלכה שאול אלא בע\"כ דאיכא סברא איפכא ולמימר דע\"כ לא קאמר אבא שאול דמותר לספר ולכבס ולרחוץ משום דיום ז' עולה לו לכאן ולכאן אלא בחל יום שביעי בערב הרגל דעולה תחלתו ליום ז' וסופו כיון שנכנס הרגל עולה לתחלת ל' ומבטל ממנו גזירת ל' אבל בחל יום שמנה בשבת שבערב הרגל דהשתא סוף יום שביעי בע\"ש כיון דאינו סמוך לרגל אין סופו עולה לו לתחלת ל' ולא הותר לו לספר ולכבס לכך קאמר תלמודא דהך סברא ליתא אלא קושטא דסברא דאפי' חכמים מודים בהא לאבא שאול והשתא ניחא דכתב רבינו תחלה דין חל יום ט' בערב הרגל דיום ז' עולה לו לכאן ולכאן ואח\"כ כתב וכן אם חל יום ח' כו' בדרך לא זו אף זו משום דאיכא סברא איפכא לומר דדוקא כשחל יום שבעה בערב הרגל הוא דעולה לכאן ולכאן אבל לא כשחל יום שמנה בשבת שבערב הרגל להכי קאמר דליתא אלא אף כשחל יום שמנה בשבת שבערב הרגל עולה לו לכאן ולכאן וכיוצא בזה כתבתי בסייעתא דשמיא ליישב דברי רבינו בח\"מ ריש סימן ס\"ב וע\"ש אחר שכתבתי זה נזכרתי שכבר הקשה ב\"י קושיא זו בא\"ח סימן תקמ\"ח ולא השיב כלום ע\"ש:","\u0003ואם חל יום ששי או יום ראשון שלו ערב הרגל מותר לו לספר ולכבס וכו'\u0004 והרמב\"ם כתב שאינו מותר לא לגלח ולא לרחוץ וכו' שם אמר רב הונא הכל מודים כשחל שלישי שלו להיות ערב הרגל שאסור ברחיצה עד הערב ומפרש רבינו במ\"ש בהגהות סמ\"ק דהא דנקט יום שלישי דוקא שלישי קאמר משום דלתנא דמתני' אין הרגל מבטל האבילות אלא בקובר מתו שלשה ימים קודם הרגל הואיל ועיקר האבילות אינו אלא ג' ימים וקאמר רב הונא דלדידיה ג' שלימים בעינן עד הלילה ופירש\"י ואז רוחץ כל גופו בצונן או פניו ידיו ורגליו בחמין או בחש\"מ כל גופו בחמין אבל בערב קודם הלילה אסור כיון דאפשר לו לרחוץ בליל י\"ט אבל כבוס דאסור בי\"ט שרי ביום ואסור ללבשו עד הלילה שכך פירש הראב\"ד ולפ\"ז למאי דקי\"ל כחכמים דאפילו שעה אחת קודם הרגל מבטל ממנו גזירת שבעה אין חילוק בין יום שלישי ליום ראשון או יום ששי דבכל ענין אינו רוחץ עד הלילה ומותר לכבס כסותו ביום וללבשו בלילה וכך כתב הרי\"ף והרא\"ש לשם וכן כתב הרמב\"ם פ\"י דאבל אלא דהרי\"ף והרא\"ש לא כתבו הלכך אין מותר לרחוץ עד דעל רגל ולא הזכיר כבוס כלל אלא רחיצה ועד דעל רגל משמע ודאי דלא שרי רחיצה עד הלילה והרמב\"ם גם הוא כתב וז\"ל ואינו מותר לרחוץ ולסוך ולעשות דבר עד שיכנס י\"ט אלא דאינו מתיר אלא בלילה ומיהו מפורש בדבריו דאוסר גם הכבוס כל היום כמו רחיצה וז\"ש רבינו דריב\"א חולק אסברא ראשונה בתרתי חדא דכבוס אסור ביום כמו רחיצה אידך דשניהם מותרים סמוך לחשיכה וא\"צ להמתין עד הלילה והרמב\"ם אינו חולק אלא בחדא דאוסר כבוס ביום כמו רחיצה ומודה לסברא הראשונה דאסור לרחוץ עד הלילה מיהו עכשיו נהגו היתר ברחיצה לאחר מנחה וכ\"כ בהגהות מיימוני פ\"י בשם מהר\"ם וכמה גדולים והביאו ב\"י בא\"ח סימן תקמ\"ח וכן כתב מהרא\"י בת\"ה סימן רפ\"ז דנוהגים היתר לרחוץ בחמין סמוך לערב אפילו לא נהג אבילות אלא שעה אחת לפני הרגל וכתב עוד שלפי זה כשחל שבת בערב הרגל ומת לו מת בע\"ש מותר נמי לרחוץ בחמין בע\"ש ע\"ש וכ\"כ בהגהות ש\"ע כאן דאפילו בחל יום א' דאבילות בערב הרגל מותר לרחוץ אחר תפלת המנחה סמוך לחשיכה וכן נוהגין אך קשה ממ\"ש בהגהות ש\"ע בא\"ח סימן תקמ\"ח דלדידן דנוהגין איסור רחיצה כל ל' אסור לרחוץ דהא הרגל לא בטל ממנו אלא גזירת ז' וה\"ה לענין כבוס במקום דנוהגין איסור כיבוס כל שלשים עכ\"ל וא\"כ דבריו סותרין זא\"ז וצ\"ל דמ\"ש הרב בהגה\"ה בא\"ח ולדידן דנוהגין איסור רחיצה וכו' ה\"ק דלפ\"ז כשחל אחד מימי האבילות חוץ מהשביעי בערב הרגל לדידן אסור הוא לרחוץ דהא לא בטל ממנו רק גזירת ז' וה\"ה לכבוס וכו' כלומר כך הוא ראוי להורות לדידן אבל כאן כתב דאע\"ג דכך היה ראוי להורות לדידן מ\"מ המנהג אינו כן אלא אפילו לא נהג אבילות אלא שעה אחת לפני הרגל רוחצין אחר המנחה סמוך לחשיכה וצ\"ל דמתחלה לא קבלו עליהם לנהוג איסור רחיצה וכבוס כל ל' אלא כשאין שם הפסקה של רגל אבל כשהרגל מפסיק אוקמוה אדינא דתלמודא דרוחצין לערב אחר המנחה סמוך לחשיכה וא\"כ יהיה דעת הרב בהגהות ש\"ע כדעת כל האחרונים והכי נקטינן עוד כתב לשם ב\"י על מ\"ש לשם רבינו וכן כאן דבחל יום ראשון או ששי בערב הרגל דמותר לספר ולכבס דהוא דבר תמוה דהא כתב להדיא דאינו מותר לגלח אלא בחל יום שביעי ערב הרגל מטעם דיום שביעי עולה לכאן ולכאן אבל יום ששי לא והיה נראה בעיני ב\"י דוחק לומר שהוא ט\"ס ורצה ליישבו בלי טעות ולא התיישב לו והניחו בצ\"ע אבל אין ספק שט\"ס הוא כי כן נמצא בספרים ישנים מותר לכבס וכן מ\"ש בדברי רבינו בשם הרמב\"ם שאינו מותר לא לגלח ולא לרחוץ וכו' עד שנכנס י\"ט הוא ט\"ס אלא צריך להיות שאינו מותר לא לרחוץ וכו' והוא דבר פשוט ומפרש כך למי שמעיין בספר הרמב\"ם עצמו וכתב הרב בהגהות ש\"ע דאף על פי דלא נהגו לספר בחל שביעי בערב הרגל אלא סמוך לחשיכה מכל מקום בערב פסח עדיף טפי לגלח קודם חצות הואיל ואחרים אסורים לגלח אחר חצות אם כן אנוס הוא קצת כיון שאינו יכול לגלח אחר חצות לכך מותר לו לגלח קודם חצות ולמד כך ממ\"ש הר\"י מינץ בתשובה סימן ד' ומה שכתב ב\"י בשם תשב\"ץ דבחל יום ששי בע\"פ דאין אבילות נוהג בו הוא תמוה דהא אפילו שעה אחת מפסיק ואפי' אינו ע\"פ ואפשר דבע\"פ התיר טפי לכבס ולרחוץ אפילו ביום קודם מנחה והא דקאמר יום ששי לאו דוקא דאפילו ביום ראשון היה מתיר אלא דמעשה שהיה כך היה ובזה מיושב מה שהיה קשה לבית יוסף ועוד כתב בתשב\"ץ על אבל שחל יום שלישי בערב יום כפור ונצטווה לרחוץ אבל לא ללבוש לבנים דוקא ביום שלישי מותר פחות מכאן לא והקשה בית יוסף דאין לזה סמך ולא ראיה ובאורח חיים סימן תר\"ו ביאר דבריו דקשיא ליה מפני מה התיר הרחיצה תוך שבעה משום מנהג שנהגו לרחוץ בערב יום כפור וכבר התבאר בס\"ד לשם כל הצורך ע\"ש: והא דרגל מבטל גזירת שלשים וכו' איכא לתמוה דכאן משמע דס\"ל כספר המצות ולעיל בסימן ש\"ץ ס\"ה פסק בסתם דלא כספר המצות ויש לומר דלעיל סתם דבריו לחומרא ע\"פ דעת הרבה פוסקים שחולקים על ס\"ה וכאן לא כתב אלא מיהו איכא ס\"ה דמיקל בזה ועל כן היכא דנהוג כמותו לקולא לא ישנו מנהגם:","\u0003ר\"ה ויום הכפורים חשיבי כרגלים וכו'\u0004 ויום טוב שני של עצרת עולה למנין י\"ו כיון שאנו בקיאין בקביעותא דירחא וכו' לכאורה משמע דבראש השנה אין יום שני עולה למנין כיון דלאו משום מנהג הוא נקבע והכי נמי משמע קצת מלשון הרמב\"ם הביאו בשלחן ערוך אצל המקומות שעושין ב' ימים טובים מונה השבעה מיום טוב שני האחרון אף על פי שאינו נוהג בו אבילות הואיל ומדבריהם הוא עולה לו מן המנין מדכתב המקומות וכו' משמע דדוקא בשני ימים טובים של גליות שהוא משתנה לפי מנהג המקומות אבל ראש השנה דעושין אותו שני ימים בכל מקום אינו מונה אלא מיום שלאחריו דכיומא אריכתא נינהו וגדולה מזו כתב רבינו בשם בה\"ג דאפי' בקובר מתו קודם ראש השנה לא נמנה יום שני דראש השנה ליום בפני עצמו למנין ל' מטעמא דהני תרתי יומא דראש השנה כיומא אריכתא דמיין וכן כתב הר\"ר ירוחם להדיא ומביאו ב\"י וכתב דדבריו הם לדעת בה\"ג ולפי זה כל שכן בקובר מתו ביום ראשון של ראש השנה ונקבר בו ביום דאין מונין שבעה אלא מג' בתשרי ואילך מיהו נראה עיקר דמה שכתב רבינו גבי יום טוב של עצרת דיום שני עולה למנין משום דאנו בקיאין בקביעותא דירחא וכו' לא כתב כך אלא בקובר מתו לפני עצרת דשעה אחת לפני עצרת חשובה כז' ועצרת נמי חשוב כז' התם הוא דאי לאו דבקיאין בקיבועא דירחא לא היה לנו להקל עוד קולא ולמנות יום ב' דעצרת בפני עצמו דדי לנו קולא דב' ימים של עצרת חשובים כז' ולכן בר\"ה דלאו משום מנהג עושין ב' ימים לא היה נחשב בפני עצמו אם היינו צריכין לחושבו אלא דאין אנו צריכין לחושבו כיון דאיכא ז' ימים בין ר\"ה ליה\"כ ויה\"כ מבטל ממנו גזירת ל' אבל בקובר מתו ברגל דלא מקילי' אלא קולא זו דמתחילין למנות מיום שני הואיל שהוא מדבריהם ודאי דאף בר\"ה דהוי מדבריהם מונין מיום שני גם מ\"ש הרמב\"ם המקומות וכו' איכא למימר דהרמב\"ם אזיל לטעמיה דמחלק בין ב' י\"ט של גליות לב' י\"ט דר\"ה להיכא דמת לו מת בי\"ט שני דנהוג ביה אבילות בי\"ט שני של גליות ובי\"ט של ר\"ה אינו נוהג דכיומא אריכתא דמיין אבל להרמב\"ן והגאונים דאין חילוק ואף בי\"ט שני דר\"ה נהוג אבילות כיון שהוא מדבריהם כמ\"ש בסוף סימן זה השתא איכא למימר דאף לדידן דנהגינן דלא נהיג אבילות בשום י\"ט מכל מקום לענין התחלת מנין ז' בכל ענין מונין מיום שני בין בי\"ט של גליות בין בי\"ט של ר\"ה הואיל וזה וזה מדבריהם הוא. ועוד נראה דאף להרמב\"ם אין חילוק בין י\"ט ב' של גליות לי\"ט שני של ר\"ה אלא להיכא שמת לו מת בי\"ט שני דאין אבילות בר\"ה כיון ששניהם יום ארוך ובשל גליות איכא אבילות אבל שיהא עולה למנין ז' מודה דעולה אף י\"ט שני של ר\"ה ותדע שהרי בקובר מתו בתוך הרגל דאינו נוהג אבילות כל הרגל ואעפ\"כ כתב הרמב\"ם גופיה די\"ט שני עולה לו למנין ז' ומה דכתב הרמב\"ם המקומות וכו' ר\"ל כל המקומות שעושין ב' י\"ט אפילו בא\"י כגון ר\"ה ולהוציא ממקצת גאונים דבא\"י אין עושין רק יום א' אף בר\"ה והכי משמע להדיא בהגהות מיימוני דעולה י\"ט ב' של ר\"ה למנין שבעה אלא דבמהרי\"ל במסכת שמחות כתב דלא היה מורה להקל בי\"ט של ר\"ה אפשר דלא אמר בה כלל הוראה לא לאיסור ולא להיתר ולפעד\"נ דבר פשוט דאין חילוק ואפילו בי\"ט ב' של ר\"ה עולה ואפילו היה י\"ט שני האחרון בשבת כגון בי\"ט של גליות אפ\"ה עולה דלא גרע משמע שמועה קרובה בשבת דעולה ע\"ל במ\"ש סוף סימן ת' והארכתי בכל זה בתשובה בס\"ד בראיות וטעמים וכאן מספיק הקיצור:"]],["\u0010c0\u0011\u0010y0\u0011שבת אינו מפסיק האבילות כמו הרגל שא\"א לשבעת הימים בלא שבת ואם היה מפסיק א\"כ לא יהיו לעולם ז' ימים \u0010c1\u0011ועולה שהרי קצת דיני אבילות נוהגין בו \u0010y1\u0011דקי\"ל פח\"ז חובה נת\"ר רשות פי' פריעת הראש שמגלהו מעטיפתו וחזרת קרע לאחוריו וזקיפת מטה חובה שלא לנהוג בהן אבילות בשבת לפי שהן של פרהסיא אבל נעילת סנדל ותשמיש המטה ורחיצה בחמין שהן דברים שבצינעא רשות ויכול לנהוג בהן אבילות \u0010c2\u0011הלכך חייב לנהוג בהן כמו בחול כיון שאינו נראה כאבילות ואם יש לו מנעל ברגליו אף פריעת הראש רשות שמנעלים מוכיחין עליו \u0010y2\u0011והרמב\"ן כתב תשמיש המטה ורחיצה שהם דברים שבצינעא ממש חייב לנהוג בהם אבילות כפיית המטה וחזרת הקרע לאחוריו שהם דברים שבפרהסיא אסור בהן אלא חייב בזקיפת המטה ובחזרת קרע לאחוריו \u0010y3\u0011כסוי הראש וחליצת סנדל חייב לנהוג בהן אבילות בתוך ביתו באו אחרים להראות לו פנים פריעת הראש חובה שלא לנהוג ונעילת הסנדל רשות ואם היו סנדליו ברגליו אף פריעת הראש רשות ע\"כ \u0010y4\u0011וי\"א דאף חזרת קרע לאחוריו אינו חובה אלא כשהוא בגלוי אבל כשמטייל בתוך ביתו אין צריך להחזירו לאחוריו \u0010y5\u0011וא\"א ז\"ל כתב דברים שבצינעא כגון כסוי הראש ורחיצה בחמין ותשמיש המטה וכיוצא בהן נוהגין \u0010y6\u0011והאידנא שאין רגיל לילך יחף הוי נעילת הסנדל חובה \u0010y7\u0011ותלמוד תורה יראה דהוי דברים שבצינעא אבל לחזור הפרשה כיון שחייב אדם להשלים פרשיותיו עם הצבור הוי כקורא את שמע ומותר ואם קראו את האבל לעלות לתורה צריך לעלות שאם היה נמנע הוי דבר של פרהסיא ושמעתי שר\"ת היו קורין אותו בכל פעם שלישי ואירע בו אבילות ולא קראו החזן ועלה מעצמו ואמר כיון שהורגל לקרות שלישי בכל שבת הרואה שאינו עולה אומר שבשביל אבילות הוא נמנע והוי דברים של פרהסיא ע\"כ \u0010y8\u0011ושאלת שלום תלוי במנהג כדפרישית בדיני שאלת שלום \u0010y9\u0011זוקפין המטות בערב שבת מהמנחה ולמעלה ואעפ\"כ לא ישב עליה עד שתחשך ולמוצ\"ש חוזר וכופה אפי' לא נשאר לו אלא יום אחד:",["\u0003שבת אינו מפסיק האבילות כרגל וכו'\u0004 ועולה משנה בפרק אלו מגלחין (מועד קטן דף יט.) שבת עולה ואינה מפסקת ומה שנתן טעם למה אינו מפסיק מפני שא\"א לז' הימים בלא שבת וכו' כ\"כ הרמב\"ן בת\"ה והכי איתא בירושלמי","ומ\"ש דקי\"ל פח\"ז חובה נת\"ר רשות מימרא דשמואל פרק אלו מגלחין (מועד קטן כד.) ואיתמר עלה ורב אמר אף פריעת הראש רשות ושמואל מ\"ש נעילת הסנדל דרשות דלאו כ\"ע עבידי דסיימי מסאנייהו פריעת הראש נמי לאו כ\"ע עבידי דמגלי רישייהו שמואל לטעמיה דאמר כל עטיפה שאינה כעטיפת ישמעאלים אינה עטיפה כלומר וכ\"ע לא נהגי בעטיפה זו אלא אבילים. ומ\"ש הילכך חייב לנהוג בהן כמו בחול כיון שאינו נראה כאבילות כ\"כ הרי\"ף והרא\"ש ז\"ל שם והרמב\"ן בת\"ה וטעמא מדאמרינן התם אביי אשכחיה לרב יוסף דפריס ליה סודרא ארישיה ואזיל ואתי בביתיה א\"ל לא ס\"ל למר אין אבילות בשבת א\"ל הכי א\"ר יוחנן דברים שבצינעא נוהג וזה לשון המרדכי עטיפת הראש דבר של צינעא הוא ולא כעטיפת ישמעאלים אלא כיסוי הראש לבד כדאביי דאשכחיה לרב יוסף דפריס סודרא ארישא וכו' וחליצת סנדל בתוך ביתו לא דבר של צינעא ממש הוא משום דאיכא אינשי טובא דלא מסיימי מסאני בבית או משום מיחוש או משום הנאה הלכך רשות הוא עכ\"ל וכתוב בהגה\"מ בפי\"ב בשם ס\"מ דחזרת קרע בשבת אינו חובה אם יש לו מנעלים ברגליו כדאמר ר\"י לענין פריעת הראש :","ומ\"ש רבינו בשם הרמב\"ן בת\"ה כתב אהא דאמר רבי יוחנן אבל יש לו מנעלים ברגליו מנעליו מוכיחים עליו פירש הרי\"ף ואפי' פריעת הראש רשות ונראה שהוא סובר שחזרת קרע לעולם חוב וכן זקיפת המטה ואחר כך כתב הא דגרסינן התם אמר רבא מטייל באנקלי בתוך ביתו וכתב עליו פר\"ח אנקלי כעין מצנפת וכולי ורש\"י מפרש אנקלי בגד קרוע שלו וכן נראה שהוא מלבוש וכו' והדברים מטין כדברי רש\"י שהאנקלי קרוע הוא ומהלך בו בצינעא וקרעו לפניו וכשבאין אחרים להראות לו פנים לובש בגד שלם עליו וכתב עוד לדעת הרי\"ף הא דרבי יוחנן אפריעת הראש קיימא ואליבא דשמואל אבל חזרת קרע חובה וכן נראה מדבריו שאפילו בביתו בצינעא חובה ואינה מכלל דברים שבצינעא שאפילו בחול אינו מגזירת ז' אלא מחליף ומחזיר אם ירצה והיינו דתניא ובשבת קרעו לאחוריו ובתשובות הגאונים מצינו דעת אחרת דאפילו פח\"ז בפרהסיא חובה בצינעא נוהג בכולן וכדעת רבינו בעל הלכות ז\"ל נראה ונכון מכולם הילכך דברים שבצינעא ממש תשמיש רחיצה וסיכה חייב לנהוג בהם אבילות וכולי עד אף פריעת הראש רשות וכן העיקר עכ\"ל. ומ\"ש דדברים שבצינעא ממש נוהג בהם אבילות פשוט דהיינו מדא\"ר יוחנן דברים שבצינעא נוהג. ומ\"ש דברים שפרהסיא כגון כפיית המטה וחזרת הקרע לאחוריו אסור בהן כלומר ואפילו בצינעא וכמו שכתב שהוא דעת הרי\"ף.","\u0003ומ\"ש כיסוי הראש וחליצת הסנדל חייב לנהוג בהם אבילות בתוך ביתו וכו'\u0004 נראה דהיינו ממה שכתבתי בסמוך מדאשכחיה אביי לרב יוסף דפריס סודרא בביתיה ויהיב טעמא משום דא\"ר יוחנן דברים שבצינעא נוהג ומשמע ליה להרמב\"ן דדין נעילת סנדל כדין כיסוי הראש:","ומ\"ש רבינו וי\"א דאף חזרת קרע לאחוריו אינו חובה אלא שהוא בגלוי וכולי נראה שזהו לפי פירש\"י שכתבתי בסמוך על ההיא דאמר רבא מטייל באנקלי בתוך ביתו:","ומ\"ש בשם הרא\"ש דברים שבצינעא כגון כיסוי הראש ורחיצה בחמין ותשמיש המטה וכיוצא בהן נוהגין כן כתב ג\"כ הרי\"ף ומבואר בדבריהם דדוקא בצינעא נוהג בהם אבל בפרהסיא אסור בעטיפת הראש וכההיא דאשכחיה אביי לרב יוסף דפריס סודרא ארישיה בביתיה וכו' וכן נראה שהוא דעת הרמב\"ם שכתב בפ\"י אין אבילות בשבת אלא בדברים שבצינעא כגון עטיפת הראש ותשמיש המטה ורחיצת ראשו בחמין אבל דברים שבגלוי אינו נוהג בהם אבילות אלא לובש מנעליו וזוקף את המטה ונותן שלום לכל אדם ואם יש לו בגד מחליף ולא ילבש בגד קרוע בשבת אפילו על אביו ואמו ואם אין לו להחליף מחזיר את הקרע לאחוריו עכ\"ל ונ\"ל דהא דכתב דנוהג דברים שבצינעא כגון עטיפת הראש היינו לומר בצינעא דוקא נוהג וכעובדא דרב יוסף דמשמע דלא הוה פריס סודרא ארישא אלא בגו ביתיה דוקא ולא בפני רבים אלא דא\"כ קשה דהול\"ל גם בנעילת הסנדל שינהוג בצינעא דמ\"ש מעטיפת הראש ושמא י\"ל דכיון דלא אשכחן בגמרא מאן דחלץ מנעליו בצינעא לית לן למימר שיחלוץ מנעליו אפי' בצינעא ויותר נראה לומר דאף בפני רבים קאמר שיעטוף ראשו וקרי ליה דברים שבצינעא משום דכיון דיש לו מנעלים ברגליו וכמ\"ש לובש מנעלין מנעליו מוכיחין עליו וכדרבי יוחנן ועי\"ל שטעמו משום דפסק כרב דאמר אף פריעת הראש רשות וא\"כ חייב לנהוג בה כמו בחול כיון שאינו נראה כאבילות ואע\"ג דמשמע בגמרא דטעמא דרב משום דלית ליה כשמואל דאמר כל עטיפה שאינה כעטיפת ישמעאלים אינה עטיפה והוא ז\"ל פסק בפ\"ה כשמואל דמצריך עטיפת ישמעאלים איכא למימר דרב נמי מצריך עטיפת ישמעאלים וטעמא דאמר פריעת הראש רשות משום דקסבר איכא אינשי דמכסו פומייהו בלא אבילות אבל קשה דמאי כתב דלובש מנעליו הא אמרינן דנעילת הסנדל רשות ואם כן חייב הוא לחלוץ ואפשר דמשום דבהאי זימנא אין רגילות לילך אף יחף פסק כן:","ומ\"ש רבינו והאידנא שאין רגילות לילך יחף הוה נעילת הסנדל חובה כ\"כ שם הרא\"ש וז\"ל והוא פשוט מדאמרינן לאו כ\"ע עבידי דסיימי מסאנייהו.","\u0003ומ\"ש ות\"ת יראה דהוי דברים שבצינעא וכו'\u0004 עד והוי דברים של פרהסיא הכל מדברי הרא\"ש שם והגה\"מ בפ\"ד כתבו לענין ת\"ת בשם הר\"מ כדברי ר\"ת אמנם יותר טוב היה לומר לו מקודם לצאת מב\"ה והר\"י א\"ז פסק לחיובא והתיר לקרותו וכתב המרדכי יש אוסרים ת\"ת בשבת דדמי למילי דצינעא אבל ר\"י היה מתיר ת\"ת בשבת שהוא משמחת את הלב והוא צריך לשמח עצמו בשבת עכ\"ל. ולענין הלכה נקטינן כר\"מ והר\"מ והרא\"ש דרוב מנין ורוב בנין הם :","\u0003ומ\"ש רבינו ושאילת שלום תלוי במנהג כדפרישית בדיני שאלת שלום הוא בסימן שפ\"ה:\u0004 ","\u0003זוקפין המטות בע\"ש מן המנחה ולמעלה וכו'\u0004 עד סוף הסימן בס\"פ אלו מגלחין (מועד קטן כז.) וכתב נ\"י נראה דמנחה קטנה קאמר והגה\"מ כתבו בפ\"י בשם הר\"מ אבל שחל ל' שלו בשבת מותר לו לרחוץ ע\"ש שהוא יום כ\"ט שלו לכבוד השבת ע\"כ ודברים אלו לא ניתנו ליכתב אלא לפי מנהגם שהיו נוהגים שלא לרחוץ כל ל' יום כמבואר בדבריו שם אבל לדידן לא מיתסר לרחוץ אלא תוך ז' כמו שהוא הדין :"],["\u0003שבת אינו מפסיק וכו'\u0004 משנה פרק אלו מגלחין (מועד קטן דף י\"ט) ומ\"ש שאי אפשר לשבת וכו' פי' קשיא ליה כיון דקי\"ל כמאן דאמר אין אבילות בשבת אמאי אין דינו כמו הרגל ויהא ג\"כ מפסיק ותירץ משום דאין שבעה בלא שבת וכ\"כ הרמב\"ן בסת\"ה [דף ע\"ג ע\"ג] כלומר כיון דילפינן מקרא והפכתם חגיכם לאבל דאבילות שבעה כדלעיל ריש סימן שע\"ה אי איתא דשבת מפסיק לא אשכחן כלל אבילות שבעה וקרא למאי אתא ואיכא למידק הלא אפילו את\"ל דשבת מפסיק אשכחן ז' ימים כגון שמת ביום א' ונקבר בו ביום דיום שביעי שלו חל בשבת אי נמי שמע שמועה קרובה בשבת דיום שביעי שלו חל בערב שבת וי\"ל דהיקישא דמה חג שבעה אף אבל שבעה מקרא מלא דיבר הכתוב דבכל אבל איכא שבעה.","\u0003ומ\"ש ועולה שהרי קצת דיני אבילות נוהגים בו כו'\u0004 פי' קשיא ליה אכתי כיון דאין אבילות בשבת למה הוא עולה ותירץ שהרי קצת וכו':","\u0003ומ\"ש הלכך חייב לנהוג בהן כמו בחול וכו'\u0004 קשיא לי לישנא כיון דבתחלה קאמר שהן רשות היאך נמשך ממה שהן רשות דחייב לנהוג בהן אבילות ואפשר דה\"ק דבעלמא בלא אבילות פח\"ז חובה בשבת נת\"ר רשות הלכך כשהוא אבל חייב לנהוג בהן דכיון דדברים שבצינעא נוהג בשבת א\"כ חייב לנהוג בהן אבילות בשבת ומש\"ה עולה וכ\"כ התוס' פרק אלו מגלחין (מועד קטן דף כ\"ד) בד\"ה ושמואל לטעמיה דיש מפרשים כך ואע\"ג דהתוס' כתבו אח\"כ דא\"צ לפרש כך מ\"מ רבינו ס\"ל דפירוש י\"מ הוא עיקר והכי משמע להדיא מלשון הרא\"ש שכתב נת\"ר רשות יכול לנהוג אותן ואין בהם משום אבילות הלכך חייב לנהוג אותן כמו בחול כיון שאינו נראה כאבילות עכ\"ל וכך צריך להגיה בלשון רבי' רשות ויכול לנהוג בהן [ואין בהן משום] אבילות וכו' ודו\"ק כתב בש\"ע גררתו חיה או הרגוהו לסטים ובשבת נתייאשו מלבקשו כיון דדברים שבצינעא נוהג בשבת עולה לו ליום אחד עכ\"ל וה\"א בירושלמי הביאו המרדכי במ\"ק והוא דעת הסמ\"ג בשם בה\"ג דשבת עולה אפילו בתחלת המנין אע\"פ שלא נהג אבילות שעה אחת לפני השבת וכן כתב במרדכי בשם תוספות ריב\"ם ע\"ש וכ\"כ הסמ\"ק וז\"ל שמע שמועה קרובה בשבת שבת עולה ליום א' ולמחר קורע ונוהג ששה ימי אבילות וכתב בהגה\"ה והו\"ל יום ששי שביעי שלו ויקום מן האבילות בשחר ולא ינהוג אפילו דברים שבצינעא בשבת שלאחריו כלל ומיהו בתוס' מורי רבינו יחיאל ז\"ל פי' דשבת אינו עולה בתחלת המנין וא\"כ יתחיל למנות ז' ימי אבילות מן הראשון והו\"ל שבת יום שביעי לאבילות וינהג דברים שבצינעא במקצת היום וצ\"ע עכ\"ל ההגה\"ה ומביאו רבינו בסימן ת\"ב וקשה דמ\"ש מגררתו חיה וכו' וי\"ל דס\"ל לרבינו יחיאל דשאני ייאוש דבשעת הייאוש הוה כשעת קבורה משא\"כ בשמועה רחוקה ודוחק ולענין הלכה אע\"פ שמדברי מהרי\"ק בשורש נ\"ג נראה דהכריע כרבי' יחיאל כיון שהוא בתראה ורבינו פרץ בעל הגה\"ת הסמ\"ק הביא דבריו מכל מקום כיון דרבים נינהו דמקילין בעל ה\"ג והסמ\"ק והסמ\"ג והמרדכי בשם ריב\"ם וכך פסק בש\"ע סימן ת\"ב סעיף ז' הכי נקטינן ותו דהלכה כדברי המיקל באבל:"]],["\u0010c0\u0011\u0010y0\u0011אין מניחין המטה ברחוב בחול המועד \u0010y1\u0011ולא קורעין בו אלא קרובים של מת הראוים להתאבל עליו פי' לאפוקי מי שרוצה לקרוע בשביל כבודו של מת \u0010y2\u0011אבל מי שצריכין לקרוע עליו בשביל חכמתו או שהוא אדם כשר או רבו או עומד עליו בשעת יציאת נשמה קורעין על כל אחד כדינו במועד \u0010y3\u0011כדפרישית לעיל בדין קריעה \u0010y4\u0011ואין חולצין כתף במועד ואין מברין בו אלא קרוביו של מת \u0010y5\u0011אבל הקרובים מיהא מברין \u0010y6\u0011ואף כשמברין אין מברין אלא על מטות זקופות \u0010c1\u0011ואין מוליכין לבית האבל לא בטבלא ולא באסקטלא לא בקנון ולא בסלים ואין בו ברכת אבילים שאומרים ברחבה אבל עומדין בשורה ומנחמין ופוטרין את הרבים נשים בח\"ה מענות פירוש שכולם עונות כאחת אבל לא מטפחות להכות כף אל כף בר\"ח חנוכה ופורים מענות ומטפחות אבל לא מקוננות שתהא אחת מדברת ואחרות עונות אחריה נקבר המת לא מענות ולא מטפחות \u0010y7\u0011והני מילי לאיניש דעלמא אבל לתלמיד חכם בין בח\"ה בין בר\"ח חנוכה ופורים מענות ומקוננות כדרכן בחול והני מילי בפניו אבל שלא בפניו לא \u0010y8\u0011כתוב בתשובת הגאונים וששאלתם היכא שמספידין בר\"ח מהו שיאמרו צידוק הדין כך שנינו נשים במועד מענות אבל לא מטפחות הילכך צידוק הדין אם עונין כולן כאחד מותר ואם אחד מדבר וכולן עונין אחריו אסור וכתב רב האי מנהגינו לומר קדיש על המת ביום טוב ולומר כן תתכלא חרבא \u0010c2\u0011ולשאול בו שלום כחול \u0010y9\u0011לשון א\"א הרא\"ש ז\"ל ועל צה\"ד לאומרו בר\"ח חנוכה ופורים נחלקו בו חכמי אשכנז חכמי גרמיז\"א אומרים דרך הילוך וחכמי מגנצ\"א א\"א אותו אלא על חכם גדול וכן השיב רבינו משולם בן רבי משה שנינו אין מניחין המטה ברחוב שלא להרגיל ההספד ומתוך צידוק הדין נמי ירגיל את ההספד וכיון שאין צידוק הדין אין קדיש ודי לאדם מופלא שמספידין בחול המועד שאומרים צידוק הדין וקדיש ובחילוף מנהגים שבין בני בבל ובני א\"י כתב שלדברי שניהם אין אומרים צידוק הדין בחול המועד והרי\"ץ גיאות כתב אנו מנהגינו מימות זקנים הראשונים שלא לומר צידוק הדין אחר המת בר\"ח חנוכה ופורים דלא עדיף צ\"ה דהדיוט מצידוק הדין דמשה רבינו דמסלקינן ליה בשבת שחל להיות במועד ואפי' בר\"ח וחנוכה שחלו להיות בשבת דהללו יומי שמחה נינהו דכתיב וביום שמחתכם ובמועדיכם ובראשי חדשיכם ובכל חדא אומרים בו הלל זה היום עשה ה' נגילה ונשמחה בו לפיכך מבטלין בו צידוק הדין ותלמידי רש\"י כתבו בשמו שאומרים על המת צידוק הדין וקדיש בחולו של מועד שאין זה הספד וחילול י\"ט אלא הודאה וקבלת דין שמים ע\"כ וכ\"כ הרמב\"ם שאומרים בחולו של מועד צידוק הדין וקדיש כדרכן וכן בי\"ט שני אבל בי\"ט ראשון כיון שאין מתעסקין במת אין אומרים כלום \u0010c3\u0011\u0010y10\u0011כתב בשאלתות שאם מת לו מת בפורים אסור להספיד ולנהוג בו אבילות ואם מת קודם פורים ופגע בו האבילות בתוך ז' בטלה ממנו גזירת ז' ודוקא פורים אבל חנוכה ור\"ח אין מבטלין האבילות אלא שאין מספידין בהם \u0010y11\u0011והרמב\"ם כתב שנוהגין בפורים כל דין אבילות \u0010y12\u0011והר\"מ מרוטנבורג כתב שגם פורים אין מבטל האבילות ומ\"מ אין אבילות נוהג בו לא בי\"ד ולא בט\"ו אלא דברים שבצינעא נוהגין ולאחר שיתפללו בבית האבל בלילה ילך לב\"ה לשמוע מקרא מגילה וחייב לשלוח מנות אע\"פ שאינו מתאבל בהן עולין לו ומשלים אבילתו אח\"כ \u0010y13\u0011וי\"א שאינו הולך לבית הכנסת ואדוני אבי הרא\"ש ז\"ל כתב כדברי הר\"מ מרוטנבור\"ק:",["אין מניחין המטה ברחוב בחה\"מ משנה שם [כח:] ויהיב במתני' טעמא שלא להרגיל את ההספד וכתב נ\"י ובחש\"מ אסור להרגיל ההספד אלא לכבוד ת\"ח לפיכך אין מוליכין המת לבית הקברות כשהוא מת במועד עד שיהיה כל הקבר מתוקן ומזומן:","\u0003ומ\"ש ולא קורעין בו אלא קרוביו של מת ג\"ז משנה שם:\u0004 ","\u0003ומ\"ש אבל מי שצריך לקרוע עליו בשביל חכמתו או שהוא אדם כשר וכו'\u0004 שם בגמרא:","\u0003ומ\"ש כדפרישית לעיל בדין קריעה סי' ש\"מ.\u0004 כתב רבינו ירוחם שמועה קרובה ששמעה בח\"ה קורע וכ\"כ הראב\"ד ובה\"ג כתב דמי ששמע שמועה קרובה ברגל דאסור לקרוע ואחר הרגל קורע ונוהג אבילות. וראשון נראה עיקר וכ\"כ ר\"מ עכ\"ל. וגם המרדכי כתב שכן נראה עיקר וכן משמע בירושלמי וכ\"כ הגה\"מ פי\"א והכי נקטינן:","\u0003ומ\"ש ואין חולצין כתף במועד ואין מברין אלא קרוביו של מת ג\"ז שם במשנה:\u0004 ","ומ\"ש אבל קרובים מיהא מברין לאפוקי מהר\"מ מארץ האי וסמ\"ג וסמ\"ק שכתבו דאין עושין הבראה בח\"ה והביאו ראיות מהירושלמי והרא\"ש בפרק אלו מגלחין סתר דבריו וראייתו והעלה שעושין הבראה במועד לקרובים וכ\"כ הרמב\"ן בת\"ה. וכן כתב הרמב\"ם בפי\"א והגהות כתבו שכן נראה להר\"מ וכתב עוד הרמב\"ם אבל בי\"ט אפילו בי\"ט שני אין קורעין ולא חולצין ולא מברין. וכתב עוד מברין הכל על החכם בח\"ה לתוך הרחבה כדרך שמברין את האבילים שהכל אבילים עליו והוא פשוט שם בגמרא כתב סמ\"ג בהל' ח\"ה בחנוכה ור\"ת משמע דלדברי הכל מברין:","\u0003ומ\"ש רבינו ואף כשמברין אין מברין אלא על מטות זקופות וכו'\u0004 עד לא מענות ולא מטפחות שם במשנה וכתב הרמב\"ן אהא דאין מוליכין לבית האבל לא בטבלא וכו' הא נמי במועד קתני ואצ\"ל בחול אלא דקתני דאפילו במועד דלא נהגו אבילות לא יוליך אלא בסלים כתקנתא דרבנן שלא לבייש את מי שאין לו:","\u0003ומ\"ש וה\"מ לאיניש דעלמא אבל לת\"ח בין בח\"ה בין בר\"ח חנוכה ופורים מענות ומקוננות וכו'\u0004 שם [כז:] א\"ר אין מועד בפני ת\"ח וכ\"ש חנוכה ופורים וה\"מ בפניו אבל שלא בפניו לא ומקשינן בגמרא והא רב כהנא ספדיה לרב זביד מנהרדעא בפום נהרא בחולא דמועדא ופרקינן יום שמועה הוה דיום שמועה כבפניו דמי. וכתב הרמב\"ם בפי\"א דאפי' שמועה רחוקה נמי כבפניו דמי ונ\"י כתב י\"מ דיום שמועה דהתם הוה יום מיתה וקבורה דפום נהרא ונהרדעא קרובים הם ובו ביום הגידוהו:","\u0003כתוב בתשובת הגאונים וששאלתם היכא שמספידין בר\"ח מהו שיאמרו צידוק הדין וכו':\u0004 ","\u0003לשון א\"א הרא\"ש ז\"ל ועל צ\"ה לאומרו בר\"ח חנוכה ופורים נחלקו בו חכמי אשכנז וכו'\u0004 בסוף מ\"ק וכתבוהו ג\"כ הגה\"מ בפי\"א וטעם האומרים אותו דרך הילוך נראה שהוא משום דכל שהוא דרך הילוך דמי לעונין שכולן עונים כאחת דשרי במתני'. ומ\"ש בשם הרמב\"ן שאומרין בחש\"מ צידוק הדין וקדיש כדרכן וכן בי\"ט ב' וכו' בת\"ה. והכלבו כתב יש שכתבו שאין אומרים צידוק הדין במועד ולא קדיש שהרי אינו אלא בשביל פסוקי צידוק הדין: כתבו הגה\"מ פי\"א ובהגה\"א פרק אלו מגלחין בשם א\"ז בניסן א\"א כל החדש צידוק הדין אלא דרך הליכה וכן בסיון עד יום טבוח שהוא אסרו חג ורבינו יואל הלוי לא אמרו כל ז' ימים אחר עצרת כ\"א דרך הליכה כי עצרת יש לו תשלומין כל ז' וכתב עוד בהגה\"א שם מעי\"ה עד ר\"ח מרחשון מצדיקין דרך הליכה ושוב אומרים קדיש אחר קבורתו ונהגו שבע\"פ אין מצדיקין עכ\"ל. וכתב בתשב\"ץ שאין אומרים צידוק הדין על המת בט\"ב משום דכתיב קרא עלי מועד ואנו נוהגין לומר צ\"ה בכל אלו הימים ואין אנו נמנעים כי אם בימים טובים :","כתב בשאלתות שאם מת לו מת בפורים אסור להספיד ולנהוג בו אבילות ואם מת קודם פורים ופגע בו אבילות בתוך ז' בטלה ממנו גזירת ז' ודוקא פורים וכו' כ\"כ הרא\"ש בסוף מ\"ק בשם ספר המקצועות והשאלתות נתן טעם מידי דהוה ארגלים ורגלים מפסיקים ואינם עולים מ\"ט דשמחה כתיב בהו (דברים טז) ושמחת בחגך פורים נמי שמחה כתיב ביה (אסתר ט') ועשה אותו יום משתה ושמחה:","ומ\"ש בשם הרמב\"ם הוא בפרק י\"א וז\"ל אין מספידין את המת בחנוכה ופורים ולא בראשי חדשים אבל נוהגים בהם כל דברי אבילות וכ\"כ המרדכי במ\"ק בשם ר\"ג:","ומ\"ש בשם הר\"מ מרוטנבור\"ק בפסקי הרא\"ש סוף מ\"ק כתוב שהקשה הר\"מ על דברי השאלתות והורה שלא יתאבל כלל בפורים דימי משתה קביל עלייהו אבל דברים של צינעא נוהג דלא עדיף משבת ולאחר שהתפללו בבית האבל בליל פורים בערב הורה לו שילך לב\"ה בעת קריאת המגילה דאפילו עבודה דקרבן צבור שדוחה שבת קריאת מגילה דוחה אותה כ\"ש אבילות דרבנן וחייב לשלוח מנות דאבל חייב בכל מצות האמורות בתורה וביום ט\"ו נמי אינו מתאבל כדאמרי' פ\"ב דתענית [יח.] יום י\"ד וט\"ו יומי פוריא דלא למספד בהון ואמר רבא לא נצרכה אלא לאסור את של זה בזה ואע\"ג דלא מתאבל בהו עולין לו מידי דהוה אשבת ואח\"כ משלים אבילותו עכ\"ל. ויש לתמוה עליה מה הוצרך להתיר לאבל לילך לב\"ה בליל פורים אותם שהתפללו בביתו יקראו שם המגילה ונראה שהטעם משום דבב\"ה איכא פרסומי ניסא טפי דברב עם הדרת מלך:","ומ\"ש וי\"א שאינו הולך לב\"ה כ\"כ בתשובת הגה\"מ דשייכי להלכות אבל בשם הרוקח דאין לו לצאת מפתח ביתו אפי' לילך לב\"ה בשעת מגילה אלא יקרא בביתו בין המתפללים שם עמו או ביחיד אבל פורים שחל להיות במוצ\"ש כיון שבלא\"ה הוא בב\"ה התיר לו לישאר שם עד לאחר קריאת המגילה ע\"כ וכתבו עוד הגהות הנזכר מורי רבינו הנהיג שינעול האבל מנעליו וילך לב\"ה לשמוע מגילה וכשיצא מב\"ה יחזור לאבילותו. ורבי' ירוחם כ' נראה דבפורים אינו נוהג אבילות כלל ואפילו תוך ג' ימים מותר לילך לשמוע המגילה ומ\"מ יום ראשון של אבילות נוהג ביום פורים דלא עדיף מי\"ט שני. ולענין הלכה נקטינן דאין פורים מבטל האבילות וכמו שהסכימו הרמב\"ם והר\"מ והרא\"ש ולנהוג בה אבילות נקטינן כדברי הר\"מ והרא\"ש דלגבי הרמב\"ם רבים נינהו ובתראי ומקילים באבל:"],["\u0003אין מניחין וכו'\u0004 משנה בפרק אלו מגלחין (מועד קטן דף כ\"ז). אין מניחין את המטה ברחוב להרגיל את ההספד ולא קורעין וכו' משנה שם [סוף דף כ\"ד ]:","\u0003ואין מוליכין לבית האבל לא בטבלא וכו'\u0004 פי' בכלים חשובים של כסף וזהב שלא יתביישו העניים אלא שמוליכין בסלים ולפיכך אפילו במועד אסור ומכל שכן בחול:","\u0003ולשאול בו טעם בחול כצ\"ל ועיין פירושו בסימן שע\"ו סעיף ד':\u0004 ","\u0003כתב בשאלתות שאם מת לו מת בפורים וכו'\u0004 לשון מהרש\"ל וכתב מהרא\"ק בהגה\"ה וז\"ל אבילות נוהג בר\"ח חנוכה ופורים ובדבר זה שוין רבינו גרשום ומיימוני וספר המצות שלא מנו חכמים ימים שאין אבילות נוהג בהן אלא שבת ורגלים וראש השנה ויה\"כ אבל ר\"ח חנוכה ופורים לא תנן ומהר\"ם הנהיג ברוטנבור\"ק לאבל שינעול מנעליו וילך לבהכ\"נ לשמוע מגילה ערבית ושחרית ובצאתו יחזור לאבילתו אבל הוא חייב לשלוח מנות לב' או לג' בני אדם כי הוא חיוב בכל המצות וכך העיד עליו בספר הפרנס ולא כי\"ד שהעיד עליו שלא לנהוג אבילות בפורים ועוד כתב לשם שכך הורה מהר\"ש הלכה למעשה וכך הורה מהרי\"ל וכן המנהג ואל תשגיח במנהג מהר\"א וכן קבלה שלא לנהוג בזה כמותו ומ\"מ אם טעה אחד ולא נהג בהו א\"צ להשלים אלא עולין לו מן המנין אפי' הזיד בכך דלא אמרינן דאינו עולה אלא כשאינו נוהג אבילות כל ז' אבל במקצת לא איכפת לן כדלעיל בסימן שצ\"ו:"]],["\u0010c0\u0011\u0010y0\u0011השומע שמת לו מת אם הוא בתוך ל' יום \u0010y1\u0011ויום ל' בכלל דינו כיום קבורה לקריעה ולהבראה ולכל דין אבילות \u0010c1\u0011\u0010y2\u0011ואם שמע מיום ל' ואילך אין צריך לנהוג אלא שעה א' \u0010c2\u0011ל\"ש שמע ביום או בלילה \u0010y3\u0011ואפילו שמע על אביו ועל אמו \u0010c3\u0011\u0010y4\u0011וכתב הרמב\"ן ז\"ל והני מילי לענין גזירת ז' אבל לענין גזירת ל' נוהג על אביו ועל אמו בתספורת עד שיגערו בו חביריו ובגיהוץ עד שיגיע הרגל ויגערו בו וכן בשאילת שלום וליכנס לבית המשתה ומונה מיום מיתה ולא מיום שמועה \u0010c4\u0011לפיכך אם באתה לו שמועה על אביו ועל אמו לאחר י\"ב חדש אינו נוהג אלא יום אחד אף בדין ל' וכתב עוד \u0010y5\u0011שהשומע שמועה רחוקה אין צריך לנהוג כל דין אבילות אלא דיו בחליצת מנעל וא\"צ לא עטיפה ולא כפיית המטה ומותר במלאכה רחיצה וסיכה ותשמיש המטה ובת\"ת ואם אין לו מנעלים ברגליו צריך שיכפה מטתו או יעטוף ראשו שצריך שיעשה מעשה שניכר בו שעשה משום אבילות ודאי אם היה עוסק בתורה או במלאכה או שהיה רוחץ וסך ובאתה לו שמועה מפסיק שעה אחת משום אבילות וחוזר למה שבידו אבל אם היה לבוש תפילין אין צריך לחולצן ומ\"מ אינו יוצא ידי אבילות בהפסק זה וצריך שיעשה מעשה שניכר שעושה משום אבילות כגון חליצת מנעל או כפיית המטה ועטיפה ומיהו בחדא סגי \u0010c5\u0011\u0010y6\u0011אין קורעין על שמועה רחוקה אלא על אביו ואמו קורע לעולם כדין קריעה שאינו מתאחה לעולם. \u0010c6\u0011\u0010y7\u0011השומע שמועה בשבת או ברגל ולמ\"ש ורגל נעשית רחוקה אינו נוהג אלא יום אחד \u0010y8\u0011וכתב הרמב\"ן דשבת ורגל אסור בדברים של צינעא. והשומע שמועה רחוקה בשבת או ברגל אינו נוהג אפילו דברים שבצינעא ולמ\"ש ורגל נוהג שעה א' ודיו \u0010y9\u0011וכתב בספר המצות השומע שמועה קרובה בשבת השבת עולה לו ליום א' ולמחר קורע והוה ליה יום ו' שביעי לאבילות וכ\"כ בה\"ג \u0010y10\u0011והר\"ר יחיאל כתב שאין שבת עולה לו בתחלת המנין אלא יתחיל למנות ביום א' והו\"ל יום שבת שביעי לאבילות ונוהג בו דברים שבצינעא:",["\u0003השומע שמת לו מת אם הוא בתוך ל' יום וכו'\u0004 דינו כיום קבורה וכו' בפרק אלו מגלחין (מועד קטן כ.) ת\"ר שמועה קרובה נוהגת שבעה ול' וכתב הרא\"ש ונוהג בה הבראה וכל דין אבילות כיום קבורה. וז\"ל הרמב\"ם בפ\"ז מי שבאת לו שמועה שמת לו קרוב אם בתוך ל' יום הגיעה השמועה אפילו יום ל' עצמו הרי זו שמועה קרובה וחייב לנהוג ז' ימי אבילות מיום שהגיע השמועה וקורע ומונה ל' לאיסור התספורת עם שאר הדברים כללו של דבר יום שמועתו הקרובה כיום הקבורה ע\"כ:","ומ\"ש ויום ל' בכלל כך העלה הרי\"ף פרק אלו מגלחים וסתר דברי האומר דיום ל' הוי שמועה רחוקה וכ\"פ הפוסקים כדברי הרי\"ף והרמב\"ם וכן הכריע הרמב\"ן בת\"ה:","ומ\"ש ואם שמע מיום ל' ואילך א\"צ לנהוג אלא שעה אחת שם פלוגתא דתנאי ואיפסיקא הלכתא כרבי עקיבא דאמר שמועה רחוקה אינו נוהגת אלא יום אחד ואסיקנא התם דמקצת היום ככולו: ומ\"ש ל\"ש אם שמע ביום או בלילה כלומר שאם שמע בלילה ונהג מקצת אבילות בלילה עלה לו כמ\"ש בסימן שצ\"ה:","ומ\"ש ואפי' שמע על אביו ועל אמו כ\"כ הרמב\"ן והרא\"ש מדגרסינן בההוא פירקא (שם) רב חיננא אתיא ליה שמועה דאבוה מבי חוזאי אתא לקמיה דרב חסדא א\"ל שמועה רחוקה אינה נוהגת אלא יום אחד:","\u0003ומ\"ש בשם הרמב\"ן וה\"מ לענין גזירת ז' וכו'\u0004 כ\"כ בת\"ה מסברא והביא דבריו הרא\"ש בפרק אלו מגלחין:","\u0003ומ\"ש עוד שהשומע שמועה רחוקה א\"צ לנהוג כל דין אבילות וכו'\u0004 עד ומיהו בחדא סגי אהא דאיתא בפרק אלו מגלחין דר' חייא אתיא ליה שמועה רחוקה אמר ליה לשמעיה חלוץ לי מנעלי והולך כלי אחרי לבית המרחץ ש\"מ תלת ש\"מ אבל אסור בנעילת הסנדל וש\"מ שמועה רחוקה אינה נוהגת אלא יום אחד וש\"מ מקצת היום ככולו כתב הרמב\"ן בת\"ה ק\"ל מאי האי דקאמר אבל אסור בנעילת הסנדל כלומ' בשמועה רחוקה פשיטא אלא במאי נוהג יום אחד ונ\"ל דאינה נוהגת אלא יום אחד קאמר לומר שדיו מכל גזירות אבילות בחליצת מנעל וא\"צ שילך לביתו ויכפה מטותיו ויתעטף בראשו שהרי רבי חייא לא עשה אלא חליצת מנעליו ומיד הלך לבית המרחץ לא כפה ולא עטף וכן במלאכה ורחיצה וסיכה ותשמיש וקריאת התורה בכולן לא נהג כלום לפי שאין שעה אחת מתפרסמת עליו באיסור מש\"ה דייק דשמועה רחוקה כיון שקבל עליו אבילות בנעילת הסנדל דיו וכן הדין נמי במי שאין לו מנעלים ברגליו שמתעטף כאבל או כופה מטתו שעה א' ויוצא י\"ח ובודאי אם היה עוסק במלאכה או שהיה רוחץ וסך או קורא בתורה ובאת לו שמועה רחוקה הרי זה מפסיק שעה אחת משום אבילות וחוזר למה שבידו אבל מ\"מ אין יוצא י\"ח שמועה בהפסק זה עד שיעשה מעשה הניכר באבילות שיהא אבילות מתפרסמה עליו בכך כגון חליצת מנעל וסנדל ועטיפת הראש שהן מצות עשה שבאבילות אי נמי כפיית מטותיו שאף בהן יש צד מעשה כנ\"ל וכ\"נ שהיה רבי חייא לבוש תפילין בשעת שמועה זו שלא היה דרכו של אותו צדיק לילך בלא תפילין ואף על פי כן לא חלץ תפיליו כלל והטעם לזה לפי שאף בשעת אבילות מניח תפילין ואינו חולץ אלא ביום א' בלבד ולא תהא שמועה רחוקה חמורה מיום ב' של אבילות קרובה הלכך אם היה לבוש תפילין בשעת שמועה של אבילות רחוקה אינו חולץ אלא מתעטף ראשו וחולץ מנעל וסנדל ודיו עכ\"ל והביא הרא\"ש דבריו בפרק אלו מגלחין: כתבו נ\"י והמרדכי דאין מברין על שמועה רחוקה:","אין קורעין על שמועה רחוקה בפרק אלו מגלחין [שם:] פלוגתא דאמוראי ומשמע התם דהלכתא כמ\"ד אינו קורע וכן פסקו הפוסקים: ומ\"ש דעל אביו ואמו קורע לעולם הכי משמע התם בגמרא וכ\"כ הרמב\"ן שכן אמרו בירושלמי אמר ר' מונא וכי יש קריעה בלא איבול שכן על אביו ואמו אפילו אחר כמה חייב לקרוע והראב\"ד כתב דאפילו על אביו ואמו אינו קורע בשמועה רחוקה לפי שהיה מפרש סוגיא דגמרא בע\"א וכתב עליו הרמב\"ן דסוגיא משובשת היא בפירוש זה וסתר דבריו והרא\"ש ג\"כ דחה דברי הראב\"ד והעלה שכדברי הרמב\"ן עיקר וכן נראה מדברי הרי\"ף ז\"ל והרמב\"ם סתם דבריו בפ\"ז דאינו קורע בשמועה רחוקה ולא חילק בין אביו ואמו לשאר מתים ובודאי שדעתו לומר שאינו קורע בשמועה רחוקה אפילו על אביו ואמו שהרי הוא סובר דמי שלא היה לו חלוק בשעה שמתו אביו או אמו ואח\"כ נזדמן לו אינו קורע אלא עד שלשים יום. ולענין הלכה כיון שהרי\"ף והרא\"ש והרמב\"ן מסכימין לדעת אחת הכי נקטינן :","השומע שמועה בשבת או ברגל ולמ\"ש או רגל נעשית רחוקה אינו נוהג אלא יום אחד ברייתא פרק אלו מגלחין:","ומ\"ש בשם הרמב\"ן בת\"ה כ\"כ מסברא והביא דבריו הרא\"ש בפרק אלו מגלחין וכתב הרשב\"א שנשאל כיון דשבת עולה אפילו לתחלת ימי אבלות כדמשמע אהא דתניא ומודים חכמים כשחל ח' שלו בשבת ערב הרגל שמותר לגלח וכו' למה אמרו באה לו שמועה בשבת ולמ\"ש נעשית רחוקה דהא יום שבת נוהג אבילות ועולה מהמנין וכיון שכן הרי חל עליו אבילות ביום השבת שהוא יום ל' והרי היא קרובה והשיב דאע\"פ שעולה אפילו לתחלת ימי אבילות מ\"מ כיון שאין נוהג בו אלא דברים שבצינעא אינו גורם אבילות שאם שמע שמועה בשבת אין אומרים כיון שאבילות חל עליו בשבת ועולה תהא שמועה שבו כמו שחל עליו האבילות ביום ל' ויגרום למנות במ\"ש שא\"כ היה מה שהוא גורם חמור ממנו בו אין אבילות נוהג ומחמתו יהא אבילות נוהג אינו בדין שיהא חמור מה שיבא בגרמתו יותר ממנו:","\u0003וכתב בספר המצות השומע שמועה קרובה בשבת השבת עולה לו ליום אחד וכו'\u0004 עד סוף הסימן הכל בסמ\"ק כתבו סמ\"ג והגה\"מ בפ\"י בשם בה\"ג מי שבאה לו שמועה בשבת שבת עולה לו מן המנין וקורע באחד בשבת ומברכין ברכת אבילות מפני שהוא דברים של צינעא:","כתב ר\"י מת לו מת ערב הרגל שערב החג וחג ושמיני עצרת עולין למנין כ\"א יום וצריך לנהוג ט' ימים אחר החג להשלים ל' ולא ידע שמת עד שעברו י' ימים אחר הרגל ולפי המנין שמנינו כבר עברו ל' יום והוי שמועה רחוקה כתב בעל המאור שיש מן החכמים שנסתפקו בזה וכתבו דהו\"ל ספק אבילות וקי\"ל כדברי המיקל באבל והו\"ל שמועה רחוקה ולדעתי נ\"ל דהו\"ל שמועה קרובה שאין הדברים נראים שיעלה הרגל למי שלא באה לו עדיין שמועת המת כי לעולם אין דין מי שלא נהג אבלותו ולא שמע בו כדין מי שנהג הלכך ל\"ש ערב הרגל ולא שנא יום שמיני עצרת וכל כיוצא בו אינן נמנין לגבי שמועה אלא לעצמן ע\"כ דבריו והרבה ראיות ע\"ז עכ\"ל ונ\"י בפרק אלו מגלחין כתב כל זה ג\"כ וגם הרמב\"ן בת\"ה הסכים לדברי בעל המאור ז\"ל והכי נקטינן : כתב המרדכי במ\"ק מסקינן דיום אחד לפני הרגל קבר מתו בין אותו רגל יום אחד כגון עצרת ור\"ה ויה\"כ בין ישנה הרבה ימים עולה לו למנין י\"ד ואם קברו לפני סוכות עולה לו לכ\"א יום רק לשומע שמועה בר\"ה או בעצרת או בי\"כ נחלקו בו ה\"ר יוסף והריב\"ם לדברי ה\"ר יוסף עולה למנין ז' ולדברי ריב\"ם אין עולה כי אם יום אחד ואף ח' עצרת אינו עולה לז' אם לא קברו לפני הרגל בחול וכן הדין לשמועה קרובה עכ\"ל: וכתב עוד שכתב הר\"מ מאינגלטיר\"א הנני מסופק אם שמע שמועה קרובה בשבת ערב הרגל אם עולה אותו שבת למנין ז' כדאמרינן [מ\"ק כ.] אפילו שעה אחת דשמא היינו דוקא כי נהג כל אבילות אבל שבת נהי דעולה ליום אחד היכא דגררתו חיה או הרגוהו לסטים ונתייאש מלבקש בשבת מ\"מ לאו דין חול גמור משוית ליה מדאמרינן שמע שמועה קרובה בשבת ולאחר שבת נעשית רחוקה ואינה נוהגת אלא יום אחד וטעמא הואיל ושמע ביום שאינו יכול להתאבל כאילו שמע אחר השבת ע\"כ: ונראה לר\"מ דכיון דתנן [שם יט.] השבת עולה ואינה מפסקת רגלים מפסיקים ואינם עולים אע\"ג דתרוייהו שוין לענין אבילות דתרוייהו דברים של צינעא נוהג ולא של פרהסיא ואפ\"ה תנן השבת עולה והרגלים אינם עולים א\"כ עולה לכל דבר ולקולא אמרינן דעולה ולא לחומרא כגון שמע שמועה קרובה בשבת ולמ\"ש נעשית רחוקה ושוה לרגל לקולא ולימות החול לקולא ואח\"כ מצאתי כדבריו בתוס' הרי\"ב כ\"ה במרדכי וכ\"כ הגה\"מ בפ\"י: וכתב עוד המרדכי שם והגה\"מ מי שמת לו מת ולא נודע לו אין חובה שיאמר לו ואפילו באביו ואמו וע\"ז נאמר (משלי י') מוצא דבה הוא כסיל מיהו אם שואל עליו אין לו לשקר ולומר חי הוא שנאמר (שמות כג) מדבר שקר תרחק והביא ראיה לדבר וכתבו הגה\"מ פ\"ו שרש\"י פסק שמותר להזמינו לסעודת אירוסין ונישואין וכל שמחה כיון שאינו יודע ועוד כתבו הגה\"מ פ\"ג והמרדכי בסמ\"ק מי שהתפלל כבר ערבית ועדיין הוא יום ולא נראו כוכבים נראה דמונה מיום מחר ואותו יום אינו עולה לו וטעמא דתרי קולי דסתרי אהדדי לא עבדי' דמאחר שכבר התפלל ערבית ועשאו לילה אל תעשהו יום וכבר כתבתי זה בס\"ס שע\"ה: כתב הרמב\"ן בת\"ה בשם הרי\"ץ גיאת מדאמרינן במעשה דרבי חייא דא\"ל דאביו ואמו אינן קיימין וא\"ל לשמעיה חלוץ לי מנעלי והוליך כלי אחרי לבית המרחץ שמעינן דמי ששמע ב' שמועות רחוקות ביום אחד אינו נוהג עליהן אלא יום א' היו קרובות או שמתו לו ב' מתים כא' מונה לשניהם כאחד ל' וז' שמע לזה היום ולזה למחר מונה לשני מיום שמועה שלו ז' ול' עכ\"ל :"],["\u0003השומע שמת לו מת וכו'\u0004 בפ' ואלו מגלחין (מועד קטן דף כ') תנו רבנן שמועה קרובה נוהגת שבעה ושלשים שמועה רחוקה אינה נוהגת אלא יום א' איזו היא קרובה ואיזו היא רחוקה קרובה בתוך שלשים רחוקה לאחר שלשים דר\"ע וחכ\"א אחת קרובה ואחת רחוקה נוהגת ז' ול' ארבב\"ח א\"ר יוחנן כל מקום שאתה מוצא יחיד מיקל ורבים מחמירין הלכה כרבים חוץ מזו שאע\"פ שר\"ע מיקל וחכמים מחמירין הלכה כר\"ע דאמר שמואל הלכה כדברי המיקל באבל ומ\"ש דביום ל' דינו כשומע בתוך ל' כ\"כ הרי\"ף בשם בעל הלכות ודלא כמי שהורה דדינו כשומע לאחר ל' וכן פסקו הפוסקים כהרי\"ף:","\u0003ומ\"ש ואם שמע מיום שלשים וכו'\u0004 הכי אסיקנא שם בעובדא דרב ורבי חייא דא\"ל אייבו קיים וכו' דשמועה רחוקה דאינה נוהגת אלא יום אחד אפי' מקצת היום ככולו:","ומ\"ש ל\"ש שמע ביום או בלילה פי' לענין ל' שמע בלילה חשוב ככל היום כדלעיל סוף סי' שצ\"ה: ומ\"ש ואפילו שמע על אביו ועל אמו שם בעובדא דרב חיננא אתיא ליה שמועה דאבוה מבי חוזאי וכו':","\u0003ומ\"ש וכתב הרמב\"ן והני מילי לענין גזירת שבעה וכו'\u0004 כלומר הא דשמועה רחוקה אינו נוהג אלא שעה א' אפי' באביו ואמו היינו דוקא לענין גזירת שבעה כגון נעילת הסנדל ורחיצה וכיוצא בו דברים שגזרו על שאר אבל שאסור בהם תוך ז' התם הוא דא\"צ לנהוג אלא שעה אחת. ודיו בחליצת הסנדל כמ\"ש בסמוך לענין גזירת שלשים וכו' פי' דברים שגזרו על שאר אבל תוך ל' דהיינו גיהוץ וכו' עד ובגיהוץ עד שיגיע הרגל ויגערו בו והוא ע\"פ דברי הרמב\"ן שהסכים הרא\"ש עמהם הביאם רבינו בסוף סימן שפ\"ט:","ומ\"ש לפיכך אם באת לו שמועה על אביו ועל אמו לאחר י\"ב חודש אינו נוהג אלא יום אחד אף בדין ל' פירוש לאו דוקא יום אחד אלא אפילו שעה אחת כדמוכח בעובדא דלעיל דמקצת היום ככולו: ומ\"ש וכתב עוד שהשומע וכו' כך הוכיח הרב מהך עובדא דרב ורבי חייא ומביאו ב\"י:","\u0003אין קורעין על שמועה רחוקה וכו'\u0004 כך פסק הרמב\"ם בסת\"ה ריש דף ע\"ט אבל בפירש\"י ותוס' משמע דהכי קמיבעיא ליה לשם [בדף כ'] היכא דשמע שמועה קרובה בשבת ולמ\"ש נעשה רחוקה דאינו נוהג אלא יום אחד קורע או אינו קורע אלמא דוקא בכה\"ג קמיבעיא ליה לפי שהיה חייב לקרוע בשעת שמועה אם היה חול אבל בשמועה רחוקה ובחול פשיטא דאינו קורע ואפי' על אביו ואמו אינו קורע וכתבו עוד התוס' שכ\"כ רש\"י בתשובה והוא דעת הראב\"ד והרמב\"ם אבל הב\"י הסכים לדברי רבינו שהם כהרי\"ף והרא\"ש והרמב\"ן שעל אביו ואמו קורעים אף על שמועה רחוקה דכך מפורש בירוש' והכי נהגי עלמא:","\u0003השומע שמועה בשבת או ברגל וכו'\u0004 ברייתא שם לענין שבת ומימרא דר' יוסי בר אבין לענין רגל ומ\"ש בשם הרמב\"ן דבשבת ורגל אסור בדברים של צינעא נראה דכל יום השבת אסור ואע\"ג דלר' יחיאל בסמוך סגי במקצת היום בדברים שבצינעא היינו כשחל יום ז' בשבת דאחר מקצת יום אין כאן אבילות אבל כאן בשמע שמועה בשבת ולמ\"ש נעשה רחוקה דצריך לנהוג שעה אחת אבילות אחר השבת פשיטא שכל יום השבת נוהג דברים שבצינעא ועוד נראה דאפילו במת לו מת בא' בשבת דיום ז' הוא שבת אסור בדברים שבצינעא כל יום השביעי דלא כרבי' יחיאל והוא דהא דאיתא בפרק אלו מגלחין דמקצת היום הוי ככולו אין זה אלא בחול דכיון דעושה מעשה אבילות במקצת יוצא י\"ח באותו מקצת הניכר משום אבילות אבל ביום שבת שאין נוהג בו אלא דברים שבצינעא ואינו עושה מעשה שניכר משום אבילות לא יצא י\"ח ספירה ביום השבת דבכל יום ויום מז' הימים צריך שיעשה מעשה הניכר משום אבילות כדכתב הרמב\"ן אפילו לגבי שמועה רחוקה בסמוך דקיל דאינו נוהג אלא שעה אחת והסכים עמו הרא\"ש ורבינו כ\"ש באבילות שבעה דחמיר דאינו יוצא י\"ח בשביעי אלא בנוהג שעה אחת אבילות במעשה הניכר משום אבילות וכיון דבשבת אינו עושה מעשה צריך לנהוג כל היום דברים שבצינעא ולכן אין לקרות לאבל לס\"ת בשביעי שלו בשבת אפילו במנחה בשבת דצריך לנהוג דברים שבצינעא כל יום השבת כיון דאינו נוהג אבילות במעשה הניכר משום אבילות ועוד נראה דאפשר דאף רבינו יחיאל מודה בקריאת ס\"ת דלא אמר הרב דבמקצת היום סגי אלא בתשמיש המטה וכיוצא בדברים דאף כשאינו נוהג אבילות בשאר היום הוי נמי בצינעא ואין שם פרהסיא כלל לפיכך יוצא במקצת היום אבל לקרותו לס\"ת מודה אף רבינו יחיאל כיון שלא עשה מעשה שניכר בו משום אבילות במקצת היום אין לו לעשות שום מעשה שניכר בו שאינו נוהג אבילות אלא כל היום יהא הדבר בצינעא ועוד הארכתי בתשובה בס\"ד. העולם נוהגים תוך ז' שיושבים במ\"ש לאחר הבדלה על הארץ וחליצת הסנדל ונלאו החכמים למצוא טעם לדבר ולפע\"ד יש לתת טעם והוא כמ\"ש בסמוך דתופסים דברי הרמב\"ן בשומע שמועה בשבת ולמ\"ש נעשה רחוקה דאף ע\"ג דנוהג בשבת דברים שבצינעא לא נפטר בזה דצריך לעשות במ\"ש מעשה שניכר בו משום אבילות וה\"נ כיון שלא עשה בשבת מעשה שניכר בו משום אבילות לא יצא י\"ח וצריך לנהוג אבילות במ\"ש שעה אחת בדבר שניכר בו משום אבילות ולפ\"ז אף בחל ז' שלו בשבת צריך לנהוג אבילות שעה אחת במ\"ש לאחר הבדלה כיון שלא נהג אבילות כל יום השבת במעשה שניכר בו משום אבילות וכמדומה שכך נהגו העולם ולפי זה ודאי צריך הוא לנהוג אבילות בדברים שבצינעא בכל היום אף בתשמיש המטה דאם לא ינהוג אלא שעה אחת תמה על עצמך היאך הוא חוזר לאבלותו במ\"ש לאחר הבדלה וכן כתב הרמב\"ן בויכוחו עם הגדולים בדין מקצת היום ככולו עיין בספר ת\"ה (דף ע' ע\"ב) והכי נקטינן לנהוג דברים שבצינעא כל יום השבת כשחל יום ז' שלו בשבת ולנהוג שעה אחת אבילות במעשה לאחר הבדלה: כתב בהגה\"ת ש\"ע מצוה להתענות יום שמת בו אב או אם ומתענין יום המיתה ולא יום הקבורה אם לא מי שהיה אצל הקבורה ולא אצל המיתה עכ\"ל מיהו בת\"ה סימן רצ\"ג ובתשובת מהרי\"ל סי' ז' משם האגודה וכן בדרשות מהרי\"ל ה' שמחות כתב בסתם דמתענין יום המיתה ולא יום הקבורה ולא חילק וכ\"כ בספר חסידים סימן תשי\"ב וז\"ל מהר\"י בדין בתשובה וששאלתם מתי מתענין יום המיתה או יום הקבורה דע כי יום המיתה מתענין וה\"א בהדיא בס' חסידים ומפרש שם הטעם לבקש תשובה וכפרה להציל עצמו מאותה שעה שאירע לו כך וכך דאיתרע ליה מזלא בההיא יומא וכן כתב הרוקח דמתענין ביום שמת בו אב ואם דתניא כיום שמת בו אבא וכיום שנהרג גדליה וכו' ובספר אגודה איתא גבי קדיש אזלינן בתר יום המיתה ולא בתר יום הקבורה ויש מחלקים כשהוא אצל הקבורה מתענין יום הקבורה וכשאינו אצל הקבורה מתענין יום המיתה ולאו מילתא הוא כלל אלא כדפרי' לעיל עכ\"ל מהרי\"ב ואפשר דבהיה גם כן אצל המיתה קאמר דאין מתענין אלא יום המיתה וה\"ה כשלא היה לא אצל המיתה ולא אצל הקבורה אבל בהיה אצל הקבורה ולא אצל המיתה מודה דמתענה יום הקבורה משום דאותו יום חשוב היה לו יום מר טפי מיום המיתה וכמ\"ש הרב בהגה\"ת ש\"ע בקבלה מפי חכם זקן: כתב מהרי\"ק שורש ל\"א השני אם אירע יום שמת בו אב או אם בשבת או בר\"ח נדחה עד אחר שבת או אחר ר\"ח ולא נהגו כמותו אלא אין מתענין כלל אבל אומרים קדיש וגם נותנים נר לב\"ה כמנהג כל יאר צייט: כתב בת\"ה בסימן רצ\"ד דאם מת באדר העיקר להתענות באדר הראשון וכן פסק בתשובת מהרי\"ל סימן ל\"א וסימן ק\"ה וכ\"כ במהרי\"ל בה' שמחות שלו ומהרש\"ל כתב ויש חולקים ואומרים אדרבה אדר השני לעולם עיקר ונהגו להתענות בשניהם וזהו פשוט שאם מת בראשון או בשני שכך מתענין בשנה המעוברת עכ\"ל שוב מצאתי כתוב ע\"ש מהרי\"ל שמתענין בשניהם כלומר דאף על פי דהורה דהראשון עיקר מ\"מ העולם מתענין בשניהם וכדכתב מהרש\"ל אבל בסוף ספר מהרי\"ו כתב ע\"ש מהרי\"ל שהורה להתענות בשניהם ושכך הורה מהרי\"ו אחריו וכתב בספר חסידים סימן תשי\"ב וז\"ל לאחד היה מת אביו באדר הראשון והיה מתענה באותו יום שמת אביו ובשנה פשוטה היה מתענה בשבט ואדר מספק עכ\"ל ונראה דאישתמיטתיה לההוא חסיד הא דאיתא בפ\"ק דר\"ה [דף ט\"ו] דקמיבעיא ליה רבא מרב נחמן ואמרי ליה רבי יוחנן מר' ינאי היתה שנה מעוברת מהו פירוש אימתי ר\"ה שבט הסמוך לטבת או אדר הראשון שהוא במקום שבט ופשטינן אמר ליה הלך אחר רוב שנים מי ששמו שבט אלמא דאין ספק באדר הראשון דפשיטא דאינו שבט והכי נקטינן דא\"צ להתענות אלא באדר:"]],["\u0010c0\u0011\u0010y0\u0011תניא המלקט עצמות אביו הרי זה מתאבל עליהן כל היום כולו ולערב אין מתאבל עליהן אפילו צרורות לו בסדינו \u0010c1\u0011\u0010y1\u0011כתב הר\"מ מרוטנבורק כל זמן שלא נקברו חל עליו כל דין אנינות לאסור בשתיית יין ואכילת בשר ואחר שנקבר חל עליו כל דין אבילות עד הערב וא\"א הרא\"ש ז\"ל כתב שאין עליו דין אנינות כלל אלא מיד חל עליו דין אבילות אפילו קודם שקברום: \u0010y2\u0011היה עומד ומלקט וחשכה לו מותר ביום שלאחריו לפיכך אין מלקטין אותם סמוך לחשיכה. \u0010y3\u0011לאו דוקא עצמות אביו אלא על כל הקרובים נמי מתאבל ביום ליקוט עצמותיהן ככל הדברים הנוהגים באבל בקריעה ובכל דיני אבילות: כל שקורעין עליו בשעת מיתתו קורעין עליו בשעת ליקוט עצמות \u0010y4\u0011אין עומדין עליהן בשורה ואין אומרים עליהן ברכת אבלים אבל אומרים עליהן תנחומין לעצמו ואין מברין עליהן בחבר עיר אבל מברין עליהן לעצמו \u0010y5\u0011תניא ליקוט עצמות אין אומרים עליהם קינה ונהי וא\"א עליהן ברכת אבלים ותנחומי אבלים אבל אומרים דברים מה הן דברים רבנן אומרים קילוסין פירוש מקלסין המת ומספרים בשבחו לפי מה שהוא וי\"א קילוסין להקב\"ה שהוא ממית ומחיה \u0010y6\u0011כתב הרמב\"ן ז\"ל מותר ללקטן במועד ואינו מתאבל עליהן כלל מפני ששמחת הרגל עליו אבל הרמב\"ם כתב אין מלקטין עצמות אביו במועד ואין צריך לומר עצמות שאר קרוביו \u0010y7\u0011ירושלמי תניא אין שמועה לליקוט עצמות אמר רבי חגי והוא ששמע למחר אבל אם שמע בו ביום יש שמועה לליקוט עצמות פירוש אם שמע שלקטו עצמות אביו היום מתאבל עליהן אף על פי שלא היה שם \u0010y8\u0011תניא אין מפרקין את העצמות ואין מפסיקין את הגידין אלא אם כן נפרקו העצמות מעצמן ונפסקו הגידין: כל העצמות אדם מלקט חוץ מעצמות אביו ואמו דברי ר\"ע פירוש לא ילקטם בידו אלא אחרים ילקטו לו ר' יוחנן בן נורי אומר ליקוט עצמות אינו אלא משיכלה הבשר כלה הבשר אין הצורה ניכרת בעצמות ואע\"ג דהלכה כר\"ע מחבירו הכא מסתברא טעמא כרבי יוחנן: מלקט עצמות שני מתים כאחד בראש אפרסקא מכאן ובראש אפרסקא מכאן דברי ר' יוחנן בן נורי רבי עקיבא אומר סוף אפרסקא להתעכל וסוף עצמות להתערב אלא מלקטן ונותנם בארזים פי' סוף אפרסקא להתעכל ונמצא עצמות ב' מתים מתערבים אלא מלקטן ונותנן כל א' לעצמו בארון של ארזים א\"ר אליעזר בר צדוק כך אמר לי אבא בשעת מיתתו מתחלה קברוני בבקעה ולבסוף לקטו עצמותי ותנם בארזים ואל תלקטם אתה בידך שלא יהו בזויין בידך וכן עשיתי לו נכנס יוחנן וליקט ופירש עליהן את אפרסקא ונכנסתי וקרעתי עליהן ופירשתי עליהן את הסדין וכשם שעשה אבא לאביו כך עשיתי לו: תניא המלקט עצמות והמשמר עצמות והמוליך אותם ממקום למקום פטור מק\"ש ומן התפלה ומן התפילין ומכל מצות האמורות בתורה בין בחול בין בשבת לא שנא עצמות של קרובים לא שנא של רחוקים בין אם הוא בספינה או בדרך ואפילו אם הם מלקטין רבים ואם רצה להחמיר על עצמו לא יחמיר מפני כבוד עצמות \u0010y9\u0011המוליך עצמות ממקום למקום ה\"ז לא יתנם בשק ולא בדסקיא ויניחם ע\"ג חמור וירכב עליהן מפני שנוהג בהן מנהג בזיון ואם היה מתיירא מפני הגנבים והלסטין מותר \u0010y10\u0011תניא היה ר\"מ אומר טוב ללכת אל בית אבל מלכת אל בית משתה באשר הוא סוף כל האדם והחי יתן אל לבו דברים של מיתה דיספד יספדוניה דקבר יקברוניה דיטעון יטענוניה דדלאי ידלוניה. היה \u0010y11\u0011\u0010y12\u0011\u0010y13\u0011ר\"מ אומר גדול השלום שלא ברא הקב\"ה מדה יפה מן השלום שנתנה לצדיקים שבשעה שנפטר האדם מן העולם ג' כתות של מלאכי השרת מקדימין אותו בשלום הראשונה אומרת יבא בשלום והשנייה אומרת ינוחו על משכבותם והג' אומרת הולך נכוחו ולא דיין לצדיקים שמיתתן בידי הכבוד שנאמר וכבוד ה' יאספך אלא שמקלסין לפניו יבא שלום יבא שלום :",["תניא המלקט עצמות אביו ואמו ה\"ז מתאבל עליהם כל היום ולערב אין מתאבל עליהם אפילו צרורות לו בסדינו בפ\"ק דמ\"ק [ח.] ופירש\"י אפילו צרורין לו בסדינו שאינו מלקטן ואינו רואה אותן ה\"ז מתאבל עליהם כל זמן שלא נקברו והתוס' כתבו דיותר נראה לפרש דה\"ק אפי' צרורים לו בסדינו מתאבל לערב. וכתב נימוקי יוסף בסוף מ\"ק מתאבל לאו דוקא בנעילת הסנדל ושאר דברים הנהוגים באבל אלא מתאונן ואסור לאכול קדשים שהם ראוים ליאכל בשמחה וזה כשהוא רואה אביו ששב עפר ואפר חם לבו בקרבו ודואג עליו. ואפי' צרורים. לא מיבעיא אם נקברו אותן עצמות שאינו אונן עוד עליהם אלא אותו היום בלבד כדין אבילות של תורה שאינו אלא יום קבורה בלבד אלא אפילו צרורים בסדינו שלא נקברו לא גזרו חכמים להאסר עוד בקדשים עכ\"ל ואין זה דעת הפוסקים שכתבו דין זה ואם כדבריו כיון דלא נפקא לן מידי בזמן הזה דלית לן קדשים לא הוה ליה לכתבו אלא ודאי מתאבל ממש קאמר וכ\"כ רבינו ירוחם אותו יום נוהג כאבל בעטיפת הראש וכפיית המטה ונעילת הסנדל ותשמיש המטה ורחיצה וסיכה וכל מה שאסור באבל:","ומ\"ש רבינו בשם הר\"מ וכן מ\"ש בשם הרא\"ש בפרק אלו מגלחין בפסקי הרא\"ש וכתבתיו בסימן שע\"ה וכתב רבי' ירוחם מ\"מ ראוי לסמוך על הר\"מ כי תלמידו הוא החולק עליו כמספק:","היה עומד ומלקט וחשכה לו מותר ביום שלאחריו לפיכך אין מלקטין אותו סמוך לחשיכה כלומר כדי שלא יהא נמצא שלא נתאבל על ליקוט עצמות אביו ברייתא באבל רבתי פי\"ב וכתבה הרמב\"ן בת\"ה והרא\"ש בפ\"ק דמ\"ק:","\u0003ולאו דוקא עצמות אביו וכו'\u0004 כן כתב הרמב\"ן בת\"ה והרא\"ש בפ\"ק דמ\"ק דעל כל הקרובים נמי מתאבל ביום ליקוט עצמותיהם ככל הדברים הנוהגים באבל בכפיית המטה ועטיפת הראש ונעילת הסנדל ותשמיש המטה ורחיצה וסיכה דתניא באבל רבתי כל שקורעים עליו במיתתו קורעים עליו בשעת ליקוט עצמות וכל שאינו מתאחה בשעת מיתתו אין מאחה בשעת ליקוט עצמות:","אין עומדים עליהם בשורה וכולי ברייתא באבל רבתי פרק י\"ב כתבה הרמב\"ן בת\"ה והרא\"ש בפ\"ק דמ\"ק אלא שמ\"ש רבינו אבל מברין עליהם לעצמו כתוב שם בתוך ביתו במקום לעצמו:","\u0003תניא ליקוט עצמות א\"א עליהם קינה ונהי וכו'\u0004 עד רבנן אומרים קילוסין ירושלמי כתבו הרי\"ף בסוף מ\"ק והרמב\"ן בת\"ה והרא\"ש בפ\"ק דמ\"ק והרמב\"ם בפרק י\"ב:","כתב הרמב\"ן מותר ללקטן במועד ואינו מתאבל עליהם כלל וכולי בת\"ה ומ\"ש בשם הרמב\"ם הוא בפי\"א מהלכות אבל וטעם מחלוקתם תלוי במאי דתנן בפ\"ק דמ\"ק [ח:] ועוד אמר רבי מאיר מלקט אדם עצמות אביו ואמו מפני ששמחה הוא לו רבי יוסי אומר אבל הוא לו ורמי בגמרא אר' מאיר מדתניא המלקט עצמות אביו ואמו ה\"ז מתאבל עליהם כל היום ומשני מפני ששמחת הרגל עליו כלומר הרבה הוא עוסק בשמחת הרגל ואינו מצטער בליקוט עצמות אביו ואמו וסובר הרמב\"ן דכיון דמהדר תלמודא לפרושי מילתיה דר\"מ משמע דהלכתא כוותיה והרמב\"ם סובר דאין זה כדאי לבטל כלל שבידינו ר\"מ ור' יוסי הלכה כר\"י:","\u0003ולענין הלכה נקטינן כהרמב\"ם:\u0004 ","\u0003ירושלמי תניא אין שמועה לליקוט עצמות אמר ר' חגי והוא ששמע למחר וכו'\u0004 כתבו הרא\"ש פרק קמא דמ\"ק והרמב\"ן בת\"ה:","\u0003תניא אין מפרקין את העצמות וכו'\u0004 עד מפני כבוד העצמות הכל באבל רבתי פי\"ב וכתבוהו הרמב\"ן בת\"ה והרא\"ש בפ\"ק דמ\"ק:","המוליך עצמות ממקום למקום וכולי ברייתא בפרק מי שמתו (ברכות יח.) וכתב הרא\"ש אהא דקתני וירכב עליהם אבל אם מפשילו לאחוריו על החמור ש\"ד:","תניא היה ר\"מ אומר טוב ללכת אל בית אבל וגומר והחי יתן על לבו דברים של מיתה דיספד יספדוניה וכו' בסוף מ\"ק [כח:] ופ' התדיר [עב.] ופי' רש\"י דיספד יתן אל לבו שאף הוא יספדוהו ואל ירע לו אם נהג כן דידל הרים קולו בבכי ובמספד ובסוף מ\"ק פריש דידל ידלוניה כלומר הספיד לאחרים:","\u0003תניא היה רבי מאיר אומר גדול השלום וכו'\u0004 עד סוף הסימן וההיא דג' כתות של מלאכי השרת מקדימים אותו בשלום וכו' איתא נמי בגמרא פרק הנושא (כתובות קג.) כתב בתשב\"ץ אומר קדיש על אמו בחיי אביו והר\"מ אומר שאין אומר קדיש על אמו בחיי אביו אם אביו מקפיד אפי' עשתה לו אמו צוואה לומר עליה קדיש מיהו נהגו העולם לומר לעולם קדיש אפי' בחיי האב וכתב עוד שיש להתענות ולומר קדיש בכל שנה ביום שמת אביו ובשנה מעוברת בשנה הראשונה יתענה ויאמר קדיש באדר ראשון ובשאר שנים באדר שני ונראה דטעמו משום דסוף שנה ראשונה הוי לסוף י\"ב חדש כדאמרינן דמשפט רשעי ישראל בגיהנם י\"ב חדש ולא אמרו שנה הילכך י\"ב חדש מנינן ובשאר שנים תלי בפלוגתא דר\"מ ור\"י בפרק קונם יין וס\"ל דהלכה כר\"מ דאמר דכותבין בשטרות אדר הראשון אדר הראשון והשני אדר סתם כותבין דאיהו סתם אדר מיקרי ובת\"ה כתוב שנשאל על מי שנפטרו הוריו באדר בשנה פשוטה כשיגיעו שנות העיבור באיזה אדר יצום ויאמר קדיש וברכו בראשון או בשני והשיב יראה דיעשה בראשון וכל שכן אם נפטר בשעת העיבור בראשון שיעשה לעולם בראשון אמנם בהא מודינא דאם נפטר בשנת העיבור בשני שיעשה לעולם בשני וכתב עוד חלוקים רבים בדבר זה יש מתענין ואומרים קדיש וברכו ביום המיתה ויש ביום הקבורה והוא ז\"ל הכריע דביום המיתה שפיר טפי: \u0005ב\"ה וכתב מהרי\"ק בשורש ל\"א שהרגיל להתענות ביום שמת אביו ואירע אותו יום בשבת ובר\"ח יש לדחותו למחר וראיה לדבר מצום גדליה:\u0006","מ\"כ אחד מדיורי העיר היה אומר קדיש עבור אמו שמתה בעירו ואחד שכיר מלמד בעיר והיה אומר קדיש עבור אמו אבל לא מתה בעיר ולא היתה דירתה בעיר ואחת היתה זקנה שנח נפשה בעיר ולא עזבה בן ולא בת וקרוביה השכירו אחד שיאמר קדיש עבור נפשה וע\"כ שלחו למה\"ר יוחנן נ\"ע וזה טופס תשובתו ראיתי דבריך על דבר הקדיש יודע לו כי אין הענין תלוי בפרעון עולי העיר אם אין לו ודר בעיר אף ע\"פ שדר בשכירות נקרא בן חלק ואם דר בעיר אע\"פ שהוא בשכירות יהיה לו לפי הענין חלק ואם שום אחד מהקדישים הוא בעד מת שמת בעיר יש לו חלק מכח המת ומכחו ואם דר בעיר ואפי' שכיר חלק אחד והם שני חלקים ומי שאין כלל דר ואין המת מן העיר אין לו חלק כלל כן אמרתי בלבי כדין ונהגתי במקומי נאום המדבר יוחנן בן מהר\"ר מתתיה דטריו\"ש ז\"ל: וגם בתפלה שאומר בשביל כפרת אביו וחילוקים בדין הקדיש זה נמצא במהרי\"ח שורש מ\"ד וגם באגור עיין עליהם:"],["\u0003תניא המלקט עצמות וכו'\u0004 בפרק קמא דמ\"ק [דף ח'] תניא המלקט עצמות אביו ואמו ה\"ז מתאבלים עליהם כל היום ולערב אין מתאבל עליהם ואמר רב חסדא אפילו צרורין לו בסדינו ופירש רש\"י אפי' צרורין לו בסדינו שאינו מלקטן ואינו רואה אותן ה\"ז מתאבל כל זמן שלא נקברו עכ\"ל וקצת קשה דלאיזה צורך אמר צרורין לו בסדינו אלא הוה ליה למימר רבותא טפי אפילו צרורין ומונחין ולא נקברו ואצ\"ל בצרורין בסדינו ולכך כתבו התוס' דניחא טפי לפרש דאסיפא קאי דאפילו צרורין לו בסדינו אינו מתאבל לערב ומלשון רבינו נראה דהסכים לדברי התוספות והכי משמע מדברי הרמב\"ם פי\"ב דאבל:","\u0003כתב רבינו מאיר כל זמן שלא נקברו וכו'\u0004 כצ\"ל וכן כתב הרא\"ש בשמו פרק אלו מגלחין (סוף דף מ\"א) ומה שנמצא בספרי רבינו כתב הרמב\"ם הוא ט\"ס וכך מבואר בדברי ב\"י דהנוסחא הנכונה היא רבינו מאיר ע\"ש: המברכים ברכת המזון בבית האבל מזמנין ואומרים נברך מנחם אבלים שאכלנו משלו ועונין ברוך מנחם אבלים שאכלנו משלו ובטובו חיינו והמברך חוזר ואומר ברוך מנחם אבלים שאכלנו משלו ובטובו חיינו ברוך אתה ה' אלהינו מלך העולם הזן את העולם וכו' עד ולא נכלם לעולם ועד ואומר נחם ה' אלהינו את אבילי ציון ואת אבילי ירושלים ואת האבילים המתאבלים באבל זה נחמם מאבלם ושמחם מיגונם כדבר שנאמר כאיש אשר אמו תנחמנו כן אנכי אנחמכם ובירושלים תנוחמו ברוך אתה ה' מנחם ציון ובונה ירושלים ואומר ברכה רביעית ברוך אתה ה' אלהינו מלך העולם האל אבינו מלכנו וכו' עד הוא מטיב הוא ייטיב לנו אל אמת שופט צדק לוקח נפשות במשפט שליט בעולמו לעשות בו כרצונו כי כל דרכיו משפט ואנחנו עמו ועבדיו ובכל אנחנו חייבים להודות לו ולברכו גודר פרצות ישראל הוא יגדור הפרצה הזאת מעלינו ומעל אבל זה לחיים ולשלום הוא גמלנו הוא גומלנו הוא יגמול לנו וכו' הרחמן הוא יגדור את הפירצה הזאת מעמו ומעל כל ישראל לחיים ולשלום הרחמן הוא ישמח את האבלים המתאבלים שיהיו שמחים וטוב לב הרחמן הוא ינחם האבלים בנחמות ירושלים עם כל ישראל עושה שלום וכו'. ונותן הכוס לאבל ולא ישתו אחר האבל מכוסו אלא מוזגין כוס אחר ומברכין בפה\"ג והאבל שותה מכוסו והן שותין מכוסן ושמחים מיגונם וכן הוא ברוקח ועיין לעיל סימן שע\"ח שע\"ט: בלע המות לנצח וגו'"]]]};
